INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f789e659-88bf-5571-a906-6fc6131163e3', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 1, 1, 'የምድያም ካህን የሙሴ አማት ዮቶር እግዚአብሔር ለሙሴና ለሕዝቡ ለእስራኤል ያደረገውን ሁሉ፥ እግዚአብሔርም እስራኤልን ከግብፅ እንደ አወጣ ሰማ።'),
  ('da8f037d-ab3b-5049-a96d-8b95d17deb74', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 2, 2, 'በዚያ ጊዜ የሙሴ አማት ዮቶር ትቶአት የነበረውን የሙሴን ሚስት ሲፓራን፥ ሁለቱንም ልጆችዋን ወሰደ።'),
  ('26661ce1-507e-541c-a8e6-aba6f36e7b2a', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 3, 3, 'የአንደኛው ስም ጌርሳም ነበረ፤ አባቱ “በሌላ ሀገር ስደተኛ ነበርሁ” ብሎአልና፤'),
  ('cdbe597f-a06d-5fa9-ab02-6aa77504587d', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 4, 4, 'የሁለተኛውም ስም አልዓዛር ነበረ፤ “የአባቴ አምላክ ረዳኝ፤ ከፈርዖንም እጅ አዳነኝ” ብሎአልና።'),
  ('cc0f4068-4a0d-5efa-a855-96f436185c97', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 5, 5, 'የሙሴ አማት ዮቶርም ከልጆቹና ከሚስቱ ጋር በእግዚአብሔር ተራራ አጠገብ በምድረ በዳ ወደ ሰፈረ ወደ ሙሴ መጣ።'),
  ('974cb0ec-0d97-53ab-a036-62b2c3770f8e', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 6, 6, 'ሙሴንም፥ “እነሆ፥ አማትህ ዮቶር፥ ሚስትህም ከእርስዋም ጋር ሁለቱ ልጆችህ መጥተውልሃል” አሉት።'),
  ('465b42bd-2ba8-5077-a35b-a6619b786a35', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 7, 7, 'ሙሴም አማቱን ሊገናኝ ወጣ፤ እጅ ነሣው፤ ሳመውም፤ እርስ በርሳቸውም ሰላምታ ተሰጣጡ፤ ወደ ድንኳኑም ገቡ።'),
  ('11bc7cb3-d350-5d0e-aa72-c6420d310c68', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 8, 8, 'ሙሴም እግዚአብሔር በፈርዖንና በግብፃውያን ላይ ስለ እስራኤል ያደረገውን ሁሉ፥ በመንገድም ያገኛቸውን ድካም ሁሉ፥ እግዚአብሔርም እንደ አዳናቸው ለአማቱ ነገረው።'),
  ('8597148f-a5f4-569e-aedd-8a8ea2f6fc3b', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 9, 9, 'ዮቶርም እግዚአብሔር ያደረገላቸውን ቸርነት ሁሉ፥ ከግብፃውያን እጅና ከፈርዖን እጅ እንደ አዳናቸው ሰምቶ በሁሉ አደነቀ።'),
  ('7b56bcca-1485-5063-a73e-c61069782f35', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 10, 10, 'ዮቶርም፥ “ከግብፃውያን እጅና ከፈርዖን እጅ ሕዝቡን የአዳነ እግዚአብሔር ቡሩክ ነው።'),
  ('187994e1-112a-5c6c-a072-420b292be72e', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 11, 11, 'እግዚአብሔርም ግብፃውያን ከሚመኩባቸውና ከሚገዙላቸው አማልክት ሁሉ እንዲበልጥ አሁን ዐወቅሁ” አለ።'),
  ('08ebd2af-2799-5381-a5b3-3eebc7c09972', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', 'de33e28a-ed27-50d2-a43a-14b90ca8b8bf', 12, 12, 'የሙሴ አማት ዮቶርም የሚቃጠል መሥዋዕትንና ሌላ መሥዋዕትን ለእግዚአብሔር ወሰደ፤ በእግዚአብሔርም ፊት ከሙሴ አማት ጋር እንጀራ ሊበሉ አሮንና የእስራኤል ሽማግሌዎች ሁሉ መጡ።'),
  ('7455f744-7fd2-5924-a0dd-e52e50c31ad6', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 1, 13, 'እንዲህም ሆነ፤ በነጋው ሙሴ በሕዝቡ ሊፈርድ ተቀመጠ፤ ሕዝቡም በሙሴ ፊት ከጥዋት እስከ ማታ ድረስ ቆመው ነበር።'),
  ('2ca7549c-3d14-52e2-a9c5-2b4d390d445c', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 2, 14, 'ዮቶርም ሙሴ በሕዝቡ ላይ የሚያደርገውን ሁሉ አይቶ እንዲህ አለው፥ “ብቻህን ተቀምጠህ በሕዝቡ የምታደርገው ይህ ምንድን ነው? ሕዝቡ ሁሉ ከጥዋት ጀምሮ እስከ ማታ ድረስ በዙሪያህ ቆመዋል።”'),
  ('f90d0bd8-bb50-5f47-a894-b928cd39cbba', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 3, 15, 'ሙሴም አማቱን፥ “ሕዝቡ ከእግዚአብሔር ፍርድ ለመጠየቅ ወደ እኔ ይመጣሉ፤'),
  ('b15942dc-6c52-51e5-a92b-d05d5a4150f1', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 4, 16, 'ነገርም ቢኖራቸው ወደ እኔ ይመጣሉ፤ በዚህና በዚያ ሰውም መካከል እፈርዳለሁ፤ የእግዚአብሔርንም ሥርዐትና ሕግ አስታውቃቸዋለሁ” አለው።'),
  ('98d3266f-e712-5a3d-a300-215832d92b0f', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 5, 17, 'የሙሴም አማት አለው፥ “አንተ የምታደርገው ይህ ነገር ትክክል አይደለም።'),
  ('defd6e44-04fa-5b84-a016-4adecd879a62', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 6, 18, 'አንተ፥ ከአንተም ጋር ያለው ሕዝብ ትደክማላችሁ፤ ይህ ነገር ይከብድብሃል፤ አንተ ብቻህን ልታደርገው አትችልም።'),
  ('5c63d07a-faa2-5078-a76c-c8aec688d8a4', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 7, 19, 'አሁንም እመክርሃለሁና ስማኝ፤ እግዚአብሔርም ከአንተ ጋር ይሆናል፤ አንተ በእግዚአብሔር ፊት ለሕዝቡ ሁን፤ ነገራቸውንም ወደ እግዚአብሔር አድርስ፤'),
  ('abd159fd-acbd-5385-a426-b616a45ce7ef', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 8, 20, 'የእግዚአብሔርንም ሥርዐቱንና ሕጉን መስክርላቸው፤ የሚሄዱበትንም መንገድ፥ የሚያደርጉትንም ሥራ ሁሉ አሳያቸው።'),
  ('209975d4-d950-5360-ae5c-03e41343e9f3', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 9, 21, 'አንተም ከሕዝቡ ሁሉ ኀያላን ሰዎችን፥ እግዚአብሔርን የሚፈሩትን እውነተኞች ሰዎችን፥ ትዕቢትንም የሚጠሉ ሰዎችን ፈልግ። ከእነርሱም የሺህ አለቆችን፥ የመቶ አለቆችን፥ የአምሳ አለቆችን፥ የዐሥርም አለቆችን ሹምላቸው።'),
  ('4d4a5ca9-e639-5e71-a5ec-fabd1b05df7a', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 10, 22, 'በሕዝቡ ላይ ሁል ጊዜ ይፍረዱ፤ የከበዳቸውን ነገር ወደ አንተ ያምጡት፤ ቀላሉን ነገር ሁሉ እነርሱ ይፍረዱ፤ ያቃልሉልሃል፤ ይረዱሃልም።'),
  ('720c2ffe-2e43-5658-af7e-56e2199c9cc6', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 11, 23, 'ይህንም ቃሌን ብታደርግ፥ እግዚአብሔር ያበረታሃል፤ መፍረድም ትችላለህ፤ ሕዝቡም ሁሉ በሰላም ወደ ስፍራው ይመለሳል።”'),
  ('388180e4-a05d-571e-a58b-d70f9b110180', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 12, 24, 'ሙሴም የአማቱን ቃል ሰማ፤ እንደ አለውም አደረገ።'),
  ('2fae9a1c-c931-5f95-a16e-abfdf09afa55', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 13, 25, 'ሙሴም ከእስራኤል ሁሉ ችሎታ ያላቸውን ሰዎች መረጠ፤ በሕዝቡም ላይ የሺህ አለቆች፥ የመቶ አለቆች፥ የአምሳም አለቆች፥ የዐሥርም አለቆች አድርጎ ሾማቸው።'),
  ('9bd9c08a-34b9-5aac-a13b-b451220d8867', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 14, 26, 'በሕዝቡም ላይ ሁልጊዜ ፈረዱ፤ የከበዳቸውንም ነገር ወደ ሙሴ አመጡ፤ ቀላሉን ነገር ሁሉ ግን እነርሱ ፈረዱ።'),
  ('48851775-f845-5275-aa9f-6fdae881826c', '5887d0f9-6e68-59d5-a17c-3b1ba8eb4438', '974ff1ba-17fa-5f25-a942-6993da4ab2e1', 15, 27, 'ሙሴም አማቱን አሰናበተው፤ እርሱም ወደ ሀገሩ ተመለሰ።'),
  ('031228d9-f0e5-51f5-a84c-12fc594f010a', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 1, 1, 'የእስራኤል ልጆች ከግብፅ ምድር ከወጡ በኋላ በሦስተኛው ወር በዚያ ቀን ወደ ሲና ምድረ በዳ መጡ።'),
  ('19ef037a-9714-5a8a-a91b-4aa7a733f548', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 2, 2, 'ከራፊድም ተነሥተው ወደ ሲና ምድረ በዳ መጡ፤ በዚያም እስራኤል በተራራው ፊት ሰፈሩ።'),
  ('150cb664-b6d1-5f4f-a825-06247dcb3733', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 3, 3, 'ሙሴም ወደ እግዚአብሔር ዘንድ ወጣ፤ እግዚአብሔርም ከተራራው ጠርቶ አለው፥ “ለያዕቆብ ቤት እንዲህ በል፤ ለእስራኤል ልጆች እንዲህ ንገር፤'),
  ('926b27b5-e555-58b5-a428-15bbe338349c', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 4, 4, 'በግብፃውያን ያደረግሁትን፥ እንደ ንስር ክንፍም እንደ ተሸከምኋችሁ፥ ወደ እኔም እንዳመጣኋችሁ አይታችኋል።'),
  ('54aba7dd-bcba-51c1-a662-012556d23637', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 5, 5, 'አሁንም ቃሌን በእውነት ብትሰሙ፥ ኪዳኔንም ብትጠብቁ፥ ምድር ሁሉ የእኔ ናትና ከአሕዛብ ሁሉ የተመረጠ ርስት ትሆኑልኛላችሁ።'),
  ('72972802-f2ba-5764-a8ac-46f10e272fe0', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 6, 6, 'እናንተም የክህነት መንግሥት፥ የተቀደሰም ሕዝብ ትሆኑኛላችሁ፤ ይህንም ቃል ለእስራኤል ልጆች ንገራቸው።”'),
  ('e45321f2-ea90-591e-a8ea-eeeb2c2fdeea', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 7, 7, 'ሙሴም መጣ፤ የሕዝቡንም ሽማግሌዎች ጠርቶ እግዚአብሔር ያዘዘውን ይህን ቃል ሁሉ በፊታቸው ተናገረ።'),
  ('a381ece1-ffc5-5207-a2a8-632478d8318b', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 8, 8, 'ሕዝቡም ሁሉ አንድ ቃል ሆነው፥ “እግዚአብሔር ያለውን ሁሉ እንሰማለን፤ እናደርጋለንም” ብለው መለሱ፤ ሙሴም የሕዝቡን ቃል ወደ እግዚአብሔር አደረሰ።'),
  ('95a600e6-4cdb-5ef2-a0d3-2c414ca094b9', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 9, 9, 'እግዚአብሔር ሙሴን፥ “ከአንተ ጋር ስነጋገር ሕዝቡ እንዲሰሙ፥ ደግሞም ለዘለዓለም እንዲያምኑብህ፥ እነሆ፥ በዐምደ ደመና ወደ አንተ እመጣለሁ” አለው። ሙሴም የሕዝቡን ቃል ለእግዚአብሔር ነገረ።'),
  ('ea16d7c7-3c1e-5948-a839-20b1e8fc4ad1', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 10, 10, 'እግዚአብሔርም ሙሴን አለው፥ “ውረድ፤ ዛሬና ነገ ራሳቸውን ያንጹ፤ ልብሳቸውንም ያጥቡ ዘንድ ሕዝቡን እዘዛቸው።'),
  ('2e33111a-a8ac-57a7-aca6-05c19716a021', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 11, 11, 'በሦስተኛውም ቀን ሕዝቡ ሁሉ ሲያዩ እግዚአብሔር በሲና ተራራ ላይ ይወርዳልና ለሦስተኛው ቀን ተዘጋጅተው ይጠብቁ።'),
  ('ef866cf3-7065-5be5-ac18-6f134c9b41b2', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 12, 12, 'ለሕዝቡም በዙሪያው ወሰን አድርግላቸው፤ ወደ ተራራው እንዳትወጡ፥ ከእርሱ ማንኛውንም ክፍል እንዳትነኩ ተጠንቀቁ፤ ተራራውንም የነካ ፈጽሞ ይሞታል” ብለህ ንገራቸው፤'),
  ('b5992159-de41-5a62-a3ac-629416a5c87d', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 13, 13, 'የማንም እጅ አይንካ፤ የሚነካውም ሁሉ በድንጋይ ይወገራል፤ ወይም በፍላጻ ይወጋል፤ እንስሳ ወይም ሰው ቢሆን የቀረበ አይድንም። የመለከት ድምፅና ደመና በተራራው በዐለፈ ጊዜ ወደ ተራራው ይውጡ።'),
  ('829fc832-63a6-5c92-a00b-7a41f2a62f65', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 14, 14, 'ሙሴም ከተራራው ወደ ሕዝቡ ወረደ፤ ሕዝቡንም ቀደሰ፤ ልብሳቸውንም አጠቡ።'),
  ('f072c95e-063c-599b-a844-03e85e179a4d', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 15, 15, 'ሕዝቡንም፥ “ለሦስተኛው ቀን ተዘጋጁ፤ ወደ ሴቶቻችሁም አትቅረቡ” አለ።'),
  ('74720cee-837b-558f-a182-829694d40b13', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 16, 16, 'እንዲህም ሆነ፤ በሦስተኛው ቀን በማለዳ ጊዜ ነጐድጓድና መብረቅ፥ ከባድም ደመና፥ ጉምም በሲና ተራራ ላይ ሆነ፤ እጅግም የበረታ የቀንደ መለከት ድምፅ ተሰማ፤ በሰፈሩም የነበሩት ሕዝብ ሁሉ ተንቀጠቀጡ።'),
  ('3f9855cc-57ca-55af-a4df-2940aa28e2d6', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 17, 17, 'ሙሴም ሕዝቡን ከእግዚአብሔር ጋር ለማገናኘት ከሰፈር አወጣቸው፤ በተራራውም እግርጌ ቆሙ።'),
  ('11177c00-fc95-568a-a6d5-a039d0885022', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 18, 18, 'እግዚአብሔርም በእሳት ስለ ወረደበት የሲና ተራራ ሁሉ እንደ ምድጃ ጢስ ይጤስ ነበር፤ ከእርሱም እንደ እቶን ጢስ ያለ ጢስ ይወጣ ነበር፤ ተራራውም ሁሉ እጅግ ይናወጥ ነበር፤ ሕዝቡም ፈጽመው ደነገጡ።'),
  ('dfc6590c-1bad-58d4-a897-c5afc7b9352b', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 19, 19, 'የቀንደ መለከቱም ድምፅ እጅግ እየፈጠነ በርትቶ ይሰማ ነበር። ሙሴም ተናገረ፤ እግዚአብሔርም በድምፅ መለሰለት።'),
  ('55d90672-ae0a-5e29-ae21-c46b96343510', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 20, 20, 'እግዚአብሔርም በሲና ተራራ ላይ ወደ ተራራው ራስ ወረደ፤ እግዚአብሔርም ሙሴን ወደ ተራራው ራስ ጠራው፤ ሙሴም ወጣ።'),
  ('8e841519-a3c3-5797-aa23-d3bba895392b', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 21, 21, 'እግዚአብሔርም ሙሴን፥ “ውረድ፤ ይህንም ለመረዳት ወደ እግዚአብሔር እንዳይቀርቡ፥ ከእነርሱም ብዙ እንዳይጠፉ ለሕዝቡ አስጠንቅቃቸው፤'),
  ('1e39dcb0-61ce-5ba8-a2f1-56cee6bb161f', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 22, 22, 'ወደ እግዚአብሔርም የሚቀርቡት ካህናት ደግሞ እንዳያጠፋቸው ራሳቸውን ይቀድሱ” አለው።'),
  ('18fb227d-b801-57ef-a9ad-9b7b19066790', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 23, 23, 'ሙሴም እግዚአብሔርን፥ “ሕዝቡ ወደ ሲና ተራራ ይወጡ ዘንድ አይችሉም፤ አንተ፦ በተራራው ዙሪያ ወሰን አድርግ፤ ቀድሰውም ብለህ አስጠንቅቀኸኛልና” አለው።'),
  ('72f05d54-a816-5b0a-aa6d-ee74b392f989', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 24, 24, 'እግዚአብሔርም፥ “ሂድ፤ ውረድ፤ አንተ አሮንም ከአንተ ጋር ትወጣላችሁ፤ ካህናቱና ሕዝቡ ግን እግዚአብሔር እንዳያጠፋቸው ወደ እግዚአብሔር ይወጡ ዘንድ አይደፋፈሩ” አለው።'),
  ('7e5fbd4f-e466-5eb3-aec0-6005473a995d', 'c1efc725-2a87-5375-a335-5f58b1fecad0', '9de42d65-ff9f-5646-a053-e2a67ad4cb8c', 25, 25, 'ሙሴም ወደ ሕዝቡ ወረደ፤ ይህንም ነገራቸው።'),
  ('e6516058-e7e5-50a1-ae38-def6d09a033a', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 1, 1, 'እግዚአብሔርም ይህን ቃል ሁሉ እንዲህ ብሎ ተናገረ፦'),
  ('3aabdf77-2108-5d25-ab58-f2891f9a058a', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 2, 2, '“ከግብፅ ምድር ከባርነት ቤት ያወጣሁህ እግዚአብሔር አምላክህ እኔ ነኝ፤'),
  ('b1c5f33b-8ca1-555f-a90c-6a3d67077c5f', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 3, 3, '“ከእኔ በቀር ሌሎችን አማልክት አታምልክ።'),
  ('7a39f090-25f9-5558-a6fa-01270ba706b7', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 4, 4, '“በላይ በሰማይ ከአለው፥ በታችም በምድር ከአለው፥ ከምድርም በታች በውኃ ከአለው ነገር የማናቸውንም ምስል ለአንተ አምላክ አታድርግ።'),
  ('75f6cdf3-5a26-5bbe-ab74-224fd6a62dfd', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 5, 5, 'አትስገድላቸው፤ አታምልካቸውም፤ እኔ እግዚአብሔር አምላክህ ቀናተኛ አምላክ ነኝና። በሚጠሉኝ እስከ ሦስተኛና አራተኛ ትውልድ ድረስ የአባቶችን ኀጢአት በልጆች ላይ የማመጣ፤'),
  ('b06e9748-f49d-510c-a634-9da940094118', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 6, 6, 'ለሚወድዱኝ፥ ትእዛዜንም ለሚጠብቁ እስከ ሺህ ትውልድ ድረስ ምሕረትን የማደርግ አምላክ ነኝና።'),
  ('f6415d6a-dddb-5a01-ae9d-47017a8a8dfe', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 7, 7, '“የእግዚአብሔርን የአምላክህን ስም በከንቱ አትጥራ፤ አምላክህ እግዚአብሔር ስሙን በከንቱ የሚጠራውን ከበደል አያነጻውምና።'),
  ('18183a1d-f063-5a0f-ac67-6ee2400c2bec', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 8, 8, '“የሰንበትን ቀን ትቀድሳት ዘንድ አስብ።'),
  ('9c971391-7238-5857-afbd-920a53709bb2', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 9, 9, 'ስድስት ቀን ሥራህን ሥራ፤ ተግባርህንም ሁሉ አድርግ፤'),
  ('352ca325-b18b-5eeb-a3c4-4837b71b2a6f', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 10, 10, 'ሰባተኛዋ ቀን ግን ለእግዚአብሔር ለአምላክህ ሰንበት ናት፤ አንተ፥ ወንድ ልጅህም፥ ሴት ልጅህም፥ ሎሌህም፥ ገረድህም፥ አህያህም፥ ከብትህም፥ በደጆችህም ውስጥ ያለ እንግዳ በእርስዋ ምንም ሥራ አትሥሩ፤'),
  ('10aa19bd-5d10-56bd-a99d-fd773d4fd53d', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 11, 11, 'እግዚአብሔር በስድስት ቀን ሰማይንና ምድርን፥ ባሕርንም፥ በውስጣቸው ያለውንም ሁሉ ፈጥሮ በሰባተኛዋ ቀን ዐርፎአልና፤ ስለዚህ እግዚአብሔር የሰንበትን ቀን ባርኮታል፤ ቀድሶታልም።'),
  ('3dc486e6-8f0c-54bd-a344-b00a76c5974c', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 12, 12, '“አባትህንና እናትህን አክብር፤ መልካም እንዲሆንልህ፥ እግዚአብሔር አምላክህ በሚሰጥህ ምድርም ዕድሜህ እንዲረዝም።'),
  ('fa8edd59-44ef-56a2-a46d-4a565300bf16', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 13, 13, '“አትግደል።'),
  ('68de6fe4-06ec-52a6-a0c1-52420660dac4', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 14, 14, '“አታመንዝር።'),
  ('4fc3a6f1-f7d0-551a-ace5-8eb8f7501c68', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 15, 15, '“አትስረቅ።'),
  ('f6622002-58fb-51e0-accd-1208a93f1417', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 16, 16, '“በባልንጀራህ ላይ በሐሰት አትመስክር።'),
  ('a208c5a4-152b-5704-a645-f5c6820f683a', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5a2efa30-fd70-52fb-ac43-b61372a0eb04', 17, 17, '“የባልንጀራህን ሚስት፥ የባልንጀራህን ቤት አትመኝ፤ እርሻውንም፥ ሎሌውንም፥ ገረዱንም፥ በሬውንም፥ አህያውንም፥ ከብቱንም ሁሉ ከባልንጀራህ ገንዘብ ሁሉ ማንኛውንም አትመኝ።”'),
  ('641409ff-ddd0-52b6-abe6-e1017801208d', '765e9f47-fb7d-5028-ad0a-0195b217167c', '60d96ce2-b8d4-548d-abcd-a739dfe579c4', 1, 18, 'ሕዝቡም ሁሉ ነጐድጓዱንና መብረቁን፥ የቀንደ መለከቱን ድምፅ፥ ተራራውንም ሲጤስ አዩ፤ ሕዝቡም ሁሉ ፈርተው ርቀው ቆሙ።'),
  ('e5f01c04-63ed-5098-a768-d5061c9ad7e7', '765e9f47-fb7d-5028-ad0a-0195b217167c', '60d96ce2-b8d4-548d-abcd-a739dfe579c4', 2, 19, 'ሙሴንም፥ “አንተ ከእኛ ጋር ተናገር፤ ነገር ግን እንዳንሞት እግዚአብሔር ከእኛ ጋር አይናገር” አሉት።'),
  ('6fdf505a-2297-5413-a356-f2ec2423f3ba', '765e9f47-fb7d-5028-ad0a-0195b217167c', '60d96ce2-b8d4-548d-abcd-a739dfe579c4', 3, 20, 'ሙሴም ለሕዝቡ፥ “እግዚአብሔር ሊፈትናችሁ፥ ኀጢአትንም እንዳትሠሩ እርሱን መፍራት በእናንተ ያድር ዘንድ መጥቶአልና አትፍሩ” አላቸው።'),
  ('55c4f754-d331-5f08-a525-49bd21235bab', '765e9f47-fb7d-5028-ad0a-0195b217167c', '60d96ce2-b8d4-548d-abcd-a739dfe579c4', 4, 21, 'ሕዝቡም ርቀው ቆሙ፤ ሙሴም እግዚአብሔር ወዳለበት ወደ ጨለማው ቀረበ።'),
  ('59360a45-6c17-51a3-aa6e-ae5b30f79757', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5580d1bd-f95d-5568-ae11-32e1fa8aecd8', 1, 22, 'እግዚአብሔር ሙሴን አለው፥ “ለያዕቆብ ቤት ለእስራኤልም ልጆች እንዲህ በል፦ እኔ ከሰማይ እንደ ተናገርኋችሁ እናንተ አይታችኋል።'),
  ('73a56c12-a999-5fae-af1c-a62ecfc2c9ba', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5580d1bd-f95d-5568-ae11-32e1fa8aecd8', 2, 23, 'የብር አማልክትን አታምልኩ፤ የወርቅ አማልክትንም አታምልኩ። የዕንጨትና የድንጋይ አምላክንም አታምልኩ፤ እንዲህ ያለ አምላክን ለእናንተ አታድርጉ።'),
  ('2012bfba-e0ca-5f0f-a6c2-86cc1bac2f2c', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5580d1bd-f95d-5568-ae11-32e1fa8aecd8', 3, 24, 'ከአፈርም መሠዊያ ሥራልኝ፤ የሚቃጠለውንና የደኅንነት መሥዋዕትህን፥ በጎችህንም፥ በሬዎችህንም ሠዋበት፤ ስሜን ባስጠራሁበት ስፍራ ሁሉ ወደ አንተ መጥቼ እባርክሃለሁ።'),
  ('6f45178a-3afb-57ca-a2f1-6d7aecc0bcd1', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5580d1bd-f95d-5568-ae11-32e1fa8aecd8', 4, 25, 'የድንጋይም መሠዊያ ብታደርግልኝ ጠርበህ አትሥራው፤ በመሣሪያ ብትነካው ታረክሰዋለህና።'),
  ('1b65378a-e7ea-5ff3-a430-32ac4edabdc8', '765e9f47-fb7d-5028-ad0a-0195b217167c', '5580d1bd-f95d-5568-ae11-32e1fa8aecd8', 5, 26, 'ኀፍረተ ሥጋህ በእርሱ እንዳይገለጥ ወደ መሠዊያዬ በደረጃ አትውጣ።'),
  ('2ac5228c-6a45-584c-a547-0efd82a465e1', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '6d15b16f-9890-5c2d-a144-2cfac8245c32', 1, 1, '“በፊታቸው የምታደርገው ሥርዐት ይህ ነው።'),
  ('1bb0f049-00ae-5f62-a5bb-c095f6df4e58', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '6d15b16f-9890-5c2d-a144-2cfac8245c32', 2, 2, 'ዕብራዊ ባሪያ የገዛህ እንደ ሆነ ስድስት ዓመት ያገልግልህ፤ በሰባተኛውም ዓመት በነጻ አርነት ይውጣ።'),
  ('6dd676d5-f277-5d4f-a51f-6db6f94a65a3', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '6d15b16f-9890-5c2d-a144-2cfac8245c32', 3, 3, 'ብቻውን መጥቶ እንደ ሆነ ብቻውን ይውጣ፤ ከሚስቱም ጋር መጥቶ እንደ ሆነ ሚስቱ ከእርሱ ጋር ትውጣ።'),
  ('b29c4904-d22d-5653-acb6-c96475235db0', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '6d15b16f-9890-5c2d-a144-2cfac8245c32', 4, 4, 'ጌታው ሚስት አጋብቶት እንደ ሆነ ወንዶች ወይም ሴቶች ልጆች ብትወልድለት፥ ሚስቱና ልጆቹ ለጌታው ይገዙ፤ እርሱም ብቻውን ነጻ ይውጣ።'),
  ('59759851-0185-5d40-ab6c-70566e15d407', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '6d15b16f-9890-5c2d-a144-2cfac8245c32', 5, 5, 'ባሪያውም፦ ጌታዬን፥ ሚስቴን፥ ልጆችንም እወድዳለሁ፤ አርነትም አልወጣም ብሎ ቢናገር፥'),
  ('69cab073-08d9-589a-a41a-903c93b69818', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '6d15b16f-9890-5c2d-a144-2cfac8245c32', 6, 6, 'ጌታው ወደ ቤተ እግዚአብሔር ፈራጆች ይውሰደው፤ ወደ ደጁም፥ ወደ መቃኑም አቅርቦ አፍንጫውን በወስፌ ይብሳው፤ ለዘለዓለምም ባሪያው ይሁነው።'),
  ('0dc68f54-3ed8-5dbb-a21b-ab28b024f3cd', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '6d15b16f-9890-5c2d-a144-2cfac8245c32', 7, 7, '“ሴት ልጁን ለባርነት አሳልፎ የሰጠ ቢኖር ሴቶች ባሪያዎች አርነት እንደሚወጡ እርስዋ ትውጣ።'),
  ('b3307207-e897-56ca-a054-43e61734ad8d', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '6d15b16f-9890-5c2d-a144-2cfac8245c32', 8, 8, 'ለእርሱ ከታጨች በኋላ ጌታዋን ደስ ባታሰኘው በዎጆ ይስደዳት፤ ነገር ግን ለሌላ ወገን ይሸጣት ዘንድ አይገባውም። እርሱ አርክሶአታልና።'),
  ('011a31b8-c71f-565e-a7c4-1eae90f87228', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '6d15b16f-9890-5c2d-a144-2cfac8245c32', 9, 9, 'ለልጁም ሊድራት ቢወድድ፥ ለሴት ልጆች የሚገባውን ያድርግላት፤'),
  ('7e6e8706-7f9a-56c8-ac16-23b82c809866', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '6d15b16f-9890-5c2d-a144-2cfac8245c32', 10, 10, 'ከእርስዋም ሌላ ቢያገባ፥ ቀለብዋን፥ ልብስዋንም፥ ለጋብቻዋም ተገቢውን ይስጣት፤ እንዳልበደላትም ምስክር ያሰማባት።'),
  ('07e28272-5165-57a1-a19c-49c40eb196ad', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '6d15b16f-9890-5c2d-a144-2cfac8245c32', 11, 11, 'ይህንም ሦስት ነገር ባያደርግላት ያለ ገንዘብ ነጻ ትውጣ።'),
  ('b66fbd3a-d01a-5066-aeef-be611a11fdaf', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 1, 12, '“ሰው ሰውን ቢመታ፥ ቢሞትም፥ የመታው ፈጽሞ ይገደል።'),
  ('6b972483-d9b9-58b0-aee4-119eb1b8fd06', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 2, 13, 'ሳይፈቅድ ቢመታው፥ ባይሸምቅበትም፥ ነገር ግን እግዚአብሔር ድንገት በእጁ ቢጥለው፥ ገዳዩ የሚሸሽበትን ስፍራ እኔ አደርግልሃለሁ።'),
  ('20360419-2690-555b-af32-fe7105345ae7', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 3, 14, 'ሰው ግን ቢሸምቅ ጠላቱንም በተንኰል ቢገድለውና ቢማፀን፥ እንዲገደል ከመሠዊያዬ አውጥተህ ውሰደው።'),
  ('9a0f52e1-6f76-5c3f-aa9e-f1cc8be87618', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 4, 15, '“አባቱን ወይም እናቱን የሚማታ ይገደል።'),
  ('0147127f-bb6b-5756-a1c9-f828c85ffafe', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 5, 16, '“አባቱን ወይም እናቱን የሚሰድብ በሞት ይቀጣ።'),
  ('377c803b-2be5-5e79-a985-5a6934b68fe0', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 6, 17, '“ከእስራኤል ልጆች አንዱን የሰረቀ ወይም ግፍ የፈጸመበት፥ ወይም አሳልፎ ቢሰጠው፥ ወይም በእርሱ ዘንድ ቢገኝ፥ እርሱ ይገደል።'),
  ('ef5d02ba-6bbf-5268-a26a-1f83129456f6', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 7, 18, '“ሁለት ሰዎችም እርስ በርሳቸው ቢጣሉ፥ አንዱም ሌላውን በድንጋይ ወይም በጡጫ ቢመታ፥ ያም ባይሞት ነገር ግን በአልጋው ላይ ቢተኛ፥'),
  ('3aee879b-409c-5e2d-ab1a-de3b0dca0c9a', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 8, 19, 'ተነሥቶም በምርኩዝ ወደ ሜዳ ቢወጣ፥ የመታው ንጹሕ ነው፤ ነገር ግን ተግባሩን ስላስፈታው ገንዘብ ይክፈለው፤ ለባለ መድኀኒትም ይክፈልለት።'),
  ('a0b2f2e0-dd80-5a29-afba-b2f8d986a60d', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 9, 20, '“ሰውም ወንድ ባሪያውን ወይም ሴት ባሪያውን በበትር ቢመታ፥ በእጁ ቢሞትበትም፥ ፈጽሞ ይቀጣ፤'),
  ('b44a8aeb-9054-578d-a22d-81425307d479', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 10, 21, 'የተመታው ግን አንድ ወይም ሁለት ቀን ቢቈይ ገንዘቡ ነውና አይቀጣ።'),
  ('3524e611-8c05-5177-a12c-f8dea04556c9', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 11, 22, '“ሁለት ሰዎች እርስ በርሳቸው ቢጣሉ፥ ያረገዘችንም ሴት ቢያቈስሉ ተሥዕሎተ መልክእ ያልተፈጸመለት ፅንስም ቢያስወርዳት፥ የሴቲቱ ባል የጣለበትን ያህል ካሳ ይክፈል፤'),
  ('33958b4e-0200-529f-a377-9e6940997f49', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 12, 23, 'ተሥዕሎተ መልክእ የተፈጸመለት ፅንስ ቢያስወርዳት ግን ሕይወት በሕይወት፥'),
  ('e7daffd8-c397-5858-a917-659a4b3163fc', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 13, 24, 'ዐይን በዐይን፥ ጥርስ በጥርስ፥ እጅ በእጅ፥ እግር በእግር፥'),
  ('6edd5ae0-84e7-55e5-a180-23a182a8d5df', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 14, 25, 'መቃጠል በመቃጠል፥ ቍስል በቍስል፥ ግርፋት በግርፋት ይክፈል።'),
  ('1b0deafa-2181-52ff-acd0-7b381ff55983', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 15, 26, '“ሰውም የባሪያውን ዐይን ወይም የባሪያዪቱን ዐይን ቢመታ፥ ቢያጠፋውም፥ ስለ ዐይናቸው አርነት ያውጣቸው።'),
  ('fcd168a1-d436-552a-a953-2df3b2dc883f', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', '8c856b90-d4d8-5880-af4a-3911efb56d82', 16, 27, 'የባሪያውን ጥርስ ወይም የባሪያዪቱን ጥርስ ቢሰብር፥ ስለ ጥርሳቸው አርነት ያውጣቸው።'),
  ('fdf35a40-d15f-58c5-a848-7cc43ccdb0fc', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', 'cb7e7b29-0af5-5980-a1f0-27f4954181c3', 1, 28, '“በሬም ወንድን ወይም ሴትን ቢወጋ ቢሞቱም፥ በሬው በድንጋይ ይወገር፤ ሥጋውም አይበላ፤ የበሬው ባለቤት ግን ንጹሕ ነው።'),
  ('d7c4245d-cb8b-5575-ab85-251ba253674f', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', 'cb7e7b29-0af5-5980-a1f0-27f4954181c3', 2, 29, 'በሬው ግን ከትናንትና ከትናንት ወዲያ ተዋጊ ቢሆን፥ ሰዎችም ለባለቤቱ ቢመሰክሩለት ባያስወግደውም፥ ወንድን ወይም ሴትን ቢገድል፥ በሬው ይወገር፤ ባለቤቱ ደግሞ ይገደል።'),
  ('190eb3ef-8c03-5c97-a385-d7634a9af2bc', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', 'cb7e7b29-0af5-5980-a1f0-27f4954181c3', 3, 30, 'ከእርሱ ግን ካሳ ቢፈልጉ፥ የሕይወቱን ካሳ የጫኑበትን ያህል ይስጥ።'),
  ('a7f24068-35b5-57d7-a899-04969c35b6fd', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', 'cb7e7b29-0af5-5980-a1f0-27f4954181c3', 4, 31, 'በሬው ወንድን ልጅ ቢወጋ፥ ሴትንም ልጅ ቢወጋ ይህንኑ ፍርድ ያድርጉበት።'),
  ('eef3e09b-eb8e-5b8b-a5d0-f87eae9b7da2', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', 'cb7e7b29-0af5-5980-a1f0-27f4954181c3', 5, 32, 'በሬው ወንድ ባሪያ ወይም ሴት ባሪያ ቢወጋ፥ የበሬው ባለቤት ሠላሳ የብር ሰቅል ለጌታቸው ይስጥ፤ በሬውም ይወገር።'),
  ('3f28e4e2-345c-59cf-a18a-f5d0f89ccf3a', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', 'cb7e7b29-0af5-5980-a1f0-27f4954181c3', 6, 33, '“ሰውም ጕድጓድ ቢከፍት ወይም ጕድጓድ ቢቈፍር ባይከድነውም፥ በሬም ወይም አህያ፤ ቢወድቅበት፥'),
  ('bd02ccbb-a773-5334-a7cb-2ccc289da924', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', 'cb7e7b29-0af5-5980-a1f0-27f4954181c3', 7, 34, 'የጕድጓዱ ባለቤት ዋጋቸውን ለባለቤታቸው ይክፈል፤ የሞተውም ለእርሱ ይሁን።'),
  ('6babcbd4-7407-527d-a009-f1cb76b08375', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', 'cb7e7b29-0af5-5980-a1f0-27f4954181c3', 8, 35, '“የሰው በሬ የሌላውን በሬ ቢወጋ፥ ቢሞትም፥ ደኅናውን በሬ ይሽጡ፤ ዋጋውንም በትክክል ይካፈሉ፤ የሞተውንም ደግሞ በትክክል ይካፈሉ።'),
  ('ddc5b124-ecab-5118-a80b-902542a6cec0', '1d5a5a17-0d10-513d-a3db-0e0c0b95c057', 'cb7e7b29-0af5-5980-a1f0-27f4954181c3', 9, 36, 'በሬውም ትናንትና ከትናንት ወዲያ ተዋጊ መሆኑ ቢታወቅ ለባለቤቱም ቢመሰክሩለት፥ ባለቤቱም ባያስወግደው በሬውን በበሬው ፋንታ ይስጥ፤ የሞተውም ለእርሱ ይሁነው።'),
  ('f01193f3-8a44-5da0-ab6f-5a6ac241e093', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 1, 1, '“ሰው በሬ ወይም በግ ቢሰርቅ፥ ቢያርደው ወይም ቢሸጠው፥ በአንድ በሬ ፋንታ አምስት በሬዎች፥ በአንድ በግም ፋንታ አራት በጎች ይክፈል።'),
  ('d549252f-a4cd-5c3b-abfd-46c75ccb3e80', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 2, 2, 'ሌባ ቤት ሲምስ ቢገኝ፥ እርሱም ቢመታ፥ ቢሞትም በመታው ሰው ላይ የደም ዕዳ አይሆንበትም።'),
  ('c2e4960e-b119-58ea-afb2-32edc3761de8', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 3, 3, 'ፀሐይ ግን ከወጣችበት የደም ዕዳ አለበት፤ የገደለው ይገደል፤ ሌባው ቢያዝ የሚከፍለውም ቢያጣ ስለ ሰረቀው ይሸጥ።'),
  ('916f088f-b8c3-505a-ae88-905d040ea330', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 4, 4, 'የሰረቀው ደኅና ሆኖ በእጁ ቢገኝ፥ በሬ ወይም በግ ቢሆን፥ የሰረቀውን ያህል ሁለት እጥፍ ይክፈል።'),
  ('0a5115e5-9cde-59ad-af46-68d2f0ce506e', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 5, 5, '“የሰውን አዝመራ ከብቱን ያስበላ፥ የሌላ ሰው ወይንንም ያስበላ ሰው ቢኖር ግምቱን ይክፈል። የሰውን አዝመራ ፈጽሞ ቢያስበላ ግን በአጠገቡ ባለ አዝመራ ልክ ይክፈል፤ ወይንም ቢሆን በአጠገቡ ባለ ወይን ልክ ይክፈል።'),
  ('5e42bb3d-e616-5535-a22e-651e0d8c7e80', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 6, 6, '“እሳት ቢነሣ ጫካውንም ቢይዝ፥ ዐውድማውንም፥ ክምሩንም ወይም ያልታጨደውን እህል ወይም እርሻውን ቢያቃጥል እሳቱን ያነደደው ይክፈል።'),
  ('6bd88b15-8af0-52c9-abfb-70e00d6ca830', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 7, 7, '“ሰው በባልንጀራው ዘንድ ብር ወይም ሌላ ዕቃ እንዲጠብቅለት አደራ ቢያኖር ከቤቱም ቢሰረቅ፥ ሌባው ቢገኝ እጥፍ ይክፈል።'),
  ('aad96d12-4115-569a-a08d-20a1ba6c1373', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 8, 8, 'ሌባው ባይገኝ ባለቤቱ ወደ ፈጣሪ ፊት ይቅረብ፤ ባልንጀራው አደራ በአስቀመጠበት ገንዘብም ላይ እንዳልተተነኰለና ክፉ እንዳላሰበ ይማል።'),
  ('24f01344-dd1e-5d0e-a421-e20a08f7a5ab', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 9, 9, 'ሰዎች ስለ በሬ ወይም ስለ አህያ ወይም ስለ በግ ወይም ስለ ልብስ ወይም ስለሌላ ስለ ጠፋ ነገር ቢካሰሱ፥ አንዱም፦ ‘ይህ የእኔ ነው’ ቢል፥ ክርክራቸው በፈጣሪ ፊት ይቅረብ፤ በፈጣሪ ፊት የተፈረደበት እርሱ ለባልንጀራው እጥፍ ይክፈል።'),
  ('380de0c1-ca51-5893-a836-f54ce2fbb820', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 10, 10, '“ሰው በባልንጀራው ዘንድ አህያ ወይም በሬ ወይም በግ ወይም ሌላ እንስሳ እንዲጠብቅለት አደራ ቢያኖር፥ ማንም ሳያይ ቢሞት ወይም ቢጐዳ ወይም ቢማረክ፥'),
  ('4c2e2fd6-5916-5f22-a3f4-e45eab889cdb', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 11, 11, 'በባልንጀራው ከብት ላይ እጁን እንዳልዘረጋ የእግዚአብሔር መሐላ በሁለታቸው መካከል ይሁን፤ የከብቱም ባለቤት ይህን ከተቀበለ፥ እርሱ ምንም አይክፈል።'),
  ('b049d92a-d2bd-563c-a74f-09ae180e7a2f', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 12, 12, 'ከእርሱም ዘንድ ቢሰረቅ ለባለቤቱ ይክፈል።'),
  ('ba3315e4-3089-5312-a646-f7ed4c5e0097', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 13, 13, 'በምድረ በዳም አውሬ ቢበላው ውዳቂውን ያሳይ፤ አይክፈልም።'),
  ('e22b2130-d799-5a79-ac9c-ab0455d708c7', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 14, 14, 'ሰው ከባልንጀራው አንዳች ቢዋስ ባለቤቱ ከእርሱ ጋር ሳይኖር ቢጎዳ፥ ወይም ቢሞት፥ ወይም ቢነጠቅ ፈጽሞ ይክፈለው።'),
  ('f290cafb-3d3e-536b-aa2a-8f239bb06693', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'fe3c1b91-d4fd-5355-a2a1-a3b6552665fe', 15, 15, 'ባለቤቱ ግን ከእርሱ ጋር ቢኖር አይክፈል፤ ቢከራየውም ኪራዩን ይክፈል።'),
  ('edfe929c-9cfa-5ea4-a2e1-24652444b14c', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 1, 16, '“ሰው ያልታጨችውን ድንግል ቢያስታት፥ ከእርስዋም ጋር ቢተኛ ሚስት አድርጎ ይውሰዳት።'),
  ('c450f72d-3429-5732-aba6-8bf16b455bee', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 2, 17, 'አባቷም እርስዋን እንዳይሰጠው ፈጽሞ እንቢ ቢል እንደ ደናግል ማጫ ያህል ማጫዋን ይስጠው።'),
  ('863fa990-4dd5-56d4-adb8-07b350833f47', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 3, 18, '“ከመተተኛ ጋር አንድ አትሁኑ።'),
  ('331ad64e-1c9f-5e0e-afa3-6f40d4d620b2', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 4, 19, '“ከእንስሳ የሚደርስ ሁሉ ሞትን ይሙት።'),
  ('988b8fe3-2f5e-58eb-ac01-8786dc73fd3c', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 5, 20, '“ከእግዚአብሔር ብቻ በቀር ለአማልክት የሚሠዋ ፈጽሞ ይጥፋ።'),
  ('45c5e9d8-aa0e-50c0-a5cf-fe89793c87e9', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 6, 21, 'እናንተ በግብፅ ምድር ስደተኞች ነበራችሁና ስደተኛውን አትበድሉት፤ ግፍም አታድርጉበት።'),
  ('f8a179c3-9ce1-5578-a5ff-3193b60393b0', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 7, 22, 'መበለቲቱንና ድሀ-አደጎቹን አታስጨንቁአቸው።'),
  ('ee596dff-90d0-590e-a4fb-ada86bc56df1', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 8, 23, 'ብታስጨንቁአቸውና ወደ እኔ ቢጮኹ እኔ ጩኸታቸውን ፈጽሞ እሰማለሁ፤'),
  ('73128dcb-539e-532a-a6bf-aa716d9d5684', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 9, 24, 'ቍጣዬም ይጸናባችኋል፤ በሰይፍም አስገድላችኋለሁ፤ ሚስቶቻችሁም መበለቶች፥ ልጆቻችሁም ድሀ-አደጎች ይሆናሉ።'),
  ('2f207c83-df3a-5b76-ae9c-d9472ae32648', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 10, 25, '“ከአንተ ጋር ለተቀመጠው ለድሃው ወገንህ ብር ብታበድረው፥ አታስጨንቀው፤ አራጣም አታስከፍለው።'),
  ('690cfd97-cb81-5a82-a2c0-d587095ccd45', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 11, 26, 'የባልንጀራህን ልብስ ለመያዣ ብትወስድ ፀሐይ ሳትገባ መልስለት፤'),
  ('c1c02f6d-7dee-5a55-a178-07d3236adb93', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 12, 27, 'ልብሱ ነውና፥ ዕርቃኑንም የሚሸፍንበት ይህ ብቻ ነውና፤ የሚተኛበትም ሌላ የለውምና፤ ወደ እኔም ቢጮኽ ፈጥኜ እሰማዋለሁ፤ መሓሪ ነኝና።'),
  ('c81b1e92-0d18-5a1a-aee6-8a7670b8a032', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 13, 28, '“ፈራጆችን አትስደብ፥ የሕዝብህንም አለቃ ክፉ አትናገረው።'),
  ('2df5ec27-915a-59a4-af41-3125103942af', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 14, 29, 'የአውድማህንና የወይንህንም መጀመሪያ ለማቅረብ አትዘግይ፤ የልጆችህንም በኵር ትሰጠኛለህ።'),
  ('dd7cf1ec-bdba-584e-a95c-240c225d5db2', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 15, 30, 'እንዲሁም በበሬዎችህና በበጎችህ፥ በአህያህም ታደርገዋለህ፤ ሰባት ቀን ከእናቱ ጋር ይቀመጥ፤ በስምንተኛውም ቀን ለእኔ ትሰጠዋለህ።'),
  ('022c9ea3-84ce-5e5c-acba-4cf0811f2730', '1b98dbc7-3d2c-5360-a1f2-77ff246d1fad', 'b9ba4af1-dae7-5306-aac3-28c9d22d7dcb', 16, 31, 'ቅዱስ ወገን ትሆኑልኛላችሁ፤ ስለዚህ አውሬ የገደለውን ሥጋ ለውሻ ጣሉት እንጂ አትብሉት።'),
  ('f46a86e0-cc22-5187-ab5c-f76d6e8f460f', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '7b875d98-4199-596e-a53b-b3b40b184b73', 1, 1, '“ሐሰተኛ ወሬ አትቀበል፤ የዐመፅ ምስክርም ትሆን ዘንድ ከዐመፀኛ ጋር አትቀመጥ።'),
  ('1aa5e81c-063a-538e-afa8-37cefced1ec0', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '7b875d98-4199-596e-a53b-b3b40b184b73', 2, 2, 'ለዐመፅ ከብዙ ሰው ጋር አንድ አትሁን፤ ፍርድንም ለማጣመም ከብዙ ሰው ጋር አትጨመር።'),
  ('0438c0fd-42ae-5875-aa4c-3f6141b3e8e8', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '7b875d98-4199-596e-a53b-b3b40b184b73', 3, 3, 'በፍርድ ለድሀው አትራራ።'),
  ('e0be1518-aec1-5db7-a812-cfbcdd8aef26', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '7b875d98-4199-596e-a53b-b3b40b184b73', 4, 4, '“የጠላትህን በሬ ወይም አህያውን ጠፍቶ ብታገኘው ፈጽሞ መልስለት።'),
  ('d5e0112d-8cc1-58df-a6ac-c0bcad279c3b', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '7b875d98-4199-596e-a53b-b3b40b184b73', 5, 5, 'የጠላትህን አህያ ከጭነቱ በታች ወድቆ ብታገኘው አትለፈው፤ ነገር ግን ከእርሱ ጋር ለማንሣት ርዳው።'),
  ('a77f4c66-cd43-58b0-aceb-e6433f509f98', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '7b875d98-4199-596e-a53b-b3b40b184b73', 6, 6, '“በፍርድ የድሀውን ፍርድ አታጣምም።'),
  ('fef8147e-f940-5cb2-a518-5d7a3a1a5f13', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '7b875d98-4199-596e-a53b-b3b40b184b73', 7, 7, 'ከዐመፅ ፍርድ ሁሉ ራቅ፤ በደል የሌለበትንና ጻድቅን አትግደል፤ ኀጢአተኛውንም በመማለጃ አታድን፤'),
  ('58006667-b0d6-5265-ae26-bb84958da537', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '7b875d98-4199-596e-a53b-b3b40b184b73', 8, 8, 'መማለጃን አትቀበል፤ መማለጃ የዐይናማዎችን ዐይን ያሳውራልና፥ እውነተኛ ቃልንም ያጣምማልና።'),
  ('89eb81c1-bca7-5bf4-a5d1-a47d87e46aac', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '7b875d98-4199-596e-a53b-b3b40b184b73', 9, 9, 'በስደተኛው ግፍ አታድርጉ፤ እናንተ በግብፅ ምድር ስደተኞች ስለ ነበራችሁ የስደተኛ ነፍስ እንዴት እንደ ሆነች ዐውቃችኋልና።'),
  ('0cf5a833-c515-5cb9-af71-1bf1fdf2adc4', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '995a9ab9-c102-5bae-a546-5bd7b52948ba', 1, 10, '“ስድስት ዓመት ምድርህን ዝራ፤ ፍሬዋንም አግባ፤'),
  ('8de77839-580f-5d28-a859-e8167bbef95b', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '995a9ab9-c102-5bae-a546-5bd7b52948ba', 2, 11, 'በሰባተኛው ዓመት ግን ተዋት፤ አሳርፋትም፤ የሕዝብህም ድሆች ይበሉታል፤ እነርሱ ያስቀሩትንም የሜዳ እንስሳ ይብላው። እንዲሁም በወይንህና በወይራህ አድርግ።'),
  ('a5bb9560-61d5-5616-ab44-c09c710748e3', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '995a9ab9-c102-5bae-a546-5bd7b52948ba', 3, 12, 'ስድስት ቀን ሥራህን ሁሉ ሥራ፤ በሬህና አህያህ ያርፉ ዘንድ ለባሪያህም ልጅ ለመጻተኛውም ዕረፍት ይሆን ዘንድ በሰባተኛው ቀን ዕረፍ።'),
  ('7780e3d5-0fe9-5239-adab-bd5969c00d76', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '995a9ab9-c102-5bae-a546-5bd7b52948ba', 4, 13, 'ያልኋችሁንም ነገር ሁሉ ጠብቁ፤ የሌሎችንም አማልክት ስም አትጥሩ፤ ከአፋችሁም አይሰማ።'),
  ('d88d4728-04b3-571b-a685-cb1123652ace', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '5901dd0b-5e7c-546c-a655-316752246b99', 1, 14, '“በዓመት ሦስት ጊዜ በዓል አድርጉልኝ።'),
  ('61d26a95-fd43-5153-a895-ad172d5cb004', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '5901dd0b-5e7c-546c-a655-316752246b99', 2, 15, 'የቂጣውን በዓል ጠብቁ፤ በአዲስ ወር ከግብፅ ምድር ወጥታችኋልና በዚህ ወር እንዳዘዝኋችሁ ሰባት ቀን ቂጣ ትበላላችሁ።'),
  ('866bacc8-d5d7-598e-a57c-a6a46bc4838b', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '5901dd0b-5e7c-546c-a655-316752246b99', 3, 16, 'በፊቴ ባዶ እጅህን አትታይ። በእርሻም የምትዘራትን የፍሬህን በኵራት የመከር በዓል፥ ዓመቱም ሲያልቅ ፍሬህን ከእርሻ ባከማቸህ ጊዜ የመክተቻውን በዓል ጠብቅ።'),
  ('dd1b1cda-3a6c-591f-acd6-860aa864181d', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '5901dd0b-5e7c-546c-a655-316752246b99', 4, 17, 'በዓመት ሦስት ጊዜ በአንተ ዘንድ ያለው ወንድ ሁሉ በአምላክህ በእግዚአብሔር ፊት ይታይ።'),
  ('d5696cdc-535f-525a-aa7a-0f63730c3422', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '5901dd0b-5e7c-546c-a655-316752246b99', 5, 18, '“የመሥዋዕቴን ደም ከቦካ እንጀራ ጋር አትሠዋ፤ የበዓሌም ስብ እስኪነጋ አይደር።'),
  ('f728aff9-7795-5fe5-a9a8-74b75c08e6d2', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', '5901dd0b-5e7c-546c-a655-316752246b99', 6, 19, 'የምድርህን ፍሬ በኵራት ወደ አምላክህ ወደ እግዚአብሔር ቤት አምጣ። ጠቦትን በእናቱ ወተት አትቀቅል።'),
  ('6adacebc-e398-5266-a956-c5d495e1e264', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 1, 20, '“በመንገድ ይጠብቅህ ዘንድ፥ ወዳዘጋጀሁልህም ስፍራ ያገባህ ዘንድ፥ እነሆ፥ እኔ መልአኬን በፊትህ እልካለሁ።'),
  ('a1faa43f-6b9f-579b-abc3-e4a7c86cdcb9', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 2, 21, 'ራስህን ጠብቅ፤ ስማው፤ እንቢም አትበለው፤ ስሜ በእርሱ ስለ ሆነ ይቅር አይልምና።'),
  ('2f412017-7421-5d2f-ad0c-78bb797770ea', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 3, 22, 'አንተ ግን ቃሌን ብትሰማ፥ ያልሁህንም ሁሉ ብታደርግ፥ ጠላቶችህን እጥላቸዋለሁ፤ የሚቃወሙህንም እቃወማለሁ።'),
  ('75c84ad1-0717-5571-a5cb-0e280a02a70e', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 4, 23, 'መልአኬ በፊትህ ይሄዳልና፥ ወደ አሞሬዎናውያንም፥ ወደ ኬጤዎናውያንም፥ ወደ ፌርዜዎናውያንም፥ ወደ ከነዓናውያንም፥ ወደ ጌርጌሴዎናውያንም፥ ወደ ኤዌዎናውያንም፥ ወደ ኢያቡሴዎናውያንም ያገባሃል፤ እኔም አጠፋቸዋለሁ።'),
  ('fd005e5d-d920-5e8d-ad57-7afb0b655af9', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 5, 24, 'ለአማልክቶቻቸው አትስገድ፤ አታምልካቸውም፤ እንደ ሥራቸውም አትሥራ፤ ነገር ግን ፈጽመህ አፍርሳቸው፤ ምስሎቻቸውንም ሰባብራቸው።'),
  ('9e749413-ba59-5571-a7e6-4b0f6340bef6', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 6, 25, 'አምላክህንም እግዚአብሔርን ታመልካለህ፤ እኔ እህልህንና ወይንህን፥ ውኃህንም እባርካለሁ፤ በሽታንም ከአንተ አርቃለሁ።'),
  ('c2616958-d648-54a0-a2a4-1b58e9149380', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 7, 26, 'በምድርህም መካን፥ ወይም የማይወልድ አይኖርም፤ የዘመንህንም ቍጥር እሞላለሁ።'),
  ('53cd1899-925f-5e5c-a81f-842c118917fc', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 8, 27, 'በፊትህ መፈራትን እሰድዳለሁ፤ የምትሄድበትን ሕዝብ ሁሉ አስደነግጣቸዋለሁ፤ ጠላቶችህንም ሁሉ እንዲሸሹልህ አደርጋለሁ።'),
  ('054dbc4f-0d1e-5288-a7c4-0f9ef5298feb', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 9, 28, 'በፊትህም ተርብ እሰድዳለሁ፤ አሞራዊውንም፥ ኤዌዎያዊውንም፥ ከነዓናዊውንም፥ ኬጤዎናዊውንም ከፊትህ ያባርራቸዋል።'),
  ('4cd7eb47-1623-5f02-a1a3-e7fc7bdfc206', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 10, 29, 'ምድር ባድማ እንዳትሆን፥ የምድር አራዊትም እንዳይበዙብህ፥ በአንድ ዓመት አላባርራቸውም።'),
  ('b4ddc62c-fea1-5f2b-a9d6-eb37d3763b33', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 11, 30, 'ነገር ግን እስክትበዛ፥ ምድርንም እስክትወርስ ድረስ ጥቂት በጥቂት አባርራቸዋለሁ።'),
  ('9b2dcfcf-c386-5a80-a535-304dbe158c59', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 12, 31, 'ድንበርህንም ከኤርትራ ባሕር እስከ ፍልስጥኤም ባሕር፥ ከምድረ በዳም እስከ ታላቁ እስከ ኤፍራጥስ ወንዝ ድረስ አሰፋለሁ፤ በምድር የሚኖሩትን በእጅህ እጥላለሁና፤ ከአንተም አስወጣቸዋለሁ።'),
  ('b888572f-494f-53e1-a7c1-f500605ab523', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 13, 32, 'ከእነርሱና ከአማልክቶቻቸው ጋር ቃል ኪዳን አታድርግ።'),
  ('0ff220f2-5c3f-54db-afba-325ddba60d90', 'd12ca06d-4f2b-5539-a5ea-d372246e559f', 'becd422e-99fd-55cf-a0af-4a15f4f9a31b', 14, 33, 'እኔን እንድትበድል እንዳያደርጉህ በሀገርህ ላይ አይቀመጡ፤ አማልክቶቻቸውንም ብታመልክ ወጥመድ ይሆኑብሃልና።”'),
  ('c3f6594d-af58-5d80-a60a-d9ca570591aa', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '7365dd58-4edc-58bd-ae80-59a6b8d82a8c', 1, 1, 'እግዚአብሔርም ሙሴን አለው፥ “አንተ፥ አሮንም፥ ናዳብም፥ አብዩድም፥ ከእስራኤልም ሰባ ሽማግሌዎች ወደ እግዚአብሔር ውጡ፤ በሩቁም ለእግዚአብሔር ስገዱ፤'),
  ('78bf6780-fcb2-5347-a69c-01e6dc70aa0e', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '7365dd58-4edc-58bd-ae80-59a6b8d82a8c', 2, 2, 'ሙሴም ብቻውን ወደ እግዚአብሔር ይቅረብ፤ እነርሱ ግን አይቅረቡ፤ ሕዝቡም ከእነርሱ ጋር አይውጡ።”'),
  ('d580e690-45e3-5ca0-a589-f94f24b194c5', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '7365dd58-4edc-58bd-ae80-59a6b8d82a8c', 3, 3, 'ሙሴም ገባ፤ ለሕዝቡም የእግዚአብሔርን ቃሎች ሁሉ፥ ሥርዐቱንም ሁሉ ነገረ፤ ሕዝቡም ሁሉ በአንድ ድምፅ፥ “እግዚአብሔር የተናገራቸውን ቃሎች ሁሉ እንሰማለን፤ እናደርጋለንም” ብለው መለሱ።'),
  ('bf30067b-67fc-5d01-a121-c21832bab06a', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '7365dd58-4edc-58bd-ae80-59a6b8d82a8c', 4, 4, 'ሙሴም የእግዚአብሔርን ቃሎች ጻፈ፤ ማለዳም ተነሣ፤ ከተራራውም በታች መሠዊያን ሠራ፤ ዐሥራ ሁለትም ድንጋዮችን ለዐሥራ ሁለቱ የእስራኤል ነገድ አቆመ።'),
  ('262607eb-6a3f-56ca-a886-33d7f461c82b', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '7365dd58-4edc-58bd-ae80-59a6b8d82a8c', 5, 5, 'የእስራኤልንም ልጆች ጐልማሶች ላከ፤ የሚቃጠል መሥዋዕትንም አቀረቡ፤ ለእግዚአብሔርም ስለ ደኅንነት መሥዋዕት በሬዎችን ሠዉ።'),
  ('ff65be38-b9de-5e97-a07d-ebebe83477f5', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '7365dd58-4edc-58bd-ae80-59a6b8d82a8c', 6, 6, 'ሙሴም የደሙን እኵሌታ ወስዶ በቆሬ ውስጥ አደረገው፤ የደሙንም እኵሌታ በመሠዊያው ረጨው።'),
  ('7b595a07-bfc0-5391-ad8a-a90e70d3978d', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '7365dd58-4edc-58bd-ae80-59a6b8d82a8c', 7, 7, 'የቃል ኪዳኑንም መጽሐፍ ወስዶ ለሕዝቡ አነበበላቸው፤ እነርሱም፥ “እግዚአብሔር ያለውን ሁሉ እንሰማለን፤ እናደርጋለንም” አሉ።'),
  ('37b8ffc1-8097-5383-a36a-4fe3bb4dc62d', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '7365dd58-4edc-58bd-ae80-59a6b8d82a8c', 8, 8, 'ሙሴም ደሙን ወስዶ በሕዝቡ ላይ ረጨው፤ በዚህ ቃል ሁሉ “እግዚአብሔር ከእናንተ ጋር ያደረገው የቃል ኪዳኑ ደም እነሆ” አለ።'),
  ('fed48acd-28c8-5296-a9fe-8ab9cc8f1fd2', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '7365dd58-4edc-58bd-ae80-59a6b8d82a8c', 9, 9, 'ሙሴም፥ አሮንም፥ ናዳብም፥ አብዩድም፥ ከእስራኤልም ሰባ ሽማግሌዎች ወጡ፤'),
  ('50403c71-a3a3-5b9f-ac11-eba949fd3705', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '7365dd58-4edc-58bd-ae80-59a6b8d82a8c', 10, 10, 'የእስራኤል አምላክ እግዚአብሔርም የቆመበትን ቦታ አዩ፤ ከእግሩም በታች እንደ ሰማይ መልክ የሚያበራ፥ እንደ ብሩህ ሰንፔር ድንጋይ የሚመስል ወለል ነበረ።'),
  ('88aeabeb-e9f1-5b8c-a8b4-f23394957436', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '7365dd58-4edc-58bd-ae80-59a6b8d82a8c', 11, 11, 'የሚመስላቸው የሌለ የእስራኤል ምርጦችም በእግዚአብሔር ቦታ ታዩ፤ በሉም፤ ጠጡም።'),
  ('3039d570-d25f-5c3f-aebc-f6a54db2b7fb', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '0b75db4b-d27b-5789-ada6-5af2ec1d7dd9', 1, 12, 'እግዚአብሔርም ሙሴን፥ “ወደ እኔ ወደ ተራራው ውጣ፤ በዚያም ሁን፤ እኔ የጻፍሁትን ሕግና ትእዛዝ፥ የድንጋይም ጽላት እሰጥሃለሁ፤ ሕግንም ትሠራላቸዋለህ” አለው።'),
  ('a1b69542-d979-5135-a7f7-4148ab63c9bb', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '0b75db4b-d27b-5789-ada6-5af2ec1d7dd9', 2, 13, 'ሙሴም ከኢያሱ ጋር ተነሣ፤ ወደ እግዚአብሔር ተራራም ወጡ።'),
  ('f60df669-e70a-575e-a301-06433cfd17db', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '0b75db4b-d27b-5789-ada6-5af2ec1d7dd9', 3, 14, 'ሽማግሌዎችንም፥ “ወደ እናንተ እስክንመለስ ድረስ በዚህ ቈዩን፤ ግርግር አትበሉ፤ አሮንና ሆርም እነሆ፥ ከእናንተ ጋር ናቸው፤ ነገረተኛም ቢኖር ወደ እነርሱ ይሂድ” አላቸው።'),
  ('7aef8ca8-91d5-56d2-af3c-29da7610020c', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '0b75db4b-d27b-5789-ada6-5af2ec1d7dd9', 4, 15, 'ሙሴም ከኢያሱ ጋር ወደ ተራራ ወጣ፤ ደመናውም ተራራውን ሸፈነው።'),
  ('25f343ab-4d1c-597a-a67c-9cd41e740f0a', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '0b75db4b-d27b-5789-ada6-5af2ec1d7dd9', 5, 16, 'የእግዚአብሔርም ክብር በሲና ተራራ ላይ ወረደ፤ ደመናውም ስድስት ቀን ሸፈነው፤ በሰባተኛውም ቀን እግዚአብሔር ከደመናው ውስጥ ሙሴን ጠራው።'),
  ('17737944-a39e-53dd-a078-b6cc9b31f707', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '0b75db4b-d27b-5789-ada6-5af2ec1d7dd9', 6, 17, 'በተራራውም ራስ ላይ በእስራኤል ልጆች ፊት የእግዚአብሔር ክብር መታየት እንደሚያቃጥል እሳት ነበረ።'),
  ('426063d1-ec87-556b-aac3-ea5b02a9b841', 'd8223676-ed38-5762-a5ef-7c44c37c20ba', '0b75db4b-d27b-5789-ada6-5af2ec1d7dd9', 7, 18, 'ሙሴም ወደ ደመናው ውስጥ ገባ፤ ወደ ተራራውም ወጣ፤ ሙሴም በተራራው ላይ አርባ ቀን፥ አርባ ሌሊትም ቈየ።'),
  ('fcf329a2-beb9-56ac-a88d-d949bbd00ee9', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '92eca1d5-8453-5d53-a77c-f4b3dae08d8a', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ሲል ተናገረው፦'),
  ('10f82e47-a42a-5354-a9cc-eae0bbd5b3fd', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '92eca1d5-8453-5d53-a77c-f4b3dae08d8a', 2, 2, '“የእስራኤልን ልጆች በልባችሁ ያሰባችሁትን ከገንዘባችሁ መባ አምጡልኝ” በላቸው።'),
  ('f6d23e85-c968-5ad6-a7fd-a126cb0eaf45', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '92eca1d5-8453-5d53-a77c-f4b3dae08d8a', 3, 3, 'ከእነርሱም የምትቀበሉት መባ ይህ ነው፤ ወርቅ፥ ብር፥ ናስም፥'),
  ('0eab1207-e7c6-5c07-a383-8b5609a5ef9b', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '92eca1d5-8453-5d53-a77c-f4b3dae08d8a', 4, 4, 'ሰማያዊና ሐምራዊ፥ ቀይም ድርብ ግምጃ፥ ጥሩ በፍታም፥'),
  ('7a771326-8344-5585-a8b6-30aab997c0ed', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '92eca1d5-8453-5d53-a77c-f4b3dae08d8a', 5, 5, 'የፍየልም ጠጕር፥ ቀይ የተለፋ የአውራ በግ ቍርበት፥ ሰማያዊ ቀለም የገባ ቍርበት፥ የማይነቅዝ ዕንጨት፥'),
  ('c780b946-06f9-5a4c-ad9a-58078286c857', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '92eca1d5-8453-5d53-a77c-f4b3dae08d8a', 6, 6, 'የመብራትም ዘይት፥ ለቅብዐት ዘይትና ለጣፋጭ ዕጣን ቅመም፥'),
  ('512bcd28-51c2-5fc2-aefa-87dcd4c2178f', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '92eca1d5-8453-5d53-a77c-f4b3dae08d8a', 7, 7, 'መረግድም፥ ለልብሰ እንግድዓና ለደረት ኪስ የሚደረግ ፈርጥ።'),
  ('575ff54e-274f-567c-a75e-8e42a436f51f', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '92eca1d5-8453-5d53-a77c-f4b3dae08d8a', 8, 8, 'መቅደስ ትሠራልኛለህ፤ በመካከላቸውም አድራለሁ።'),
  ('156eafc5-a0c2-582c-aa32-d56aa8d4b332', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '92eca1d5-8453-5d53-a77c-f4b3dae08d8a', 9, 9, 'በተራራው እንዳሳየሁህ ሁሉ፥ እንደ ማደሪያው ምሳሌ፥ እንደ ዕቃውም ሁሉ ምሳሌ ለእኔ ትሠራለህ፤ እንዲሁ ትሠራለህ።'),
  ('673bac80-0048-5e27-a2e6-b04be6470f08', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 1, 10, '“ከማይነቅዝ ዕንጨትም የምስክሩን ታቦት ሥራ፤ ርዝመቱ ሁለት ክንድ ተኩል፥ ወርዱም አንድ ክንድ ተኩል፥ ቁመቱም አንድ ክንድ ተኩል ይሁን።'),
  ('45177c08-1e63-5c0b-ad92-0e26ec5e8f6e', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 2, 11, 'በውስጥና በውጭም በጥሩ ወርቅ ለብጠው፤ በእርሱም ላይ በዙሪያው የወርቅ አክሊል አድርግለት።'),
  ('49c38838-f3ab-5087-a78c-58bf95f438d1', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 3, 12, 'አራት የወርቅ ቀለበቶችም አድርግለት፤ እነርሱንም በአራቱ እግሮቹ ላይ አኑር፤ በአንድ ወገን ሁለት ቀለበቶች፥ በሌላ ወገን ሁለት ቀለበቶች ይሁኑ።'),
  ('9c6a20b8-ccf3-56f1-a979-625ae5def607', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 4, 13, 'መሎጊያዎችንም ከማይነቅዝ ዕንጨት ሥራ፤ በወርቅም ለብጣቸው።'),
  ('1531f163-e213-5c58-a3af-a09e31354038', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 5, 14, 'ለታቦቱ መሸከሚያ በታቦቱ ጎን ባሉት አራት ቀለበቶች መሎጊያዎቹን አግባ።'),
  ('85004bcb-d926-5be8-a2b3-16c7214cb4ea', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 6, 15, 'መሎጊያዎቹም በታቦቱ ቀለበቶች ውስጥ ተዋድደው ይኑሩ፤ ከቶም አይውጡ።'),
  ('65cd6ece-b5c4-561c-a2e5-7886e7a70190', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 7, 16, 'በታቦቱም ውስጥ እኔ የምሰጥህን ምስክር ታስቀምጣለህ።'),
  ('2e472003-5c8e-539f-ac58-2803cd7f3a1a', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 8, 17, 'ከጥሩ ወርቅም ርዝመቱ ሁለት ክንድ ተኩል፥ ወርዱም አንድ ክንድ ተኩል የሆነ የስርየት መክደኛ ሥራ።'),
  ('c48dd101-9644-589c-a114-2fbb34d1a504', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 9, 18, 'ሁለት ኪሩቤል ከተቀጠቀጠ ወርቅ ሥራ፤ በስርየት መክደኛውም ላይ በሁለት ወገን ታደርጋቸዋለህ።'),
  ('572d8641-ee5e-5d86-a34e-6fd3f455fdd4', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 10, 19, 'ከስርየት መክደኛውም ጋር አንዱን ኪሩብ በአንድ ወገን፥ ሁለተኛውንም ኪሩብ በሌላው ወገን አድርገህ በአንድ ላይ ትሠራዋለህ፤ ሁለቱንም ኪሩቤል እንዲሁ በሁለት ወገን ታደርጋቸዋለህ።'),
  ('1d89ed0f-89d4-5bda-a094-a3b1781b908b', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 11, 20, 'ኪሩቤልም ክንፎቻቸውን ወደ ላይ ይዘረጋሉ፤ የስርየት መክደኛውንም በክንፎቻቸው ይሸፍናሉ፤ ፊታቸውም እርስ በርሱ ይተያያል፤ የኪሩቤልም ፊቶቻቸው ወደ ስርየት መክደኛው ይሁን።'),
  ('3f44d7a9-ba48-51f7-a669-db7793840c29', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 12, 21, 'የስርየት መክደኛውንም በታቦቱ ላይ ታደርገዋለህ፤ እኔም የምሰጥህን ምስክር በታቦቱ ውስጥ ታኖረዋለህ።'),
  ('026f6c56-0eb2-55b4-a2e4-fcc231b8abca', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '73050821-d5af-58ce-a946-1f19d5bb2709', 13, 22, 'በዚያም እገለጥልሃለሁ፤ ለእስራኤል ልጆች የማዝዝህን ሁሉ፥ በምስክሩ ታቦት ላይ ባለው በሁለት ኪሩቤል መካከል፥ በስርየት መክደኛውም ላይ ሆኜ እነጋገርሃለሁ።'),
  ('e6771205-afc4-573a-a3a7-cfd203bdfe6d', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '12bbd931-c9b3-5126-a9c5-cf816c0f032b', 1, 23, '“ርዝመቱም ሁለት ክንድ፥ ወርዱም አንድ ክንድ፥ ቁመቱም አንድ ክንድ ተኩል የሆነ ገበታ ከማይነቅዝ ዕንጨት ሥራ።'),
  ('dac9e35a-88a0-53ba-a92e-ee5d0e81771a', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '12bbd931-c9b3-5126-a9c5-cf816c0f032b', 2, 24, 'በጥሩም ወርቅ ትለብጠዋለህ፤ በዙሪያውም የወርቅ አክሊል አድርግለት፤'),
  ('97218c5a-223d-5ebf-a1c2-44bccf4f037c', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '12bbd931-c9b3-5126-a9c5-cf816c0f032b', 3, 25, 'በዙሪያውም አንድ ጋት የሚያህል ክፈፍ አድርግለት፤ የወርቅም አክሊል በክፈፉ ዙሪያ አድርግለት።'),
  ('4c5ec0fc-9216-5403-a443-65d76bd1ed3d', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '12bbd931-c9b3-5126-a9c5-cf816c0f032b', 4, 26, 'አራትም የወርቅ ቀለበቶች አድርግለት፤ ቀለበቶቹንም አራት እግሮቹ ባሉበት በአራቱ ማዕዘኖች አድርግ።'),
  ('3e1fd083-caf4-5cda-a030-1e2e792b2326', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '12bbd931-c9b3-5126-a9c5-cf816c0f032b', 5, 27, 'ቀለበቶቹም ገበታውን ለመሸከም መሎጊያዎቹ እንዲሰኩባቸው በክፈፉ አቅራቢያ ይሁኑ።'),
  ('f407fa5f-1284-5846-a474-515b0add2502', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '12bbd931-c9b3-5126-a9c5-cf816c0f032b', 6, 28, 'መሎጊያዎቹንም ከማይነቅዝ ዕንጨት ሥራ፤ በንጹሕ ወርቅም ለብጣቸው፤ ገበታውም በእነርሱ ይነሣ።'),
  ('7e2a821b-edfe-5433-a673-06a5bcedde35', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '12bbd931-c9b3-5126-a9c5-cf816c0f032b', 7, 29, 'ለማፍሰሻም ይሆኑ ዘንድ ወጭቶችዋን፥ ጭልፋዎችዋንም፥ መቅጃዎችዋንም፥ ጽዋዎችዋንም አድርግ፤ እነርሱንም ከጥሩ ወርቅ አድርጋቸው።'),
  ('e1b35b11-a302-5c28-a6d4-348d353e9493', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '12bbd931-c9b3-5126-a9c5-cf816c0f032b', 8, 30, 'በገበታም ላይ ኅብስተ ገጹን ሁልጊዜ በፊቴ ታደርጋለህ።'),
  ('4ffc4f64-3f40-51a6-a8bc-279591b560b8', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '932c6bda-917d-5209-aadf-3e34e5039f97', 1, 31, '“መቅረዝንም ከጥሩ ወርቅ አድርግ፤ የመቅረዙም እግሩና ቅርንጫፎቹ የተቀጠቀጠ ሥራ ይሁን፤ ጽዋዎቹም፥ ጕብጕቦቹም፥ አበቦቹም አንድነት በእርሱ ይደረጉበት።'),
  ('08e235a5-12cb-56c7-a728-598f4cb1e6b1', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '932c6bda-917d-5209-aadf-3e34e5039f97', 2, 32, 'በስተጐኑ ስድስት ቅርንጫፎች ይውጡለት፤ ሦስት የመቅረዙ ቅርንጫፎች በአንድ ወገን፥ ሦስትም የመቅረዙ ቅርንጫፎች በሌላ ወገን ይውጡ።'),
  ('10595345-bd43-5dee-ad1d-9d14c05d394c', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '932c6bda-917d-5209-aadf-3e34e5039f97', 3, 33, 'በአንደኛውም ቅርንጫፍ ጕብጕብና አበባ፥ ሦስትም የለውዝ አበባ የሚመስሉትን ጽዋዎች፤ በሁለተኛውም ቅርንጫፍ ጕብጕብና አበባ፥ ሦስትም የለውዝ አበባ የሚመስሉትን ጽዋዎች፤ እንዲሁም ከመቅረዙ ለሚወጡ ለስድስት ቅርንጫፎች አድርግ።'),
  ('bb25057b-c8f6-59b8-aec4-8dfc3b28790d', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '932c6bda-917d-5209-aadf-3e34e5039f97', 4, 34, 'በመቅረዙም ጕብጕቦቹንና አበቦቹን፥ አራትም የለውዝ አበባ የሚመስሉትን ጽዋዎች ከእርሱ አድርግ።'),
  ('c7bcca7e-641f-5c4c-abb8-273f11e406d4', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '932c6bda-917d-5209-aadf-3e34e5039f97', 5, 35, 'ከመቅረዙ ለሚወጡ ለስድስቱ ቅርንጫፎች ከሁለት ቅርንጫፎች በታች አንድ ሆኖ የተሠራ አንድ ጕብጕብ፥ ከሁለቱም ቅርንጫፎች በታች አንድ ሆኖ የተሠራ አንድ ጕብጕብ፥ ደግሞ ከሁለት ቅርንጫፎች በታች አንድ ሆኖ የተሠራ አንድ ጕብጕብ ይሁን።'),
  ('74373243-1625-5fb7-a1d1-4cfba756b7a3', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '932c6bda-917d-5209-aadf-3e34e5039f97', 6, 36, 'ጕብጕቦቹና ቅርንጫፎቹ ሁሉ ከእርሱ ጋር አንድ ይሁኑ፤ ሁሉም አንድ ሆኖ ከተቀጠቀጠ ከጥሩ ወርቅ ይደረግ።'),
  ('405896ff-fc56-597e-aaaf-0fe8b04e8f2e', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '932c6bda-917d-5209-aadf-3e34e5039f97', 7, 37, 'ሰባቱንም መብራቶች ሥራ፤ በፊቱ ያበሩ ዘንድ መብራቶቹን ያቀጣጥሉአቸዋል።'),
  ('e5c0fb0e-0434-5d32-ad3e-7fc5a5b323c6', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '932c6bda-917d-5209-aadf-3e34e5039f97', 8, 38, 'መኰስተሪያዎችዋን፥ የኵስታሪ ማድረጊያዎችዋንም ከጥሩ ወርቅ አድርግ።'),
  ('23b851f4-e08f-575d-abf0-e5b135de85a7', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '932c6bda-917d-5209-aadf-3e34e5039f97', 9, 39, 'መቅረዙም፥ ዕቃውም ሁሉ ከአንድ መክሊት ጥሩ ወርቅ ይሠሩ።'),
  ('c840dae1-378e-5051-a131-152013745de6', 'fbddbf56-b08d-5ef8-aa3c-737d1f1d61ee', '932c6bda-917d-5209-aadf-3e34e5039f97', 10, 40, 'በተራራ ላይ እንዳሳየሁህ ምሳሌ እንድትሠራ ተጠንቀቅ።'),
  ('01fceff0-2fb8-5df3-a24a-4c2a69ebb422', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 1, 1, '“ለድንኳኑም ከተፈተለ ከጥሩ በፍታ፥ ከሰማያዊ፥ ከሐምራዊም፥ ከቀይም ግምጃ ዐሥር መጋረጆችን ሥራ፤ ኪሩቤልም በእነርሱ ላይ ይሁኑ፤ እንደ ሽመና ሥራም በብልሃት ትሠራቸዋለህ።'),
  ('8cdf3210-cb22-5ae9-aa9b-779d28086b27', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 2, 2, 'የእያንዳንዱ መጋረጃ ርዝመት ሃያ ስምንት ክንድ፥ ወርዱም አራት ክንድ ይሁን፤ የመጋረጆችም ሁሉ መጠን ትክክል ይሁን።'),
  ('13492d30-a508-5ef9-ab51-9238f1600b6c', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 3, 3, 'አምስቱ መጋረጃዎች እርስ በርሳቸው የተጋጠሙ ይሁኑ፤ ሌሎችም አምስት መጋረጃዎች እንዲሁ እርስ በርሳቸው የተጋጠሙ ይሁኑ።።'),
  ('db49f72f-52a2-5272-a4db-061963e64f98', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 4, 4, 'ከሚጋጠሙት መጋረጆች በአንደኛው መጋረጃ ዘርፍ ላይ የሰማያዊውን ግምጃ ቀለበቶች አድርግ፤ ደግሞ ከተጋጠሙት ከሌሎች በአንደኛው መጋረጃ ዘርፍ ላይ በውጭ በኩል እንዲሁ አድርግ።'),
  ('e66c1816-cd7d-5537-a9c9-9ed2b4172962', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 5, 5, 'አምሳ ቀለበቶችን በአንድ መጋረጃ አድርግ፤ አምሳውንም ቀለበቶች በሁለተኛው መጋረጃ ዘርፍ አድርግ፤ ቀለበቶቹ ሁሉ እርስ በርሳቸው ፊት ለፊት ይሆናሉ።'),
  ('197bc876-b3cb-5e1a-a0b3-cd1cf881b46c', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 6, 6, 'አምሳ የወርቅ መያዣዎች ሥራ፤ መጋረጃዎችን እርስ በርሳቸው በመያዣዎች አጋጥማቸው፤ ድንኳኑም አንድ ይሆናል።'),
  ('8f81f168-c052-550a-a393-a428af1f2a44', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 7, 7, '“ከማደሪያውም በላይ ለድንኳን የሚሆኑ መጋረጃዎች ከፍየል ጠጕር አድርግ፤ ዐሥራ አንድ መጋረጃዎች ታደርጋለህ።'),
  ('eb1c1455-2bce-5862-a6a7-40ac03080379', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 8, 8, 'እያንዳንዱም መጋረጃ ርዝመቱ ሠላሳ ክንድ፥ እያንዳንዱም መጋረጃ ወርዱ አራት ክንድ ይሁን፤ የዐሥራ አንዱም መጋረጃዎች መጠናቸው ትክክል ይሁን።'),
  ('c519aa6b-f8bd-5f70-ae24-286f9e6d3530', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 9, 9, 'አምስቱ መጋረጃዎች እርስ በርሳቸው አንድ ሆነው ይጋጠሙ፤ ስድስቱም መጋረጃዎች እርስ በርሳቸው አንድ ሆነው ይጋጠሙ፤ ስድስተኛውም መጋረጃ በድንኳኑ ፊት ይደረብ።'),
  ('7c9a1429-43f9-575f-a7fb-e47b76e7c588', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 10, 10, 'በውጭ ከተጋጠሙት መጋረጃዎች በአንደኛው መጋረጃ ዘርፍ ላይ አምሳ ቀለበቶች አድርግ፤ ደግሞ ከተጋጠሙት ከሌሎቹ በአንደኛው መጋረጃ ዘርፍ ላይ እንዲሁ አምሳ ቀለበቶች አድርግ።'),
  ('e1bab485-d854-5fec-af75-ddaf3fe12db2', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 11, 11, 'አምሳም የናስ መያዣዎችን ሥራ፤ መያዣዎችንም ወደ ቀለበቶች አግባቸው፤ መጋረጃዎችንም አጋጥማቸው፤ አንድም ይሆናሉ።'),
  ('7fe98f96-4ffc-57f2-a12a-215ecb1f4e76', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 12, 12, 'ከድንኳኑ መጋረጃዎች የቀረ ትርፍ ግማሽ መጋረጃ በድንኳኑ ጀርባ ይጋረድ።'),
  ('096ca610-8f4f-5458-a342-8c5360ae1f86', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 13, 13, 'ድንኳኑን እንዲሸፍን ከርዝመቱ በአንድ ወገን አንድ ክንድ፤ በአንድ ወገንም አንድ ክንድ ከድንኳኑ መጋረጆች የቀረው ትርፍ በድንኳኑ ውጭ በወዲህና በወዲያ ይጋረድ።'),
  ('af3076ce-2bcd-5d89-a3d2-575a5414ab1f', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 14, 14, 'ለድንኳኑም መደረቢያ ከቀይ አውራ በግ ቍርበት፥ ከዚያም በላይ ሌላ መደረቢያ ከአቆስጣ ቍርበት አድርግ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4187dd33-b19a-5ad8-aaef-197077e8c72a', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 15, 15, '“ለድንኳኑም ሳንቆችን ከማይነቅዝ ዕንጨት አድርግ።'),
  ('214a8465-a38f-58c6-a5df-49c8eaf5723a', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 16, 16, 'የእያንዳንዱም ሳንቃ ርዝመቱ ዐሥር ክንድ፥ ወርዱም አንድ ክንድ ተኩል ይሁን።'),
  ('b0e9883f-0437-5959-af99-e8dba1860e03', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 17, 17, 'ለእያንዳንዱም ሳንቃ አንዱን በአንዱ ላይ የሚያያይዙ ሁለት ማጋጠሚያዎች ይሁኑለት፤ ለድንኳኑ ሳንቆች ሁሉ እንዲሁ አድርግ።'),
  ('32ecb7d7-4ced-503a-af66-d9efd2fc95f9', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 18, 18, 'ለድንኳኑም በደቡብ በኩል ሃያ ሳንቆችን አድርግ።'),
  ('6eaf6386-a890-50d9-acec-614afbae2f4d', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 19, 19, 'ከሃያውም ሳንቆች በታች አርባ የብር እግሮችን አድርግ፤ ከእያንዳንዱ ሳንቃ በታች ለሁለት ማጋጠሚያዎች ሁለት እግሮች ይሁኑ። ከሌላውም ሳንቃ በታች ለሁለት ማጋጠሚያዎች ሁለት እግሮች ይሁኑ።'),
  ('0457bb9b-89f5-50a8-a8ad-26ed39f5bae3', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 20, 20, 'ለድንኳኑ ለሁለተኛው ወገን በሰሜን በኩል ሃያ ሳንቆች፥'),
  ('b794ae87-a6a0-5c69-a754-8ac1eef2c436', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 21, 21, 'ለእነርሱም አርባ የብር እግሮች ይሁኑ፤ ከእያንዳንዱም ሳንቃ በታች ሁለት እግሮች ይሁኑ።'),
  ('b7019bd9-b9e1-59eb-afba-ccb5b2dc0466', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 22, 22, 'ለድንኳኑም በምዕራቡ በኩል በስተኋላ ስድስት ሳንቆች አድርግ።'),
  ('817ea6ca-4cc4-52b5-af63-ceeaa54aa52e', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 23, 23, 'ለድንኳኑም ለሁለቱ ማዕዘን በስተኋላ ሁለት ሳንቆች አድርግ።'),
  ('67be40c3-eff8-5b7b-aeed-bc281d1c2aa9', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 24, 24, 'ከታችም እኩል ይሁኑ፤ ከላይ እስከ አንደኛው መጋጠሚያ ድረስ እንደ አንደኛ ክፍል እኩል ይሁኑ፤ እንዲሁም ለሁለቱ ማዕዘን አድርግ፤ እኩልም ይሁኑ።'),
  ('c74942e1-056e-50e6-a696-2497306ea439', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 25, 25, 'ስምንት ሳንቆችና ዐሥራ ስድስት የብር እግሮቻቸው ይሁኑ፤ ከእያንዳንዱም ሳንቃ በታች በሁለቱም መጋጠሚያዎች ሁለት ሁለት እግሮች ይሆናሉ።'),
  ('953a2048-faa8-5572-ade3-9ca6b961f078', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 26, 26, '“ከማይነቅዝ ዕንጨት መወርወሪያዎችን ሥራ፤ በድንኳኑ በአንደኛው ገጽ ላሉ ሳንቆች አምስት መወርወሪያዎችን፥'),
  ('67bac246-8f04-5bab-af8c-225aaf31bcd0', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 27, 27, 'በድንኳኑ በሁለተኛ ወገን ላሉት ሳንቆች አምስት መወርወሪያዎችን፥ በድንኳኑም በስተኋላ በምዕራብ በኩል ላሉት ሳንቆች አምስት መወርወሪያዎችን አድርግ።'),
  ('13001a98-28f7-54a8-a4cf-c39040aa1e55', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 28, 28, 'መካከለኛውም መወርወሪያ በሳንቆቹ መካከል ከዳር እስከ ዳር ይለፍ።'),
  ('c85bb621-a82c-5b91-acec-016b0bdc3b6a', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 29, 29, 'ሳንቆቹን በወርቅ ለብጣቸው፤ ቀለበቶቻቸውንም የመወርወሪያ ቤት እንዲሆኑላቸው ከወርቅ ሥራቸው፤ መወርወሪያዎችንም በወርቅ ለብጣቸው።'),
  ('a5f1a6d7-0915-5d98-a11d-9804c0e50f77', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 30, 30, 'ድንኳኑንም በተራራው ላይ በአሳየሁህ ምሳሌ ሥራ።'),
  ('3f32fe32-6df1-5e36-aef7-bcaf264829d9', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 31, 31, '“መጋረጃውንም ከሰማያዊ፥ ከሐምራዊም፥ ከቀይም ግምጃ ከተፈተለ ከጥሩ በፍታም አድርግ፤ በሽመና ሥራም ኪሩቤልን ሥራ።'),
  ('2c3f9536-a147-5e0c-ab5b-b769e145bd24', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 32, 32, 'በወርቅ በተለበጡት፥ ከማይነቅዝ ዕንጨትም በተሠሩት በአራቱ ምሰሶዎች ላይ ስቀለው፤ ኩላቦቻቸውም ከወርቅ፥ አራቱም እግሮቻቸው ከብር የተሠሩ ይሁኑ።'),
  ('ca513b11-a6b8-52d1-a498-4ba1bbaedfe8', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 33, 33, 'መጋረጃውንም በምሰሶዎች ላይ ስቀለው፤ በመጋረጃውም ውስጥ የምስክሩን ታቦት አግባው፤ መጋረጃውም በቅድስቱና በቅድስተ ቅዱሳኑ መካከል መለያ ይሁናችሁ።'),
  ('7f54e938-4912-5ae5-a360-44eeea00d356', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 34, 34, 'መጋረጃውም የምስክሩን ታቦት በቅድስተ ቅዱሳኑ ውስጥ ይጋርድ።'),
  ('ec2f1617-bcba-5b52-ad86-b8a2bd5e56a9', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 35, 35, 'ገበታውንም በመጋረጃው ውጭ፥ መቅረዙንም በገበታው ፊት ለፊት በድንኳኑ በደቡብ ወገን አድርግ፤ ገበታውንም በድንኳኑ በሰሜን ወገን አድርገው።'),
  ('4daf3628-3132-5f86-a0c5-9078519ad9c9', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 36, 36, 'ለድንኳኑ ደጃፍም ከሰማያዊ፥ ከሐምራዊም፥ ከቀይ ግምጃም ከተፈተለ ከጥሩ በፍምታም በጥልፍ አሠራር የተሠራ መጋረጃ አድርግለት።'),
  ('7a3ff7d9-27d0-5d52-a326-0dc709237cc6', 'b34d02c4-2e12-5ceb-aad1-03aeadcb977f', '5c8bc9ce-4ef2-5c71-a52b-3871f3548254', 37, 37, 'ለመጋረጃውም አምስት ምሰሶዎች ከማይነቅዝ ዕንጨት አድርግ፤ በወርቅም ለብጣቸው፤ ኩላቦቻቸውም ከወርቅ የተሠሩ ይሁኑ፤ አምስትም የናስ እግሮች አድርግላቸው።'),
  ('89c38ab9-5706-564f-a623-015debef54ca', '55d325b2-7063-522b-a8a5-ae483488597b', '1d1ebb73-25b4-577e-a75a-be78b14c41f8', 1, 1, '“ርዝመቱ አምስት ክንድ፥ ወርዱም አምስት ክንድ መሠዊያን ከማይነቅዝ ዕንጨት አድርግ፤ አራት ማዕዘንም ይሁን፤ ከፍታውም ሦስት ክንድ ይሁን።'),
  ('6cd2ce08-2d95-5cbc-a3f0-168a4b695107', '55d325b2-7063-522b-a8a5-ae483488597b', '1d1ebb73-25b4-577e-a75a-be78b14c41f8', 2, 2, 'በአራቱም ማዕዘን ቀንዶችን ታደርጋለህ፤ ቀንዶቹ ሥረ-ወጥ ይሁኑ፤ በናስም ለብጣቸው።'),
  ('55a29e9c-4515-58dd-a34a-722e340b094c', '55d325b2-7063-522b-a8a5-ae483488597b', '1d1ebb73-25b4-577e-a75a-be78b14c41f8', 3, 3, 'ለመሠዊያው ክዳን ሥራለት፤ መሸፈኛውን፥ ጽዋዎቹን፥ የሥጋ ሜንጦዎቹን፥ የእሳት መጫሪያዎቹንም አድርግ። ዕቃውንም ሁሉ ከናስ አድርግ።'),
  ('70a44408-f3c2-521a-ae95-f519eab9d247', '55d325b2-7063-522b-a8a5-ae483488597b', '1d1ebb73-25b4-577e-a75a-be78b14c41f8', 4, 4, 'ለመሠዊያውም እንደ መረብ ሆኖ የተሠራ የናስ መከታ አድርግለት፤ ለመከታውም አራት የናስ ቀለበት በአራት ማዕዘኑ አድርግለት።'),
  ('9453e849-828d-560c-aed6-90c16ddfa256', '55d325b2-7063-522b-a8a5-ae483488597b', '1d1ebb73-25b4-577e-a75a-be78b14c41f8', 5, 5, 'መከታውም እስከ መሠዊያው እኩሌታ ይደርስ ዘንድ ከመሠዊያው እርከን በታች አኑረው።'),
  ('6ac35d64-089c-5ae4-aca9-4f514913d3e8', '55d325b2-7063-522b-a8a5-ae483488597b', '1d1ebb73-25b4-577e-a75a-be78b14c41f8', 6, 6, 'ለመሠዊያውም ከማይነቅዝ ዕንጨት መሎጊያዎችን ሠርተህ በናስ ለብጣቸው፤ መሎጊያዎቹም በቀለበቶች ውስጥ ይግቡ፤'),
  ('1a1d23a8-e94e-567c-a40d-b3ed4aadafdd', '55d325b2-7063-522b-a8a5-ae483488597b', '1d1ebb73-25b4-577e-a75a-be78b14c41f8', 7, 7, 'መሠዊያውንም ስትሸከሙ መሎጊያዎቹ በመሠዊያው በሁለት ወገን ይሁኑ።'),
  ('3e8ea4a3-c119-5285-a375-4962a052d1c2', '55d325b2-7063-522b-a8a5-ae483488597b', '1d1ebb73-25b4-577e-a75a-be78b14c41f8', 8, 8, 'ሰሌዳውም ፍልፍል ይሁን፤ በተራራው እንዳሳየሁህ ምሳሌ እንዲሁ አድርግ።'),
  ('0797d8ef-988e-5622-aaa3-4bb5fd49b0d0', '55d325b2-7063-522b-a8a5-ae483488597b', '9e13a25b-fb0b-50bb-aa45-1ef3d2cdedac', 1, 9, '“ለድንኳኑም አደባባይ ሥራ፤ ከጥሩ በፍታ የተሠሩ የአደባባዩ መጋረጃዎችም በደቡብ በኩል ይሁኑ። የአንዱም ወገን ርዝመት መቶ ክንድ ይሁን፤'),
  ('a7794eb6-c1fc-5a07-a4e8-f93579172cf3', '55d325b2-7063-522b-a8a5-ae483488597b', '9e13a25b-fb0b-50bb-aa45-1ef3d2cdedac', 2, 10, 'ከናስ የተሠሩ ሃያ ምሰሶዎችና ሃያ እግሮች ይሁኑለት፤ የምሰሶዎቹም ኩላቦችና ዘንጎች የብር ይሁኑ።'),
  ('974d7dab-d176-59e0-ae0d-a57b02535adc', '55d325b2-7063-522b-a8a5-ae483488597b', '9e13a25b-fb0b-50bb-aa45-1ef3d2cdedac', 3, 11, 'እንዲሁም በሰሜን ወገን መቶ ክንድ ርዝመት ያላቸው መጋረጃዎች፥ ከናስ የተሠሩ ሃያ ምሰሶዎች፥ ሃያም እግሮች ይሁኑ፤ ለምሰሶዎችም በብር የተለበጡ ኩላቦችና ዘንጎች ይሁኑ።'),
  ('75f5fca9-0d3b-5541-ad1e-85cb3cded9da', '55d325b2-7063-522b-a8a5-ae483488597b', '9e13a25b-fb0b-50bb-aa45-1ef3d2cdedac', 4, 12, 'በምዕራብም ወገን ለአደባባዩ ስፋት አምሳ ክንድ ርዝመት ያላቸው መጋረጃዎች፥ ዐሥርም ምሰሶዎች፥ ዐሥርም እግሮች ይሁኑለት።'),
  ('153ef03a-7d46-57b2-a69a-db0d52578e7d', '55d325b2-7063-522b-a8a5-ae483488597b', '9e13a25b-fb0b-50bb-aa45-1ef3d2cdedac', 5, 13, 'በምሥራቅም ወገን የአደባባዩ ስፋት አምሳ ክንድ ይሁን፤ ምሰሶዎችም ዐሥር፥ እግሮቹም ዐሥር ይሁኑ።'),
  ('36b96dad-662a-5cb1-ae52-69c8472fe46e', '55d325b2-7063-522b-a8a5-ae483488597b', '9e13a25b-fb0b-50bb-aa45-1ef3d2cdedac', 6, 14, 'በአንድ ወገን የመጋረጃዎቹ ርዝመት ዐሥራ አምስት ክንድ ይሁን፤ ምሰሶዎቹም ሦስት፥ እግሮቹም ሦስት ይሁኑ።'),
  ('4527e4d9-014b-5cbc-a10f-a232f7a80333', '55d325b2-7063-522b-a8a5-ae483488597b', '9e13a25b-fb0b-50bb-aa45-1ef3d2cdedac', 7, 15, 'በሌላውም ወገን የመጋረጃዎቹ ርዝመት ዐሥራ አምስት ክንድ ይሆናል፤ ምሰሶዎቹም ሦስት፥ እግሮቹም ሦስት ይሁኑ።'),
  ('3a8fc3c4-d227-5840-a6ec-5cf1d7743b54', '55d325b2-7063-522b-a8a5-ae483488597b', '9e13a25b-fb0b-50bb-aa45-1ef3d2cdedac', 8, 16, 'ለአደባባዩ ደጅም ከሰማያዊ፥ ከሐምራዊም ከቀይም ግምጃ ከጥሩ በፍታም በጥልፍ አሠራር የተሠራ ሃያ ክንድ መጋረጃ ይሆናል፤ ምሰሶዎቹም አራት፥ እግሮቹም አራት ይሁኑ።'),
  ('0d492266-0ff6-52ae-a222-5b719e96ce18', '55d325b2-7063-522b-a8a5-ae483488597b', '9e13a25b-fb0b-50bb-aa45-1ef3d2cdedac', 9, 17, 'በዙሪያውም ያሉ የአደባባዩ ምሰሶዎች ሁሉ በብር የተለበጡ ይሁኑ፤ የብርም ክባሶች፥ የናስም እግሮች ይሁኑላቸው።'),
  ('6f6fb390-0d19-5809-a3e8-7f11c2885eab', '55d325b2-7063-522b-a8a5-ae483488597b', '9e13a25b-fb0b-50bb-aa45-1ef3d2cdedac', 10, 18, 'የአደባባዩ ርዝመት በየገጹ መቶ ክንድ፥ ስፋቱም በየገጹ አምሳ ክንድ ይሁን፤ የመጋረጃውም ከፍታ አምስት ክንድ ይሁን፤ መጋረጃውም ከጥሩ በፍታ፥ እግሮቹም ከናስ የተሠሩ ይሁኑ።'),
  ('b9a48d06-d3dd-567d-ae44-17dc2ffd69bd', '55d325b2-7063-522b-a8a5-ae483488597b', '9e13a25b-fb0b-50bb-aa45-1ef3d2cdedac', 11, 19, 'ለማገልገል ሁሉ የድንኳን ዕቃ ሁሉ፥ አውታሮቹ ካስማዎቹም ሁሉ፤ የአደባባዩም ካስማዎች ሁሉ የናስ ይሁኑ።'),
  ('9f547e62-241b-5fb6-a2dc-79f3b32df7c2', '55d325b2-7063-522b-a8a5-ae483488597b', 'e5d0ced0-4a50-5039-a42d-902e870f75c7', 1, 20, '“አንተም መብራቱን ሁል ጊዜ ያበሩት ዘንድ ለመብራት ተወቅጦ የተጠለለ ጥሩ የወይራ ዘይት እንዲያመጡልህ የእስራኤልን ልጆች እዘዛቸው።'),
  ('48d1696b-c443-542f-abb6-97281cbe0ff9', '55d325b2-7063-522b-a8a5-ae483488597b', 'e5d0ced0-4a50-5039-a42d-902e870f75c7', 2, 21, 'በምስክሩ ድንኳን ውስጥ በቃል ኪዳኑ ታቦት ፊት ካለው መጋረጃ ውጭ አሮንና ልጆቹ ከማታ እስከ ማለዳ ድረስ በእግዚአብሔር ፊት ያብሩት፤ በእስራኤል ልጆች ዘንድ ለልጅ ልጃቸው የዘለዓለም ሥርዐት ይሁን።'),
  ('a1879986-1ce0-5dcf-ad02-971f979e3bfd', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 1, 1, '“አንተም ወንድምህን አሮንን ከእርሱም ጋር ልጆቹን ከእስራኤል ልጆች መካከል ለይተህ በክህነት ያገለግሉኝ ዘንድ ወደ አንተ አቅርብ፤ አሮንን የአሮንንም ልጆች፥ ናዳብን፥ አብዩድንም፥ አልዓዛርንም ኢታምርንም አቅርብ።'),
  ('5fd7c517-c83b-5b3c-a4fa-26d334b5fe7f', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 2, 2, 'የተቀደሰውንም ልብስ ለክብርና ለመለያ እንዲሆን ለወንድምህ ለአሮን ሥራለት።'),
  ('c371caff-335e-5c8e-a5b9-1b244977d848', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 3, 3, 'አንተም የጥበብ መንፈስ ለሞላሁባቸው፥ በልባቸው ጥበበኞች ለሆኑት ሁሉ ተናገር። እነርሱም ካህን ሆኖ እንዲያገለግለኝ ለአሮን ለቤተ መቅደስ የሚሆን የተለየ ልብስ ይሥሩ፤'),
  ('cc076ef5-6d07-59b5-a800-8f43dd64af09', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 4, 4, 'የሚሠሩአቸውም ልብሶች እነዚህ ናቸው፤ ልብሰ እንግድዓ፥ ልብሰ መትከፍ፥ ቀሚስም፥ ዥንጕርጕር እጀ ጠባብ፥ መጠምጠሚያ፥ መታጠቂያም፤ እነዚህንም በክህነት ያገለግሉኝ ዘንድ ለወንድምህ ለአሮን፥ ለልጆቹም የተቀደሰ ልብስ ያድርጉ።'),
  ('2400a2fa-4a21-563a-a4ae-9e9ae7dbe9ed', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 5, 5, 'ወርቅ፥ ሰማያዊና ሐምራዊ፥ ቀይ ግምጃ፥ ጥሩ በፍታም ይውሰዱ።'),
  ('d986c6ae-a485-5119-a433-bdb5bd7b833b', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 6, 6, '“ልብሰ መትከፉንም ከወርቅ፥ ከሰማያዊና ከሐምራዊ፥ ከተፈተለ ከቀይ ግምጃ በግብረ መርፌ የተሠራ፥ የተለየ የሽመና ሥራ ያድርጉ።'),
  ('9169d0a1-fd43-57fd-adc1-c93fc854d32f', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 7, 7, 'ሁለቱ ወገን አንድ እንዲሆን በሁለቱ ጫንቃ ላይ የሚጋጠም ጨርቅ ይሁን።'),
  ('103b0a7e-3479-5079-a091-60e3d39922ac', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 8, 8, 'በላዩም የተጠለፈው የልብሰ መትከፍ ቋድ እንደ እርሱ፥ ከእርሱም ጋር አንድ ይሁን፤ ከወርቅ፥ ከሰማያዊ፥ ከሐምራዊ፥ ከቀይ ግምጃም ከተፈተለ፥ ከጥሩ በፍታም የተሠራ ይሁን።'),
  ('65064b70-8436-5210-ab7c-83b89a742a21', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 9, 9, 'ሁለትም የመረግድ ድንጋይ ወስደህ የእስራኤልን ልጆች ስም ስማቸውን ቅረጽባቸው፤'),
  ('d4c68547-14c9-554b-a51c-cd2f214302b4', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 10, 10, 'እንደ አወላለዳቸው ስድስት ስሞችን በአንዱ ድንጋይ፥ የቀሩትንም ስድስቱን ስሞች በሌላው ድንጋይ ቅረጽ።'),
  ('731f0579-83d2-5f7f-a16a-c2f293ad50e0', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 11, 11, 'በቅርጽ ሠራተኛ ሥራ እንደ ማኅተም ቅርጽ አድርገህ የእስራኤልን ልጆች ስሞች በሁለት ድንጋዮች ቅረጽ፤ በወርቅም ፈርጥ አድርግ።'),
  ('b3d4b2a8-9120-5d49-a1d4-1aa9ce7fc386', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 12, 12, 'ለእስራኤል ልጆችም የመታሰቢያ ድንጋዮች ይሆኑ ዘንድ ሁለቱን ዕንቍዎች በልብሰ መትከፉ ጫንቃዎች ላይ ታደርጋለህ፤ አሮንም በሁለቱ ጫንቃዎች ላይ ለመታሰቢያ ስማቸውን በእግዚአብሔር ፊት ይሸከማል።'),
  ('f129178a-a939-515f-a56e-4521ebbf7756', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 13, 13, 'ፈርጦችንም ከጥሩ ወርቅ ሥራ፤'),
  ('fff89fa4-49a5-5e8b-a978-f87d5c9d9dcd', '6db5aed5-815d-508c-a3bc-17c7f458f118', '9f42a5e4-a705-5b80-a81d-ca6773d9f0cd', 14, 14, 'ሁለት ቋዶችንም ከጥሩ ወርቅ እንደ ተጐነጐነ ገመድ አድርገህ ሥራ፤ የተጐነጐኑትንም ቋዶች በፈርጦቹ ላይ አንጠልጥል።'),
  ('c32e9727-799c-5193-a20a-ca39a931e5e2', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 1, 15, '“ብልህ ሠራተኛም እንደሚሠራ የፍርዱን ልብሰ እንግድዓ ሥራው፤ እንደ ልብሰ መትከፍም አሠራር ሥራው፤ ከወርቅና ከሰማያዊ፥ ከሐምራዊም፥ ከቀይም ግምጃ፥ ከጥሩ በፍታም ሥራው።'),
  ('e791c0ec-8ef9-5869-a66f-460f9e0b760b', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 2, 16, 'ርዝመቱ ስንዝር ስፋቱም ስንዝር፥ ሆኖ አራት ማዕዘን ድርብ ይሁን።'),
  ('b8a813e6-f0b9-5a01-a103-09450ee82684', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 3, 17, 'በአራት ተራ የሆነ የዕንቍ ፈርጥ አድርግበት፤ የድንጋዮቹም ተራ ሰርድዮን፥ ጳዝዮን፥ መረግድ ነው፤ ይህም መጀመሪያው ተራ ነው፤'),
  ('0147072e-38ae-5d3f-ab8e-e6fb03962c9a', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 4, 18, 'ሁለተኛውም ተራ በሉር፥ ሰንፔር፥ ኢያሰጲድ፤'),
  ('126fdc53-8ffd-515f-ab23-41c4a005c65e', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 5, 19, 'ሦስተኛውም ተራ ለግርዮን፥ አካጥስ፥ አሜቴስጢኖስ፤'),
  ('277e5388-f830-56e4-a9bf-0a9999fda055', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 6, 20, 'አራተኛውም ተራ ወርቃማ ድንጋይ፥ ቢረሌ፥ ሶም በየተራቸው በወርቅ የተለበጡና የታሠሩ ይሆናሉ።'),
  ('de00c3b7-406a-5187-a340-f1c08be5ccad', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 7, 21, 'የዕንቍም ድንጋዮች እንደ እስራኤል ልጆች ስሞች ዐሥራ ሁለት ይሆናሉ፤ በየስማቸውም ማኅተም አቀራረጽ ይቀረጹ፤ ስለ ዐሥራ ሁለቱ ነገዶችም ይሁኑ።'),
  ('4a11e086-81c2-5936-a70e-37437229dd89', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 8, 22, 'ለልብሰ እንግድዓውም የተጐነጐኑትን ቋዶች እንደ ገመድ አድርገህ ከጥሩ ወርቅ ሥራቸው።'),
  ('16ee5554-a7db-510d-ae3b-9c2ca72c2e7f', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 9, 23, 'ለልብሰ እንግድዓውም ሁለት የወርቅ ቀለበቶች ሥራ፤ ሁለቱንም ቀለበቶች በልብሰ እንግድዓው በሁለቱ ወገን አድርጋቸው።'),
  ('4b8d307c-3aa6-56d6-a1dd-abe8217a1070', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 10, 24, 'የተጐነጐኑትንም ሁለቱን የወርቅ ቋዶች በልብሰ እንግድዓው በሁለት ወገኖች ወዳሉት ወደ ሁለት ቀለበቶች ታገባቸዋለህ።'),
  ('b7144a60-47e8-5994-a6de-9bf6d1f067a7', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 11, 25, 'የሁለቱንም ቋዶች ጫፎች በሁለቱ ፈርጦች ውስጥ አግብተህ በልብሰ መትከፉ ጫንቃዎች ላይ በስተፊት በመጋጠሚያቸው ታደርጋቸዋለህ።'),
  ('52fdfd27-80cf-5cad-a4f9-7f370342624f', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 12, 26, 'ሁለት የወርቅ ቀለበቶችንም ሥራ፤ እነርሱንም ልብሰ መትከፉ በውስጥ በሚያልፍበት በከንፈሩ በኩል በሁለቱ የልብሰ እንግድዓ ጫፎች ላይ ታኖራቸዋለህ።'),
  ('ad08dd4c-46bd-5abf-a26f-c803bf249cde', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 13, 27, 'ደግሞም ሁለት የወርቅ ቀለበቶች ሥራ፤ በልብሰ መትከፉ ፊት ከጫንቃዎች በታች በብልሃት ከተጠለፈ ከልብሰ መትከፉ ቋድ በላይ በመጋጠሚያው አጠገብ ታደርጋቸዋለህ።'),
  ('e2666855-8223-5897-adbf-8c410ef00892', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 14, 28, 'ልብሰ እንግድዓውም በብልሃት ከተጠለፈ ከልብሰ መትክፉ ቋድ በላይ እንዲሆን፥ ከልብሰ መትከፉም እንዳይለይ፥ ልብሰ እንግድዓውን ከቀለበቶቹ ወደ ልብሰ መትከፉ ቀለበቶች በሰማያዊ ፈትል ያያይዙታል።'),
  ('22d4392c-a4f8-56bd-a054-5ae925c5c4da', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 15, 29, 'አሮንም ወደ መቅደስ በገባ ጊዜ በእግዚአብሔር ፊት ለዘለዓለም መታሰቢያ የእስራኤልን ልጆች ስሞች በፍርዱ ልብሰ እንግድዓ ውስጥ በልቡ ላይ ይሸከም።'),
  ('6806d87f-a0cc-5626-a36e-6a7a0fe6bbf0', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'fd81aea7-c18b-5ba2-adba-6d373bb11171', 16, 30, 'በፍርዱ ልብሰ እንግድዓም ውስጥ ኡሪምንና ቱሚምን ታደርጋለህ፤ በእግዚአብሔርም ፊት ወደ ቤተ መቅደስ በገባ ጊዜ በአሮን ልብ ላይ ይሆናሉ፤ አሮንም በእግዚአብሔር ፊት ሁልጊዜ የእስራኤልን ልጆች ፍርድ በልቡ ላይ ይሸከማል።'),
  ('3cadc0a4-6249-5c7b-a4d1-8343b77ba904', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 1, 31, '“ቀሚሱንም ሁሉ ሰማያዊ አድርገው።'),
  ('825265c9-1ced-5188-a00c-75b1a6438284', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 2, 32, 'ከላይም በመካከል አንገትጌ ይሁንበት፤ እንዳይቀደድም በግብረ መርፌ የተሠራ ጥልፍ በአንገትጌው ዙሪያ ይሁንበት።'),
  ('5ff18880-71b7-5801-af37-dd3530e92e6e', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 3, 33, 'በታችኛውም ዘርፍ ዙሪያ ከሰማያዊ፥ ከሐምራዊ፥ ከቀይም ግምጃ ሮማኖችን አድርግ፤ በእነዚያም መካከል በዙሪያው በተመሳሳይ ቅርጽ የወርቅ ሮማኖች ሻኵራዎችን አድርግ፤'),
  ('32877550-d3ed-5244-af86-6c0513ef3b68', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 4, 34, 'የወርቅ ሻኩራ ሮማንም፥ ሌላም የወርቅ ሻኩራ ሮማንም በቀሚሱ ዘርፍ ዙሪያውን ይሆናሉ።'),
  ('c6695b11-8e6b-590f-a5bd-1c6acdb27c12', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 5, 35, 'በማገልገል ጊዜም በአሮን ላይ ይሆናል፤ እርሱም እንዳይሞት ወደ መቅደሱ በእግዚአብሔር ፊት ሲገባና ሲወጣ ድምፁ ይሰማል።'),
  ('6e3c9e59-e57a-5aa7-a13c-26d9313139d9', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 6, 36, '“ከጥሩ ወርቅም የወርቅ ቅጠል ሥራ፤ በእርሱም እንደ ማኅተም ቅርጽ አድርገህ፦ ቅድስና ለእግዚአብሔር የሚል ትቀርጽበታለህ።'),
  ('0c0ed591-eca2-59cd-ad4c-febc3ac480eb', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 7, 37, 'በሰማያዊም ፈትል በመጠምጠሚያው ላይ በስተፊቱ ታንጠለጥለዋለህ ።'),
  ('f7a817bc-f45b-5420-a481-08cec7df7766', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 8, 38, 'በአሮንም ግንባር ላይ ይሆናል፤ አሮንም የእስራኤል ልጆች በሚያቀርቡትና በሚቀድሱት በቅዱሱ ስጦታቸው ሁሉ ላይ የሠሩትን ኀጢአት ይሸከም፤ በእግዚአብሔርም ፊት ተቀባይነት ያለው እንዲሆንላቸው ሁልጊዜ በግንባሩ ላይ ይሁን።'),
  ('4c55fcf2-bfb1-5a2d-a9e7-eca1584c01fe', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 9, 39, 'ቀሚሱንም ከጥሩ በፍታ ዝንጕርጕር አድርገህ፥ አክሊልን ከበፍታ ትሠራለህ፤ በጥልፍ አሠራርም መታጠቂያ ትሠራለህ።'),
  ('9b493eba-7c32-5e9b-a56f-b96ced12603f', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 10, 40, 'ለአሮንም ልጆች የበፍታ ቀሚሶችን፥ መታጠቂያዎችንም፥ ቆቦችንም ለክብርና ለመለያ ታደርግላቸዋለህ።'),
  ('fc690332-4922-5178-afdd-670889a8ecf3', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 11, 41, 'ይህንም ሁሉ ወንድምህን አሮንን፥ ከእርሱም ጋር ልጆቹን ታለብሳቸዋለህ፤ በክህነት እንዲያገለግሉኝ ትቀባቸዋለህ፤ እጆቻቸውንም ታነጻለህ፤ ትቀድሳቸውማለህ።'),
  ('930be1ba-5ce1-59f6-a503-e9340a9c202a', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 12, 42, 'ኀፍረተ ሥጋቸውንም ይከድኑበት ዘንድ የተልባ እግር ሱሪ ታደርግላቸዋለህ፤ ከወገባቸውም እስከ ጭናቸው ይደርሳል፤'),
  ('81f43e5b-ae24-520c-a8de-85fcfb980e6c', '6db5aed5-815d-508c-a3bc-17c7f458f118', 'ec9a9739-98b4-5be7-a23b-da89c3f26d0d', 13, 43, 'እንዲሁም ኀጢአት እንዳይሆንባቸው፥ እንዳይሞቱም፥ ወደ ምስክሩ ድንኳን ሲገቡ፥ በመቅደሱም ያገለግሉ ዘንድ ወደ መሠዊያው ሲቀርቡ በአሮንና በልጆቹ ላይ ይሆናል፤ ለእርሱ፥ ከእርሱም በኋላ ለዘሩ ለዘለዓለም ሥርዐት ይሆናል።'),
  ('ec730bc0-b3f0-5cc5-a61c-f3e386cdfea8', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 1, 1, '“እኔንም በክህነት እንዲያገለግሉኝ ትቀድሳቸው ዘንድ የምታደርግላቸው ነገር ይህ ነው፤ ነውር የሌለባቸውን አንድ ወይፈንና ሁለት አውራ በጎች ትወስዳለህ።'),
  ('3f90fd85-bcf6-5b89-a17b-88a03e739481', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 2, 2, 'ቂጣ እንጀራ፥ በዘይትም የተለወሰ የቂጣ እንጎቻ፥ በዘይትም የተቀባ ስስ ቂጣ ከመልካም ስንዴ ታደርጋለህ።'),
  ('8d4acc3a-2460-5fc9-a9c8-5a50a8587de0', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 3, 3, 'በአንድ መሶብም ታደርጋቸዋለህ፤ ከወይፈኑና ከሁለቱ አውራ በጎች ጋር በመሶብ ታቀርባቸዋለህ።'),
  ('fd649e4b-d897-5b04-ab70-6aabd34c8da3', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 4, 4, 'አሮንንና ልጆቹን ወደ ምስክሩ ድንኳን ደጃፍ ታቀርባቸዋለህ፤ በውኃም ታጥባቸዋለህ።'),
  ('f831c176-7d2a-5aab-abda-1c01b843c212', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 5, 5, 'ልብሶችን ወስደህ ለወንድምህ ለአሮን የነጭ ሐር እጀ ጠባብ ቀሚስ፥ ልብሰ መትከፍና ልብሰ እንግድዓ ታለብሰዋለህ፤ ለእርሱም ልብሰ እንግድዓውን ከልብሰ መትከፉ ጋር አያይዝለት።'),
  ('fa9415e6-077e-58a8-a5db-41efb7e81c38', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 6, 6, 'አክሊልንም በራሱ ላይ ታደርጋለህ፤ የወርቁንም ቀጸላ በአክሊሉ ላይ ታኖራለህ።'),
  ('eeb2909f-54db-5efd-a821-6965aa775a95', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 7, 7, 'የቅብዐትንም ዘይት ወስደህ በራሱ ላይ ታፈስሰዋለህ፤ ትቀባውማለህ።'),
  ('a79b9d52-feda-5408-aff4-3d1b055c56f3', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 8, 8, 'ልጆቹንም ታቀርባቸዋለህ፤ ቀሚሶችንም ታለብሳቸዋለህ፤'),
  ('caace05f-44ca-5ef7-a73b-a44d9efa4b12', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 9, 9, 'በመታጠቂያም ታስታጥቃቸዋለህ፤ ቆብንም ታደርግላቸዋለህ፤ ለዘለዓለም ሥርዐትም ክህነት ይሆንላቸዋል፤ እንዲሁም የአሮንንና የልጆቹን እጆች ትቀባቸዋለህ።'),
  ('04dba48f-75db-5cc4-a921-f4e93363178d', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 10, 10, '“ወይፈኑንም ወደ ምስክሩ ድንኳን በር ታቀርበዋለህ፤ አሮንና ልጆቹም በምስክሩ ድንኳን በር በእግዚአብሔር ፊት እጆቻቸውን በወይፈኑ ራስ ላይ ይጭናሉ።'),
  ('4c6f51e7-3d88-5863-a834-7c35973c1f2e', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 11, 11, 'ወይፈኑንም በምስክሩ ድንኳን በር አጠገብ በእግዚአብሔር ፊት ታርደዋለህ።'),
  ('3b5e0a9a-ec8a-5400-a33e-f20dbaff00a3', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 12, 12, 'ከወይፈኑም ደም ወስደህ በመሠዊያው ቀንዶች ላይ በጣትህ ትረጨዋለህ፤ የተረፈውንም ደም ሁሉ ከመሠዊያው በታች ታፈስሰዋለህ።'),
  ('04f56f73-65c8-5859-abfa-a8512b53fc8d', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 13, 13, 'የሆድ ዕቃውንም የሚሸፍነውን ስብ ሁሉ፥ በጉበቱም ላይ ያለውን መረብ፥ ሁለቱንም ኵላሊቶች፥ በላያቸውም ያለውን ስብ ወስደህ በመሠዊያው ላይ ታስቀምጣለህ።'),
  ('0a84a3a7-e9b8-56bf-ad5b-fdd14a272409', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 14, 14, 'የወይፈኑን ሥጋ ግን፥ ቍርበቱንም፥ ፈርሱንም ከሰፈር ውጭ በእሳት ታቃጥለዋለህ፤ የኀጢአት መሥዋዕት ነውና።'),
  ('b1046dcb-2bdd-5f75-a09c-4efe2f772e0e', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 15, 15, '“አንደኛውንም አውራ በግ ትወስደዋለህ፤ አሮንና ልጆቹም በአውራው በግ ራስ ላይ እጆቻቸውን ይጭናሉ።'),
  ('7145d024-d053-5368-a826-ff0a778d7a09', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 16, 16, 'አውራውንም በግ ታርደዋለህ፤ ደሙንም ወስደህ በመሠዊያው ላይ በዙሪያው ትረጨዋለህ።'),
  ('dc2498aa-c151-5315-ad65-2b356e16da94', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 17, 17, 'አውራውንም በግ በየብልቱ ትቈርጠዋለህ፤ የሆድ ዕቃውንና እግሮቹንም በውኃ ታጥባለህ፤ ከብልቱና ከራሱም ጋር ታኖረዋለህ።'),
  ('017a6d94-a703-583c-acb9-2a30fa2c1501', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 18, 18, 'አውራንም በግ በሞላው በመሠዊያው ላይ ታቃጥላለህ፤ ስለ ጣፋጭ ሽታ ለእግዚአብሔር የሚቃጠል መሥዋዕት ነው፤ ለእግዚአብሔር የቀረበ የእሳት ቍርባን ነው።'),
  ('4cdb6464-9453-5e41-af98-e4c69eb39ae2', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 19, 19, '“ሁለተኛውንም አውራ በግ ትወስደዋለህ፤ አሮንና ልጆቹም እጆቻቸውን በአውራው በግ ራስ ላይ ይጭናሉ።'),
  ('f2bb33ed-3674-5b61-ae64-5f79e90cace8', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 20, 20, 'አውራውንም በግ ታርደዋለህ፤ ደሙንም ትወስዳለህ፤ የአሮንንም የቀኝ ጆሮ ጫፍ፥ የቀኝ እጁንና የቀኝ እግሩን አውራ ጣት ጫፍ፥ የልጆቹንም የቀኝ ጆሮአቸውን ጫፍ፥ የቀኝ እጃቸውንና የቀኝ እግራቸውን አውራ ጣት ታስነካለህ፤ ደሙንም በመሠዊያው ላይ በዙሪያው ትረጨዋለህ።'),
  ('e40e9454-ddf4-56cb-afb7-6c3cd46ece98', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 21, 21, 'በመሠዊያውም ላይ ካለው ደም ከቅብዐት ዘይትም ወስደህ በአሮንና በልብሱ ላይ፥ ከእርሱም ጋር ባሉት በልጆቹና በልብሶቻቸው ላይ ትረጨዋለህ፤ እርሱም ልብሶቹም፥ ከእርሱም ጋር ልጆቹ፥ ልብሶቻቸውም ይቀደሳሉ።'),
  ('9d525054-4313-5cc1-a513-52c30c41b404', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 22, 22, 'የበጉንም ስብ፥ የሆድ ዕቃውን የሚሸፍነውን ስብ፥ በጉበቱም ላይ ያለውን መረብ፥ ሁለቱንም ኵላሊቶች፥ በላያቸውም ላይ ያለውን ስብ፥ የቀኙንም ወርች ትወስዳለህ፤ የሚቀደሱበት ነውና።'),
  ('f1f5df04-da53-5ad0-abec-2288046385d1', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 23, 23, 'በእግዚአብሔር ፊት በመሶብ ካለው አንድ የዘይት እንጀራና አንድ የቂጣ እንጐቻ ትወስዳለህ፤'),
  ('b3496a42-68fa-5a46-a8b2-d9d4dcf79bdf', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 24, 24, 'ሁሉንም በአሮን እጆችና በልጆቹ እጆች ታኖረዋለህ፤ ለሚለይ ቍርባን በእግዚአብሔር ፊት ትለየዋለህ።'),
  ('a5fc0b30-ea26-5c27-ad5e-04efb58776a9', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 25, 25, 'ከእጃቸውም ትቀበለዋለህ፤ በመሥዊያውም ላይ ከሚቃጠል መሥዋዕት ጋር በእግዚአብሔር ፊት በጎ መዓዛ እንዲሆን ታቃጥለዋለህ፤ እርሱ ለእግዚአብሔር መሥዋዕት ነው።'),
  ('dd9d0d52-011f-5111-a9d5-6c04f9940d46', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 26, 26, '“ለአሮንም ክህነት የታረደውን የአውራውን በግ ፍርምባ ወስደህ ለሚለይ ቍርባን በእግዚአብሔር ፊት ትለየዋለህ፤ እርሱም የአንተ ወግ ይሆናል።'),
  ('64a2cb82-ba30-530a-a486-2768cae9b7cb', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 27, 27, 'ከሚካኑበትም አውራ በግ የተወሰደ ለአሮንና ለልጆቹ ወግ የሚሆን ለመሥዋዕት የተለየውን ፍርምባና የተነሣውን ወርች ትቀድሳለህ።'),
  ('fb633692-e803-59fa-a5f7-d318ce073a79', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 28, 28, 'ይህም የተለየ ቍርባን ነውና ከእስራኤልልጆች ዘንድ ለዘለዓለም የአሮንና የልጆቹ ሕግ ይሁን፤ የእስራኤል ልጆች የሚያቀርቡት የደኅንነት መሥዋዕታቸው የተለየ ቍርባን ይሆናል፤ ለእግዚአብሔር የተለየ ቍርባን ይሆናል።'),
  ('a4d3a140-5ae8-57d2-a262-991c9b456741', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 29, 29, '“የአሮንም የቅድስናው ልብስ ይቀቡበትና እጆቻቸው ይቀደሱበት ዘንድ ከእርሱ በኋላ ለልጆቹ ይሁን።'),
  ('4fc28977-c655-53c1-ad1d-c93002317fea', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 30, 30, 'ከልጆቹም በእርሱ ፋንታ ካህን የሚሆነው በመቅደስ ለማገልገል ወደ ምስክሩ ድንኳን ሲገባ ሰባት ቀን ይልበሰው።'),
  ('41ca3e24-fe02-5748-a9b5-e9302235eaf4', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 31, 31, '“የቅድስናውንም በግ ወስደህ ሥጋውን በተቀደሰ ስፍራ ትቀቅለዋለህ።'),
  ('6011d889-92ed-5874-aca5-62a9117e0008', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 32, 32, 'አሮንና ልጆቹም የአውራውን በግ ሥጋ፥ በመሶብም ያለውን እንጀራ በምስክሩ ድንኳን በር ይበሉታል።'),
  ('91f40f1f-b84e-5e1a-a6b4-17b2b31447cf', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 33, 33, 'ለመክበራቸው እጆቻቸውን ይቀድሱ ዘንድ በተቀደሱበት በዚያ ቦታ ይብሉት፤ የባዕድ ልጅ ግን አይብላው፤ የተቀደሰ ነውና።'),
  ('d9c766b5-d2ce-5c05-ad0a-76d6ee4a3925', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 34, 34, 'ከቅድስናው መሥዋዕት ሥጋ ወይም እንጀራ እስከ ነገ ቢተርፍ፥ የቀረውን በእሳት ታቃጥለዋለህ፤ የተቀደሰ ነውና አይበላም።'),
  ('171c6837-1584-5f9f-a160-35b31775c70e', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 35, 35, '“እንዳዘዝሁህም ሁሉ ለአሮንና ለልጆቹ እንዲህ አድርግ፤ ሰባት ቀን እጆቻቸውን ትቀድሳለህ።'),
  ('7e4ccd3e-dffe-5d09-ac23-00f0860a48fa', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 36, 36, 'ዕለት ዕለትም ስለ ማስተስረይ ለኀጢአት መሥዋዕት ወይፈኑን ታቀርባለህ፤ ማስተስረያም ባደረግህ ጊዜ መሠዊያውን ታነጻዋለህ፤ ቅዱስም ይሆን ዘንድ ትቀባዋለህ።'),
  ('89bcafa9-08d1-5124-a16b-41efeb7f7ef5', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '7464b4d6-cdc9-5beb-aa2c-f5d95946e5c2', 37, 37, 'ሰባት ቀን መሠዊያውን ታነጻዋለህ፤ ትቀድሰውማለህ፤ መሠዊያውም ቅዱሰ ቅዱሳን ይሆናል፤ መሠዊያውንም የሚነካ ሁሉ ቅዱስ ይሆናል።'),
  ('2e03ac57-96c3-5e93-aa58-86c24dc2e9a3', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '551e6970-b736-5463-ac5f-b7766583e990', 1, 38, '“በመሠዊያውም ላይ የምታቀርበው ይህ ነው፤ በቀን በቀን ዘወትር በመሠዊያው ላይ ሁለት ንጹሓን የዓመት ጠቦቶች ታቀርባለህ።'),
  ('1f73c54f-e2b9-5831-aa2a-9f8513d85350', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '551e6970-b736-5463-ac5f-b7766583e990', 2, 39, 'አንዱን ጠቦት በነግህ፥ ሁለተኛውንም ጠቦት በሠርክ መሥዋዕት አድርገህ ታቀርበዋለህ።'),
  ('fc7f1f17-7cc1-5b7f-ad1d-0ea20d43b5be', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '551e6970-b736-5463-ac5f-b7766583e990', 3, 40, 'ከአንዱ ጠቦትም ጋር የኢን መስፈሪያ አራተኛ እጅ በሆነ ተወቅጦ በተጠለለ ዘይት የተለወሰ የኢፍ መስፈሪያ ዐሥረኛ እጅ መልካም ዱቄት፥ ደግሞ ለመጠጥ ቍርባን የኢን መስፈሪያ አራተኛ እጅ የወይን ጠጅ ታቀርባለህ።'),
  ('d143cbc1-abab-5ea6-a33e-bbea2a59572b', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '551e6970-b736-5463-ac5f-b7766583e990', 4, 41, 'ሁለተኛውንም ጠቦት በሠርክ ታቀርበዋለህ፤ እንደ ነግሁም የእህልና የመጠጥ ቍርባን ታደርግበታለህ፤ ለእግዚአብሔር በጎ መዓዛ እንዲሆን የእሳት ቍርባን ይሆናል።'),
  ('b3719fc0-63fc-5cd7-a94e-71525bb1af6b', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '551e6970-b736-5463-ac5f-b7766583e990', 5, 42, 'በዚያ እናገርህ ዘንድ ለአንተ በምገለጥበት በምስክሩ ድንኳን ደጃፍ በእግዚአብሔር ፊት ለልጅ ልጃችሁ የዘወትር መሥዋዕት ይሆናል።'),
  ('63bde364-0c0d-5222-a73e-b0a892941aeb', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '551e6970-b736-5463-ac5f-b7766583e990', 6, 43, 'በዚያም የእስራኤልን ልጆች አዝዛለሁ፤ በክብሬም እቀደሳለሁ።'),
  ('dd0bbfb7-1e21-5a4b-a8b1-538c6e2eeb0b', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '551e6970-b736-5463-ac5f-b7766583e990', 7, 44, 'የምስክሩንም ድንኳን መሠዊያውንም እቀድሳለሁ፤ በክህነትም ያገለግሉኝ ዘንድ አሮንንና ልጆቹን እቀድሳለሁ።'),
  ('a00467da-fcb2-56e9-adb5-c6601d0ed3b6', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '551e6970-b736-5463-ac5f-b7766583e990', 8, 45, 'በእስራኤልም ልጆች መካከል እኖራለሁ፤ አምላካቸውም እሆናቸዋለሁ።'),
  ('18ff7e34-3614-5e65-a12d-db1bd05afbd0', '217fb71b-8e14-55ca-aa2a-32b15f56b91a', '551e6970-b736-5463-ac5f-b7766583e990', 9, 46, 'በእነርሱ እጠራ ዘንድ፥ አምላክም እሆናቸው ዘንድ ከግብፅ ምድር ያወጣኋቸው አምላካቸው እግዚአብሔር እኔ እንደ ሆንሁ ያውቃሉ።'),
  ('be2e1042-d335-5b45-a611-49ce8c443921', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', 'bb40105a-21bb-5a46-a176-8da798acd0e9', 1, 1, '“የዕጣን መሠዊያውን ከማይነቅዝ ዕንጨት ሥራ።'),
  ('df25a01e-3467-5ec4-a2f4-4720d20713fa', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', 'bb40105a-21bb-5a46-a176-8da798acd0e9', 2, 2, 'ርዝመቱ አንድ ክንድ፥ ስፋቱም አንድ ክንድ፥ አራት ማዕዘን ይሁን፤ ቁመቱም ሁለት ክንድ ይሆናል፤ ቀንዶቹም ከእርሱ ይሠሩ።'),
  ('e111cdb4-9187-51fd-a988-c9d8c9da91fc', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', 'bb40105a-21bb-5a46-a176-8da798acd0e9', 3, 3, 'ወለሉንና የግድግዳውንም ዙሪያ፥ ቀንዶቹንም በጥሩ ወርቅ ትለብጠዋለህ፤ በዙሪያውም የጥሩ ወርቅ ክፈፍ ታደርግለታለህ።'),
  ('fe012e2d-3f2f-55da-a0cc-d575ce829598', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', 'bb40105a-21bb-5a46-a176-8da798acd0e9', 4, 4, 'ከክፈፉም በታች ሁለት የወርቅ ቀለበቶች አድርግለት። በዚህና በዚያ በሁለቱ ጐን ታደርጋቸዋለህ፤ እርሱን ያነሡባቸው ዘንድ የመሎጊያዎቹ መግቢያ ይሁኑ።'),
  ('afebf308-8416-5942-a780-9af8c4c254f6', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', 'bb40105a-21bb-5a46-a176-8da798acd0e9', 5, 5, 'መሎጊያዎቹንም ከማይነቅዝ ዕንጨት አድርግ፤ በወርቅም ለብጣቸው።'),
  ('89cf6bc1-24b2-5ce7-af03-8b935b33e721', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', 'bb40105a-21bb-5a46-a176-8da798acd0e9', 6, 6, 'ለአንተ በምገለጥበት በምስክሩ ታቦት ላይ ባለው መጋረጃ ፊት ታኖረዋለህ።'),
  ('6c2e89e9-4c8a-51a5-aab2-3be3695356bf', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', 'bb40105a-21bb-5a46-a176-8da798acd0e9', 7, 7, 'አሮንም በጎ መዓዛ ያለው የደቀቀ ዕጣን በውስጡ በየማለዳው ይጠንበት፤ መብራቶቹን ሲያዘጋጅ ይጠነው።'),
  ('5995d1b5-c7fb-5eb3-ab38-348e9e4d8b36', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', 'bb40105a-21bb-5a46-a176-8da798acd0e9', 8, 8, 'ይህም በእግዚአብሔር ፊት ለልጅ ልጃችሁ የዘወትር ዕጣን ይሆን ዘንድ አሮን በማታ ጊዜ መብራቶቹን ሲያበራ ያጥነዋል።'),
  ('f3358fbb-a7e4-5cba-ace0-fd9b11211102', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', 'bb40105a-21bb-5a46-a176-8da798acd0e9', 9, 9, 'ሌላም ዕጣን፥ የሚቃጠለውንም መሥዋዕት፥ የእህሉንም ቍርባን አታቀርብበትም፤ የመጠጥም ቍርባን አታፈስስበትም።'),
  ('f9321bdc-f15d-5338-a847-32fe410945d8', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', 'bb40105a-21bb-5a46-a176-8da798acd0e9', 10, 10, 'አሮንም በዓመት አንድ ጊዜ በቀንዶቹ ላይ ማስተስረያ ያደርጋል፤ በዓመት አንድ ጊዜ ኀጢአትን ከሚያነጻው ደም ይወስዳል፤ የልጅ ልጆቻቸውንም እንዲያነጻ ያደርጋል፤ ይህም ለእግዚአብሔር ቅዱሰ ቅዱሳን ነው።”'),
  ('f586c842-007e-576a-a260-b5bd66307ea7', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '82476fa4-8027-58ac-a206-18eab56c7fb4', 1, 11, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('68adf3c0-0a5e-59eb-aae4-4b064bf95a9d', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '82476fa4-8027-58ac-a206-18eab56c7fb4', 2, 12, '“አንተ የእስራኤልን ልጆች ቍጥር የወሰድህ እንደ ሆነ በቈጠርሃቸው ጊዜ መቅሠፍት እንዳይሆንባቸው፥ በቈጠርሃቸው ጊዜ ከእነርሱ ሰው ሁሉ እንደ ቍጥራቸው መጠን የነፍሱን ቤዛ ለእግዚአብሔር ይስጥ።'),
  ('f0709fb3-12b0-5258-af0b-062b910c57c6', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '82476fa4-8027-58ac-a206-18eab56c7fb4', 3, 13, 'ይቈጠሩ ዘንድ የሚያልፉት ሁሉ የሚሰጡት ይህ ነው፤ እንደ መቅደሱ ሰቅል ሚዛን የሰቅል ግማሽ ይሰጣል። ሰቅሉም ሃያ አቦሊ ነው፤ የሰቅሉም ግማሽ ለእግዚአብሔር ቍርባን ነው።'),
  ('6d704d04-b46e-5435-ac81-a3dec0c98a9c', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '82476fa4-8027-58ac-a206-18eab56c7fb4', 4, 14, 'ይቈጠር ዘንድ የሚያልፈው ሁሉ፥ ከሃያ ዓመት ጀምሮ ከዚያም ከፍ ያለ፥ የእግዚአብሔርን ስጦታ ይሰጣል።'),
  ('f847e68e-668b-5280-a14f-2d66214b4fcc', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '82476fa4-8027-58ac-a206-18eab56c7fb4', 5, 15, 'ለነፍሳችሁ ቤዛ የእግዚአብሔርን ስጦታ ስትሰጡ ባለ ጠጋው ከሰቅል ግማሽ አይጨምር፤ ድሃውም አያጕድል።'),
  ('d5b70525-9ee8-5e6f-adac-140da0224af2', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '82476fa4-8027-58ac-a206-18eab56c7fb4', 6, 16, 'የማስተስረያውንም ገንዘብ ከእስራኤል ልጆች ወስደህ ለምስክሩ ድንኳን ማገልገያ ትሰጠዋለህ፤ በእግዚአብሔርም ፊት ለነፍሳችሁ ቤዛ እንዲሆን ለእስራኤል ልጆች መታሰቢያ ይሁን።”'),
  ('d48bdf8e-30dc-5ea1-aff2-e713f401e6c2', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '67c2daee-b6c0-55a1-a1ca-762b8a6cc221', 1, 17, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('b7d7d1ed-7401-5a6d-a2f9-9df68b302134', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '67c2daee-b6c0-55a1-a1ca-762b8a6cc221', 2, 18, '“የመታጠቢያ ሰን ከናስ፥ መቀመጫውንም ከናስ ሥራ፤ በምስክሩ ድንኳንና በመሠዊያው መካከል ታኖረዋለህ፤ ውኃም ትጨምርበታለህ።'),
  ('8bf4f120-410d-5b05-af5d-b17696210a37', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '67c2daee-b6c0-55a1-a1ca-762b8a6cc221', 3, 19, 'አሮንና ልጆቹም እጆቻቸውንና እግሮቻቸውን ይታጠቡበታል።'),
  ('83718aa7-4312-5194-af62-734d840c3002', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '67c2daee-b6c0-55a1-a1ca-762b8a6cc221', 4, 20, 'ወደ ምስክሩ ድንኳን በገቡ ጊዜ፥ ለእግዚአብሔርም የእሳት መሥዋዕት ያቃጥሉ ዘንድ ወደ መሠዊያው ሊያገለግሉ በቀረቡ ጊዜ እንዳይሞቱ ይታጠቡበታል።'),
  ('81d2886e-24e5-539a-a310-dea5627fd40b', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '67c2daee-b6c0-55a1-a1ca-762b8a6cc221', 5, 21, 'ወደ ምስክሩም ድንኳን በገቡ ጊዜ እንዳይሞቱ እጆቻቸውንና እግሮቻቸውን ይታጠቡ፤ ይህም ለእነርሱ ከእነርሱም በኋላ ለልጆቻቸው የዘለዓለም ሥርዐት ይሆንላቸዋል።”'),
  ('6e0137b1-de9e-528b-afd4-d769c62d32cc', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 1, 22, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('288bca4d-409e-5b15-a668-44747f2b4f3d', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 2, 23, '“አንተም ክቡሩን ሽቱ ውሰድ፤ የተመረጠ የከርቤ አበባ አምስት መቶ ሰቅል፥ የዚህም ግማሽ ጣፋጭ ቀረፋ ሁለት መቶ አምሳ ሰቅል፤ ያማረ የጠጅ ሣርም እንዲሁ ሁለት መቶ አምሳ ሰቅል፤'),
  ('83ee8eed-6cbd-559d-a569-49d02cf81ab0', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 3, 24, 'ብርጉድም አምስት መቶ ሰቅል እንደ መቅደሱ ሰቅል ሚዛን፥ የወይራ ዘይትም አንድ የኢን መስፈሪያ ትወስዳለህ።'),
  ('014d7386-247e-56d0-a91d-21f1c5f7a853', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 4, 25, 'በቀማሚም ብልሃት እንደ ተሠራ ቅመም፥ የተቀደሰ የቅብዐት ዘይት ታደርገዋለህ፤ የተቀደሰ የቅብዐት ዘይት ይሆናል።'),
  ('f5ff6ece-417f-5164-a293-cd04adda7e85', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 5, 26, 'የምስክሩንም ድንኳን፥ የምስክሩንም ታቦት፥'),
  ('ea62beb3-78e7-588d-a43b-2cc179757e76', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 6, 27, 'ገበታውንም፥ ዕቃውንም ሁሉ፥ መቅረዙንም፥ ዕቃውንም፥ የዕጣን መሠዊያውንም፥'),
  ('cf02cbf0-e88d-513e-a398-37470f43da30', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 7, 28, 'ለሚቃጠል መሥዋዕት የሚሆነውን መሠዊያና ዕቃውንም ሁሉ፥ የመታጠቢያውን ሰንና መቀመጫውንም ትቀባበታለህ።'),
  ('9da966a8-4246-5474-acb9-3e57a25439bb', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 8, 29, 'ሁሉንም ትቀድሳቸዋለህ፤ ቅዱሰ ቅዱሳንም ይሆናሉ፤ የሚነካቸውም ሁሉ ቅዱስ ይሆናል።'),
  ('9d253955-e82d-5075-a163-85a4fac5e3f5', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 9, 30, 'በክህነትም ያገለግሉኝ ዘንድ አሮንንና ልጆቹን ቅባቸው፤ ቀድሳቸውም።'),
  ('3654e0f4-a8fb-5711-a6fe-aa27677772b5', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 10, 31, 'አንተም ለእስራኤል ልጆች እንዲህ ብለህ ተናገር፤ ይህ ለልጅ ልጃችሁ የተቀደሰ የቅብዐት ዘይት ይሁን።'),
  ('f6ca84a1-620e-5e14-adce-5e0fa5aa083c', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 11, 32, 'በሌላ ሰው ሥጋ ላይ አይፍሰስ፤ እንደ እርሱም የተሠራ ሌላ ቅብዐት አታድርጉ፤ ቅዱስ ነው፤ ለእናንተም ቅዱስ ይሁን።'),
  ('276625e8-1e47-5f19-a64a-bb2c946facd8', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '09729d85-6bc5-57bc-a024-f2ee85ca4dca', 12, 33, 'እንደ እርሱ ያለውን የሚያደርግ ሰው፥ በሌላም ሰው ላይ የሚያፈስሰው ከሕዝቡ ተለይቶ ይጥፋ።”'),
  ('7e03240b-25c2-5ec0-a2e4-caeb176c29f7', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '6e8438a4-764d-55e4-a2ea-fb6ae619ac08', 1, 34, 'እግዚአብሔርም ሙሴን አለው፥ “ጣፋጭ ሽቱ ውሰድ፤ የሚንጠባጠብ ሙጫ፥ በዛጎል ውስጥ የሚገኝ ሽቱ፥ የሚሸትትም ሙጫ፥ ጥሩም ዕጣን ውሰድ፤ የሁሉም መጠን ትክክል ይሁን።'),
  ('62003be3-38e5-5452-a648-00f26ef8e254', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '6e8438a4-764d-55e4-a2ea-fb6ae619ac08', 2, 35, 'በቀማሚ ብልሃት እንደ ተሠራ፥ የተቀመመ ንጹሕና ቅዱስ ዕጣን አድርገው።'),
  ('75b91ff3-d0c7-5c16-ab46-8e02f433988e', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '6e8438a4-764d-55e4-a2ea-fb6ae619ac08', 3, 36, 'ከእርሱም ጥቂት ትወቅጣለህ፤ ታልመውማለህ፤ ከዚያም ለአንተ በምገለጥበት በምስክሩ ድንኳን ውስጥ በምስክሩ ፊት ታኖረዋለህ። እርሱም ቅዱሰ ቅዱሳን ይሁንላችሁ።'),
  ('f0ed7e2c-9606-5f5c-a3b4-04a80a3cde73', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '6e8438a4-764d-55e4-a2ea-fb6ae619ac08', 4, 37, 'በዚህም አሠራር የዚህን ዕጣን ዐይነት ለእናንተ አታድርጉ፤ በእናንተም ዘንድ ለእግዚአብሔር የተቀደሰ ይሁን።'),
  ('c3bf7db2-789c-51c5-a2e2-d770e8eb31a1', '4d1542d6-5235-52ca-a5e5-b4a4bf8dc7f5', '6e8438a4-764d-55e4-a2ea-fb6ae619ac08', 5, 38, 'ሊያሸትተውም እንደ እርሱ የሚያደርግ ሰው ከሕዝቡ ተለይቶ ይጥፋ።”'),
  ('341dc6d6-4364-555b-a845-d8174e8d7e17', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '9784e76a-80ff-5d34-a284-bed708813506', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('ff59611d-4c3c-5e4a-a7b5-cf0297cda759', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '9784e76a-80ff-5d34-a284-bed708813506', 2, 2, '“እይ! ከይሁዳ ነገድ የሚሆን የሆር የልጅ ልጅ የኡሪ ልጅ ባስልኤልን በስሙ ጠርቼዋለሁ።'),
  ('15f3033b-e83a-57bc-a77f-3cf0a15d2532', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '9784e76a-80ff-5d34-a284-bed708813506', 3, 3, 'በሥራ ሁሉ ያስተውል ዘንድ በጥበብም፥ በማስተዋልም፥ በዕውቀትም የእግዚአብሔርን መንፈስ ሞላሁበት፤'),
  ('0a98f4e8-7fce-5edc-adca-3e1c06ccd0f0', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '9784e76a-80ff-5d34-a284-bed708813506', 4, 4, 'የአናጺዎች አለቃ ይሆን ዘንድ ወርቅንና ብርን፥ ናስንም፥ ብጫና ሰማያዊ፥ እጥፍ ሆኖ የተፈተለ ነጭና ቀይ ሐርን ይሠራ ዘንድ፤'),
  ('6afc3008-5634-5a71-a58d-0c5277fbf684', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '9784e76a-80ff-5d34-a284-bed708813506', 5, 5, 'በሥራውም ሁሉ የሚደረገውን የድንጋይ ማለዘብን፥ ከዕንጨትም የሚጠረበውን ይሠራ ዘንድ።'),
  ('a313d23a-4538-5675-ac70-874bb623ec3b', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '9784e76a-80ff-5d34-a284-bed708813506', 6, 6, 'እኔም እነሆ፥ ከዳን ነገድ የሚሆን የአሂሳሚክን ልጅ ኤልያብን ሰጠሁ፤ ያዘዝሁህን ሁሉ ያደርጉ ዘንድ በልባቸው ጥበበኞች ለሆኑት ሁሉ ዕውቅትን ሰጠሁ።'),
  ('32ba5df3-446f-5700-aeab-1583322c4feb', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '9784e76a-80ff-5d34-a284-bed708813506', 7, 7, 'የምስክሩን ድንኳን፥ የቃል ኪዳኑንም ታቦት፥ በእርሱም ላይ ያለውን የስርየት መክደኛውን፥ የድንኳኑንም ዕቃ ሁሉ፤'),
  ('ec29f7df-3c3b-50cb-a122-fa0972562a38', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '9784e76a-80ff-5d34-a284-bed708813506', 8, 8, 'የዕጣን መሠዊያውን፥ ገበታውንም፥ ዕቃውንም፥ ከዕቃው ሁሉ የነጻውን መቅረዝ፥'),
  ('40945ea9-fba8-5ec2-aa50-8e6d485343c2', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '9784e76a-80ff-5d34-a284-bed708813506', 9, 9, 'ለሚቃጠል መሥዋዕት የሚሆነውን መሠዊያ፥ ዕቃውንም ሁሉ፥ የመታጠቢያውን ሰንና መቀመጫውንም፥'),
  ('ed41a04e-1d6a-558b-a37e-876f5666e439', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '9784e76a-80ff-5d34-a284-bed708813506', 10, 10, 'በክህነት እኔን የሚያገለግሉበትን የካህኑን የአሮንን ልብሰ ተክህኖና የልጆቹን ልብስ፥'),
  ('84c78d0c-4c56-55b4-a616-8cf23eacd9a9', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '9784e76a-80ff-5d34-a284-bed708813506', 11, 11, 'የሚቀቡትን የቅብዐቱንም ዘይት፥ ለመቅደሱ የሚያጥኑትን ዕጣን እንዳዘዝሁህ ሁሉ ያድርጉ።”'),
  ('5e282a00-5eb8-5225-a152-a7b232403186', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '52a6b333-20d3-51b7-a0e6-742497460950', 1, 12, 'እግዚአብሔርም ሙሴን እንዲህ ሲል ተናገረው፦'),
  ('508a32c9-072e-57c4-a532-2b4d02e175d7', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '52a6b333-20d3-51b7-a0e6-742497460950', 2, 13, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ እኔ የምቀድሳችሁ እግዚአብሔር እንደ ሆንሁ ታውቁ ዘንድ በእኔና በእናንተ ዘንድ ለልጅ ልጃችሁ ምልክት ነውና ሰንበቴን ፈጽሞ ጠብቁ።'),
  ('c81dfc54-e0b2-5500-a1d0-55cba87392be', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '52a6b333-20d3-51b7-a0e6-742497460950', 3, 14, 'ለእናንተ በእግዚአብሔር የተቀደሰች ናትና ሰንበቴን ጠብቁ፤ የሚያረክሳትም ሰው ሁሉ ፈጽሞ ይገደል፤ ሥራንም በእርስዋ የሠራ ሰው ሁሉ ያች ነፍስ ከሕዝብዋ መካከል ተለይታ ትጥፋ።'),
  ('7f8a160d-bdfa-556a-afca-230f2d22d9eb', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '52a6b333-20d3-51b7-a0e6-742497460950', 4, 15, 'ስድስት ቀን ሥራህን ሥራ፤ ሰባተኛዋ ቀን ግን ለእግዚአብሔር የተቀደስች የዕረፍት ሰንበት ናት፤ በሰንበት ቀን የሚሠራ ሁሉ ፈጽሞ ይገደል።'),
  ('960b03b3-6364-53d9-aae6-23e320b9d62b', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '52a6b333-20d3-51b7-a0e6-742497460950', 5, 16, 'የእስራኤልም ልጆች ለልጅ ልጃቸው ለዘለዓለም ቃል ኪዳን ዕረፍት ያደርጉ ዘንድ ሰንበትን ይጠብቁ።'),
  ('67e36a26-309d-506b-ae81-5a0533822f3a', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '52a6b333-20d3-51b7-a0e6-742497460950', 6, 17, 'እግዚአብሔር ሰማይንና ምድርን በስድስት ቀን ስለ ፈጠረ፥ በሰባተኛውም ቀን ሥራውን ፈጽሞ ስላረፈ፥ በእኔና በእስራኤል ልጆች ዘንድ የዘለዓለም ምልክት ነው።”'),
  ('f64c0978-bcaa-589c-ad4c-ecfd3f1f32de', '2c2e5148-12a7-5e49-a0c2-3e8333c548d7', '52a6b333-20d3-51b7-a0e6-742497460950', 7, 18, 'እግዚአብሔርም ከእርሱ ጋር በሲና ተራራ የተናገረውን በፈጸመ ጊዜ ሁለቱን የምስክር ጽላት፥ በእግዚአብሔር ጣት የተጻፈባቸውን የድንጋይ ጽላት ለሙሴ ሰጠው።'),
  ('c242a54a-951f-52f1-a6de-e51723b2c659', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 1, 1, 'ሕዝቡም ሙሴ ከተራራው ሳይወርድ እንደ ዘገየ ባዩ ጊዜ፥ ወደ አሮን ተሰብስበው፥ “ይህ ከግብፅ ምድር ያወጣን ሰው ሙሴ ምን እንደ ሆነ አናውቅምና ተነሥተህ በፊታችን የሚሄዱ አማልክት ሥራልን” አሉት።'),
  ('872ace81-deb5-557e-ad9c-c5f69a0ef103', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 2, 2, 'አሮንም፥ “በሚስቶቻችሁና በሴቶች ልጆቻችሁ ጆሮ ያሉትን የወርቅ ጌጦች አምጡልኝ” አላቸው።'),
  ('61d9db48-a553-5b93-a68c-2c87e3a21e3a', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 3, 3, 'ሕዝቡም ሁሉ በጆሮዎቻቸው ያሉትን የወርቅ ጌጦች ወደ አሮን አመጡለት።'),
  ('1da33273-d407-5de7-a1e5-7b14f82f0287', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 4, 4, 'ከእጃቸውም ተቀብሎ በመቅረጫ ቀረጸው፤ ቀልጦ የተሠራ ጥጃም አደረገው፤ እርሱም፥ “እስራኤል ሆይ፥ እነዚህ ከግብፅ ምድር ያወጡህ አማልክትህ ናቸው” አላቸው።'),
  ('da9f200a-2675-51eb-a596-2420dbbbf73e', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 5, 5, 'አሮንም በአየው ጊዜ መሠዊያውን በፊቱ ሠራ፤ አሮንም፥ “ነገ የእግዚአብሔር በዓል ነው” ሲል አወጀ።'),
  ('b489f05c-d5cf-55d8-a42c-c6b292c04f0d', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 6, 6, 'አሮንም በነጋው ማልዶ ተነሣ፤ የሚቃጠል መሥዋዕትንም ሠዋ፤ የደኅንነት መሥዋዕትንም አቀረበ ሕዝቡም ሊበሉና ሊጠጡ ተቀመጡ፤ ሊዘፍኑም ተነሡ።'),
  ('e8d88bdf-a563-546d-add6-29cfe2567190', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 7, 7, 'እግዚአብሔርም ሙሴን ተናገረው እንዲህም አለው፥ “ከግብፅ ምድር ያወጣኻቸው ሕዝብህ በድለዋልና ሂድ፤ ፈጥነህ ውረድ።'),
  ('ced16465-7965-5626-a2f8-b8dbc05b6ebd', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 8, 8, 'ካዘዝኋቸው መንገድ ፈጥነው ፈቀቅ አሉ፤ ቀልጦ የተሠራ የጥጃ ምስል ለራሳቸው አደረጉ፤ ሰገዱለትም፤ ሠዉለትም፤'),
  ('b7c07231-6aa9-526d-a86a-17f06094600b', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 9, 9, '‘እስራኤል ሆይ፥ እነዚህ ከግብፅ ምድር ያወጡህ አማልክትህ ናቸው’ አሉ።'),
  ('5c32a53e-4ce9-5d17-ae3e-61652871afe8', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 10, 10, 'አሁንም ተቈጥቼ አጠፋቸው ዘንድ ተወኝ፤ አንተንም ለታላቅ ሕዝብ አደርግሃለሁ።”'),
  ('8100a197-60e6-5e38-ae55-ad4f4689c07c', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 11, 11, 'ሙሴም በእግዚአብሔር በአምላኩ ፊት ጸለየ፤ አለም፥ “አቤቱ፥ በታላቅ ኀይልና በጽኑ እጅ ከግብፅ ምድር በአወጣኸው በሕዝብህ ላይ ለምን ተቈጣህ?'),
  ('816506a6-80cc-5925-ac63-63c9fec237f2', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 12, 12, 'ግብፃውያንስ፦ ‘በተራራ መካከል ሊገድላቸው፥ ከምድርም ፊት ሊያጠፋቸው ለክፋት አወጣቸው’ ብለው ስለ ምን ይናገራሉ? ከመዓትህ ተመለስ፤ ለሕዝብህም በክፋታቸው ላይ ራራ።'),
  ('f5bd40c0-0aab-567b-ab6f-f2c319ec6409', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 13, 13, 'ዘራችሁን እንደ ሰማይ ከዋክብት አበዛለሁ፤ ይህችንም የተናገርኋትን ምድር ሁሉ ለዘራችሁ እሰጣታለሁ፤ ለዘለዓለምም ይወርሱአታል ብለህ በራስህ የማልህላቸው ባሪያዎችህን አብርሃምንና ይስሐቅን ያዕቆብንም ዐስብ።”'),
  ('be3811fe-e74d-507b-a5a8-29a4b7af2ec8', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 14, 14, 'እግዚአብሔርም በሕዝቡ ላይ ሊያደርግ ስላሰበው ክፋት ይቅር አለ።'),
  ('99c98e1a-835d-5875-ab14-5713d6eccd5f', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 15, 15, 'ሙሴም ተመለሰ፤ ሁለቱንም የምስክር ጽላት በእጁ ይዞ ከተራራው ወረደ፤ የድንጋይ ጽላቱም በዚህና በዚያ በሁለት ወገን ተጽፎባቸው ነበር።'),
  ('1fd822e0-b36b-5889-a98f-a8086a93686c', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 16, 16, 'ጽላቱ የእግዚአብሔር ሥራ ነበሩ፤ ጽሕፈቱም በጽላቱ ላይ የተቀረጸባቸው የእግዚአብሔር ጽሕፈት ነበረ።'),
  ('73da1178-7f2b-5352-a965-8de1d300fa4c', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 17, 17, 'ኢያሱም ሲጮሁ የሕዝቡን ድምፅ ሰምቶ ሙሴን፥ “የሰልፍ ድምፅ በሰፈሩ ውስጥ አለ” አለው።'),
  ('0dd7ef30-d7e2-5147-abe5-1dbf323c84b0', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 18, 18, 'ሙሴም፥ “ይህ የድል ነሺዎች ወይም የድል ተነሺዎች ድምፅ አይደለም፤ ነገር ግን የወይን ስካር ድምፅ እሰማለሁ” አለው።'),
  ('801c95ef-f7c4-55be-a492-6fe6a45fea54', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 19, 19, 'እንዲህም ሆነ፤ ወደ ሰፈሩ ሲቀርብ ጥጃውንም ዘፈኑንም አየ፤ የሙሴም ቍጣ ተቃጠለ፤ እነዚያንም ሁለቱን ጽላት ከእጁ ጥሎ ከተራራው በታች ሰበራቸው።'),
  ('1d70c41f-4411-50e7-a6f1-27a69483becf', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 20, 20, 'የሠሩትንም ጥጃ ወስዶ በእሳት አቀለጠው፤ ፈጨው፤ አደቀቀውም፤ በውኃም ላይ በተነው፤ ለእስራኤልም ልጆች አጠጣቸው።'),
  ('4eae0b7e-9014-58aa-a591-c37318b60e62', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 21, 21, 'ሙሴም አሮንን፥ “ይህን ታላቅ ኀጢአት ታመጣበት ዘንድ ይህ ሕዝብ ምን አደረገህ?” አለው።'),
  ('711655fc-6281-579c-addf-250c6a28906a', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 22, 22, 'አሮንም እንዲህ አለ፥ “ጌታዬ ሆይ፥ በእኔ ላይ አትቈጣ፤ የዚህን ሕዝብ ጠባይ አንተ ታውቃለህ።'),
  ('e3db7b97-6068-5cf6-a5e3-83e854c7fa88', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 23, 23, 'እነርሱም ይህ ከግብፅ ምድር ያወጣን ሰው ሙሴ ምን እንደ ሆነ አናውቅምና በፊታችን የሚሄዱ አማልክት ሥራልን አሉኝ።'),
  ('55162849-d332-5fe5-a4fa-3a77b8ee4e30', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 24, 24, 'እኔም ከእናንተ ወርቅ ያለው ሰው ያምጣልኝ አልኋቸው፤ ሰጡኝም፤ በእሳትም ላይ ጣልሁት፤ ይህም ጥጃ ወጣ።”'),
  ('8a585c74-c47b-5522-a179-b7ad1ee7f03a', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 25, 25, 'ሙሴም በጠላቶቻቸው ፊት እንዲነወሩ አሮን ስድ ለቅቆአቸዋልና ሕዝቡ ስድ እንደ ተለቀቀ በአየ ጊዜ፥'),
  ('3e86054b-37db-586b-a5c7-2d3d892176a5', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 26, 26, 'ሙሴ በሰፈሩ ደጅ ቆሞ፥ “የእግዚአብሔር ወገን የሆነ ወደ እኔ ይምጣ” አለ፤ የሌዊ ልጆች ሁሉ ወደ እርሱ ተሰበሰቡ።'),
  ('ece00744-fd4c-5e52-a18e-4214957540de', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 27, 27, 'እርሱም፦ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፥ “እያንዳንዱ ሰይፉን በወገቡ ላይ ይታጠቅ፤ ሂዱና በሰፈሩ ውስጥ ከበር እስከ በር ተመላለሱ፤ እያንዳንዱም ወንድሙን፥ እያንዳንዱም ጎረቤቱን፥ እያንዳንዱም የቅርቡን ይግደል” አላቸው።'),
  ('c0f14ae4-a473-5937-a092-58dbea92a6b1', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 28, 28, 'የሌዊም ልጆች ሙሴ እንዳለ አደረጉ፤ በዚያም ቀን ከሕዝቡ ሦስት ሺህ ሰዎች ሞቱ።'),
  ('245d4b2f-6d99-522a-af24-f160b85b0e75', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 29, 29, 'ሙሴም፥ “ዛሬ በረከትን እንዲያወርድላችሁ ከእናንተ እያንዳንዱ ከልጁና፥ ከወንድሙ የተነሣ እግዚአብሔርን በእጃችሁ ደስ አሰኛችሁት” አላቸው።'),
  ('8d9ac3d9-eadb-5245-a3fe-8d06654af4ff', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 30, 30, 'በነጋውም ሙሴ ለሕዝቡ፥ “እናንተ ታላቅ በደል ሠርታችኋል፤ አሁንም አስተሰርይላችሁ ዘንድ ወደ እግዚአብሔር እወጣለሁ፤” አላቸው።'),
  ('5ac9454b-0b6c-5f3e-abe8-058da19150d0', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 31, 31, 'ሙሴም ወደ እግዚአብሔር ተመልሶ፥ “ጌታዬ ሆይ፥ እለምንሃለሁ፤ እኒህ ሕዝብ ታላቅ ኀጢአት ሠርተዋል፤ ለራሳቸውም የወርቅ አማልክት አድርገዋል፤'),
  ('7018be37-6bb8-575b-a22e-84befef8a403', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 32, 32, 'አሁንም ይህን ኀጢአታቸውን ይቅር ትላቸው እንደሆነ ይቅር በላቸው፤ ያለዚያ ግን ከጻፍኸው መጽሐፍ ደምስሰኝ” አለ።'),
  ('822e606f-5fa0-5a13-aafe-e73588a8210d', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 33, 33, 'እግዚአብሔርም ሙሴን፥ “በፊቴ የበደለውን እርሱን ከመጽሐፌ እደመስሰዋለሁ።'),
  ('16909a47-4405-5887-a5e5-65a2f3a34959', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 34, 34, 'አሁንም ሂድ፤ ይህንም ሕዝብ ወደ ነገርሁህ ቦታ ምራ፤ እነሆ፥ መልአኬ በፊትህ ይሄዳል፤ ነገር ግን በምጐበኝበት ቀን ኀጢአታቸውን አመጣባቸዋለሁ” አለው።'),
  ('686b5bbb-960f-5912-accf-632a1d4e1bd3', '45f8facc-d9a1-5e6e-a7be-fdc221ec7145', '044a68b0-7d9f-5784-aaad-8d11dabc6e8c', 35, 35, 'አሮን የሠራውን ጥጃ ስለ ሠሩ እግዚአብሔር ሕዝቡን ቀሠፈ።'),
  ('2f41ffe8-8a3e-5918-af5e-f8415bd4a99f', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '4c337caa-7327-5b41-af0c-beeb686d8d0d', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፥ “ሂድ፤ አንተ ከግብፅ ከአወጣኸው ሕዝብህ ጋር ለአብርሃምና ለይስሐቅ ለያዕቆብም ለዘራችሁ እሰጣታለሁ ብዬ ወደ ማልሁባት ምድር ውጣ።'),
  ('3236112e-f164-5a17-ac71-3a335d04612b', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '4c337caa-7327-5b41-af0c-beeb686d8d0d', 2, 2, 'መልአኬንም ከአንተ ጋር በፊትህ እልካለሁ፤ ከነዓናዊውን፥ አሞሬዎናዊውንም፥ ኬጤዎናዊውንም፥ ፌርዜዎናዊውንም፥ ጌርጌሴዎናዊውን፥ ኤዌዎናውዊውንም፥ ኢያቡሴዎናዊውንም ያወጣቸዋል።'),
  ('a824a3b9-d0ea-5564-a315-26eee5f9b5d4', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '4c337caa-7327-5b41-af0c-beeb686d8d0d', 3, 3, 'ወተትና ማርም ወደምታፈስሰው ምድር አስገባሃለሁ፤ አንገተ ደንዳና ስለሆኑ ሕዝብህ በመንገድ ላይ እንዳላጠፋህ እኔ ከአንተ ጋር አልወጣም።”'),
  ('d164bc57-eb41-5578-ae8c-0c88fa86bd36', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '4c337caa-7327-5b41-af0c-beeb686d8d0d', 4, 4, 'ሕዝቡም ይህን ክፉ ወሬ ሰምተው ታላቅ ኀዘን አዘኑ፤'),
  ('b91ef478-ba66-5152-ab78-e41758187c47', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '4c337caa-7327-5b41-af0c-beeb686d8d0d', 5, 5, 'እግዚአብሔርም ሙሴን፥ “ለእስራኤል ልጆች እናንተ አንገተ ደንዳና ሕዝብ ናችሁ፤ ሌላ መቅሠፍት እንዳላመጣባችሁና እንዳላጠፋችሁ ተጠንቀቁ፤ አሁንም የክብር ልብሳችሁንና ጌጣችሁን ከእናንተ አውጡ፤ የማደርግባችሁንም አሳያችኋለሁ በላቸው” አለው።'),
  ('f4668477-513d-5949-a321-0d07855745d2', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '4c337caa-7327-5b41-af0c-beeb686d8d0d', 6, 6, 'የእስራኤልም ልጆች ከኮሬብ ተራራ ጀምረው ልብሶቻቸውንና ጌጦቻቸውን አወጡ።'),
  ('dac1d1cb-15a1-546a-acda-181cb8d7f5ff', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '5cde1cd0-3dd2-5d48-a227-92d850ba113d', 1, 7, 'ሙሴም ድንኳኑን ወስዶ ከሰፈር ውጭ ይተክለው ነበር፤ ከሰፈሩም ራቅ ያደርገው ነበር፤ “የምስክሩም ድንኳን” ብሎ ጠራው። እግዚአብሔርንም የፈለገ ሁሉ ከሰፈር ውጭ ወደአለው ወደ ድንኳኑ ይወጣ ነበር።'),
  ('04848b38-0446-50ec-a972-7c7a49392007', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '5cde1cd0-3dd2-5d48-a227-92d850ba113d', 2, 8, 'ሙሴም ከሰፈር ውጭ ወደአለው ድንኳን በሄደ ጊዜ ሕዝቡ ሁሉ፥ እያንዳንዱም በድንኳኑ ደጃፍ እየጠበቀ ይቆም ነበር፤ ሙሴም ወደ ድንኳኑ እስኪገባ ድረስ ይመለከቱት ነበር።'),
  ('c0ec63cd-8b13-51fa-ab92-bfed8af9c621', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '5cde1cd0-3dd2-5d48-a227-92d850ba113d', 3, 9, 'ሙሴም ወደ ድንኳኑ በገባ ጊዜ ዐምደ ደመና ይወርድ ነበር፤ በድንኳኑም ደጃፍ ይቆም ነበር፤ እግዚአብሔርም ሙሴን ይናገረው ነበር።'),
  ('253756bd-5c59-5537-a844-9f9b0789c00c', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '5cde1cd0-3dd2-5d48-a227-92d850ba113d', 4, 10, 'ሕዝቡም ሁሉ ዐምደ ደመናው በድንኳኑ ደጃፍ ሲቆም ያየው ነበር፤ ሕዝቡም ሁሉ ተነሥቶ እያንዳንዱ በድንኳኑ ደጃፍ ይሰግድ ነበር።'),
  ('dcf3ce50-d974-5d10-aec6-145dbc9caaa3', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '5cde1cd0-3dd2-5d48-a227-92d850ba113d', 5, 11, 'እግዚአብሔርም፥ ሰው ከባልንጀራው ጋር እንደሚነጋገር ፊት ለፊት ከሙሴ ጋር ይነጋገር ነበር። ሙሴም ወደ ሰፈሩ ይመለስ ነበር፤ ነገር ግን አገልጋዩ ብላቴና የነዌ ልጅ ኢያሱ ከድንኳኑ አይወጣም ነበር።'),
  ('30068418-f6cd-568a-aa94-d188042e047f', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 1, 12, 'ሙሴም እግዚአብሔርን፥ “እነሆ፥ አንተ፦ ይህን ሕዝብ አውጣ ትለኛለህ፤ ነገር ግን ከእኔ ጋር የምትልከውን አላስታወቅኸኝም። አንተም ከሁሉ ይልቅ ዐወቅሁህ፥ ደግሞም በእኔ ፊት ሞገስን አገኘህ አልኸኝ።'),
  ('bb4439b6-4fc7-5bdb-a20f-16d6a1b9f5dc', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 2, 13, 'አሁንም በፊትህ ሞገስን አግኝቼ እንደ ሆነ፥ ዐውቅህ ዘንድ በፊትህም ሞገስን አገኝ ዘንድ ይህም ትልቅ ሕዝብ ሕዝብህ እንደ ሆነ ዐውቅ ዘንድ ተገለጥልኝ” አለው።'),
  ('7f025067-a501-5195-a78b-64cf5f4926ae', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 3, 14, 'እግዚአብሔርም፥ “እኔ በፊትህ እሄዳለሁ፥ አሳርፍህማለሁ” አለው።'),
  ('e7263f57-00c1-521e-a58b-1815d063e71a', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 4, 15, 'እርሱም፥ “አንተ ከእኛ ጋር ካልወጣህስ፥ ከዚህ አታውጣን።'),
  ('4b5d6622-b6a4-5410-a6dc-495bc0764f77', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 5, 16, 'በምድርም ከአለው ሕዝብ ሁሉ እኔና ሕዝብህ ተለይተን እንከብር ዘንድ አንተ ከእኛ ጋር ካልሄድህ፥ እኔና ሕዝብህ በአንተ ዘንድ በእውነት ሞገስ ማግኘታችን በምን ይታወቃል?” አለው።'),
  ('eff3eb59-eea0-5aa2-a427-7f6a857e36e3', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 6, 17, 'እግዚአብሔርም ሙሴን አለው፥ “ይህን ያልኸኝን ነገር አደርግልሃለሁ፤ በፊቴ ሞገስን አግኝተሀልና ከሁሉ ይልቅ ዐውቄሃለሁና”አለው።'),
  ('ac6912b0-885c-5641-a1a8-e1cd6dae4bb6', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 7, 18, 'እርሱም፥ “ክብርህን አሳየኝ” አለው።'),
  ('507ff583-d871-5893-a296-cb0841df356f', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 8, 19, 'እግዚአብሔርም፥ “እኔ በክብሬ በፊትህ አልፋለሁ፤ የእግዚአብሔርንም ስም በፊትህ እጠራለሁ፤ ይቅርም የምለውን ይቅር እላለሁ፤ የምምረውንም እምራለሁ” አለ።'),
  ('da097444-f431-55c1-a60c-8b2960e7922f', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 9, 20, 'እግዚአብሔርም ሙሴን፥ “ሰው አይቶኝ አይድንምና ፊቴን ማየት አይቻልህም” አለ።'),
  ('81baa73c-28d0-5e0c-a957-06a95fe47cc8', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 10, 21, 'እግዚአብሔርም ሙሴን፥ “እነሆ፥ ስፍራ በእኔ ዘንድ አለ፥ በዐለቱም ላይ ትቆማለህ፤'),
  ('83a6548e-3842-545e-a3f8-679dc8a8c1a7', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 11, 22, 'ክብሬም በአለፈ ጊዜ በአለቱ ስንጥቅ ውስጥ አኖርሃለሁ፤'),
  ('453d0630-c73c-539c-ae7c-35cb95a8d9a1', 'ba4e89a6-14a9-5761-a799-aef18d4cfb29', '7268859c-b7f0-55c2-a89e-6c4e63360dc9', 12, 23, 'እስከ አልፍም ድረስ እጄን በላይህ እጋርዳለሁ፤ እጄንም ፈቀቅ አደርጋለሁ፤ በዚያ ጊዜ ጀርባዬን ታያለህ፤ ፊቴ ግን ለአንተ አይታይም።”'),
  ('21518956-ca00-5ef7-a45f-89e212ad0a49', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '42ceaa29-9d31-5ed9-a426-b39c6f2bc669', 1, 1, 'እግዚአብሔርም ሙሴን አለው፥ “ሁለት የድንጋይ ጽላት እንደ ፊተኞቹ አድርገህ ቅረጽ፤ ወደ እኔም ወደ ተራራ ውጣ፤ በሰበርሃቸው በፊተኞቹ ጽላት የነበሩትን ቃላት እጽፍባቸዋለሁ።'),
  ('c53ccc2a-cf20-59bf-ac45-5436b79a293f', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '42ceaa29-9d31-5ed9-a426-b39c6f2bc669', 2, 2, 'ለጥዋትም የተዘጋጀህ ሁን፤ ወደ ሲና ተራራ ወጥተህ በዚያ በተራራው ራስ ላይ በፊቴ ቁም።'),
  ('d57f37e1-765f-5723-a919-aa12e3aec203', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '42ceaa29-9d31-5ed9-a426-b39c6f2bc669', 3, 3, 'ከአንተም ጋር ማንም ሰው አይውጣ፤ በተራራውም ሁሉ ማንም አይታይ፤ መንጎችና ከብቶችም በዚያ ተራራ አጠገብ አይሰማሩ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4dc2c667-a254-5332-a518-95c679362d13', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '42ceaa29-9d31-5ed9-a426-b39c6f2bc669', 4, 4, 'ሙሴም እንደ ፊተኞቹ አድርጎ ሁለት የድንጋይ ጽላት ቀረጸ፤ ሁለቱንም የድንጋይ ጽላት በእጁ ወሰደ፤ በነጋውም ማልዶ እግዚአብሔር እንዳዘዘው ወደ ሲና ተራራ ወጣ፤'),
  ('393c59f5-6239-5d20-ac0f-be51344482d3', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '42ceaa29-9d31-5ed9-a426-b39c6f2bc669', 5, 5, 'እግዚአብሔርም በደመናው ውስጥ ወረደ፤ በዚያም ከእርሱ ጋር ቆመ፤ የእግዚአብሔርንም ስም ጠራ።'),
  ('baf57527-b746-591b-ab13-87d5a2e0d96a', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '42ceaa29-9d31-5ed9-a426-b39c6f2bc669', 6, 6, 'ጌታም በፊቱ አለፈ፥ “ስሜም ጌታ እግዚአብሔር፥ መሓሪ፥ ይቅር ባይ፥ ከመዓት የራቀ ምሕረቱ የበዛ ጻድቅ፥'),
  ('406090de-9258-52a7-a6d1-684faa91e0c5', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '42ceaa29-9d31-5ed9-a426-b39c6f2bc669', 7, 7, 'ለብዙ ሺህ ጽድቅን የሚጠብቅ፥ ቸርነትን የሚያደርግ፥ አበሳንና መተላለፍን፥ ኀጢአትንም ይቅር የሚል፥ በደለኛውንም ከቶ የማያነጻ፥ የአባቶችንም ኀጢአት በልጆች፥ እስከ ሦስትና እስከ አራት ትውልድም በልጅ ልጆች የሚያመጣ አምላክ ነው” ሲል አወጀ።'),
  ('c92dc32c-1998-5549-a3ff-7589eaa128f8', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '42ceaa29-9d31-5ed9-a426-b39c6f2bc669', 8, 8, 'ሙሴም ፈጥኖ ወደ መሬት ተጎነበሰና ለእግዚአብሔር ሰገደ፦'),
  ('b745c4b7-f1f3-5df4-a2f2-834369b5f776', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '42ceaa29-9d31-5ed9-a426-b39c6f2bc669', 9, 9, '“አቤቱ በፊትህስ ሞገስን አግኝቼ እንደ ሆነ፥ ይህ ሕዝብ አንገተ ደንዳና ነውና ጌታዬ ከእኛ ጋር ይሂድ፤ ጠማማነታችንን፥ ኀጢአታችንንና በደላችንን ይቅር በለን፤ ለአንተም እንሆናለን” አለ።'),
  ('8f22705a-52fb-5568-a47d-851416819bc5', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 1, 10, 'እግዚአብሔርም ሙሴን አለው፥ “እነሆ፥ እኔ በሕዝብህ ፊት ሁሉ ቃል ኪዳን አደርጋለሁ፤ በምድር ሁሉ፥ በአሕዛብም ሁሉ ዘንድ እንደ እርሱ ያለ ከቶ ያልተደረገውን ታላቅ ተአምራትን አደርግልሃለሁ፤ እኔም የማደርግልህ ነገር ድንቅ ነውና አንተ በመካከሉ ያለህበት ይህ ሕዝብ ሁሉ የእግዚአብሔርን ሥራ ያያል።'),
  ('c909815f-a2db-5109-a065-9dbdb1627c80', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 2, 11, 'በዚህ ቀን የማዝዝህን ነገር ጠብቅ፤ እነሆ፥ እኔ አሞሬዎናዊውን፥ ከነዓናዊውንም፥ ኬጤዎናዊውንም፥ ፌርዜዎናዊውንም፥ ጌርጌሴዎናዊውንም፥ ኤዌዎናዊውንም፥ ኢያቡሴዎናዊውንም ከፊትህ አወጣለሁ።'),
  ('3f47170e-b729-51a6-a0a7-3af56372d45a', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 3, 12, 'በመካከልህ ወጥመድ እንዳይሆኑብህ አንተ በምትገባበት ምድር ከሚኖሩ ሰዎች ጋር ቃል ኪዳን እንዳታደርግ ተጠንቀቅ፤'),
  ('73ea02b9-6b8e-5ce3-a1d7-f468aa8a8924', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 4, 13, 'ነገር ግን መሠውያዎቻቸውን ታፈርሳላችሁ፤ ሐውልቶቻቸውንም ትሰብራላችሁ፤ የማምለኪያ ዐፀዶቻቸውን ትቈርጣላችሁ፤ ጣዖቶቻቸውንም በእሳት ታቃጥላላችሁ፤'),
  ('fa325b12-75d0-596b-ab95-206556584130', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 5, 14, 'ስሙ ቀናተኛ የሆነ እግዚአብሔር ቅንዐት ያለው አምላክ ነውና ለሌላ አምላክ አትስገድ።'),
  ('07854941-f78b-5901-add3-b82de31e5dde', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 6, 15, 'በዚያች ምድር ከሚኖሩ ሰዎች ጋር ቃል ኪዳን እንዳታደርግ፥ እነርሱ አምላኮቻቸውን ተከትለው በአመነዘሩና በሠዉላቸው ጊዜ እንዳይጠሩህ፥ ከመሥዋዕታቸውም እንዳትበላ፥'),
  ('000fb6b4-75b2-528a-a1ac-0d14bb2d4eec', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 7, 16, 'ሴቶች ልጆቻቸውምንም ከወንድ ልጆችህ፥ ሴቶች ልጆችህንም ከወንድ ልጆቻቸው ጋር እንዳታጋባ፥ ልጆቻቸውም አምላኮቻቸውን ተከትለው ሲያመነዝሩ ከአምላኮቻቸው በኋላ ሄደው አመንዝረውም ልጆችህን እንዳያስቱ ተጠንቀቅ።'),
  ('9001a115-bc76-50fa-a6ac-64d48fa72288', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 8, 17, 'ቀልጠው የተሠሩትን አማልክት ለአንተ አታድርግ።'),
  ('4569432e-61fa-5c15-a581-beafbc447f8a', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 9, 18, '“የቂጣውን በዓል ትጠብቀዋለህ። በሚያዝያ ወር ከግብፅ ወጥተሃልና በታዘዘው ዘመን በሚያዝያ ወር እንዳዘዝሁህ ሰባት ቀን ቂጣ ብላ።'),
  ('b0295000-f610-5546-aaf1-3ed9b28af0a0', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 10, 19, 'መጀመሪያ የሚወለድ ተባት ሁሉ የእኔ ነው፤ የላምህም በኵር፥ የበግህም በኵር፥ የበሬህም በኵር ሁሉ የእኔ ነው።'),
  ('86dc343d-a5b1-5e96-a763-8f4bd3f83c21', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 11, 20, 'የአህያውንም በኵር በበግ ትዋጀዋለህ፤ ባትዋጀው ግን ዋጋውን ትሰጣለህ። የልጆችህንም በኵር ሁሉ ትዋጃለህ። በፊቴም ባዶ እጅህን አትታይ።'),
  ('4ad3fbce-63b3-5db5-a281-d40fbc5944a3', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 12, 21, '“ስድስት ቀን ሥራህን ትሠራለህ፤ በሰባተኛውም ቀን ታርፋለህ። በምትዘራበትና በምታጭድበት ዘመን ታርፋለህ።'),
  ('91d41e55-8601-580c-a74c-88ad858ff01a', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 13, 22, 'የሰባቱንም ሱባዔ በዓል ታደርጋለህ፤ እርሱም የስንዴ መከር መጀመሪያ ነው፤ በዓመቱም መካከል የመክተቻ በዓል ታደርጋለህ።'),
  ('c863a677-19b9-5d9b-ab5f-dc113ee8caa9', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 14, 23, 'ወንድ ልጅህ ሁሉ በእስራኤል አምላክ በእግዚአብሔር ፊት በዓመት ሦስት ጊዜ ይታይ።'),
  ('c2c03e2c-8ccb-57a5-a15e-b5138b3ace4f', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 15, 24, 'አሕዛብን ከፊትህ በአወጣሁ ጊዜ ሀገርህን አሰፋለሁ፤ በአምላክህ በእግዚአብሔር ፊትም ለመታየት በዓመት ሦስት ጊዜ ስትወጣ ማንም ምድርህን አይመኝም።'),
  ('bbaef902-c43f-51ac-a8d8-17186b68937d', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 16, 25, '“የመሥዋዕቴን ደም ከቦካ እንጀራ ጋር አትሠዋ፤ የፋሲካውም በዓል መሥዋዕት እስከ ነገ አይደር።'),
  ('511e8f72-e7b1-52d2-a175-a8d8510d2bf7', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 17, 26, 'የመጀመሪያውን የምድርህን ፍሬ ወደ አምላክህ ወደ እግዚአብሔር ቤት ትወስዳለህ። ጠቦቱን በእናቱ ወተት አትቀቅል።”'),
  ('85e59114-cf99-50ab-a0a3-be3e35a31996', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 18, 27, 'እግዚአብሔርም ሙሴን፥ “በእነዚህ ቃሎች ከአንተና ከእስራኤል ጋር ቃል ኪዳን አድርጌአለሁና እነዚህን ቃሎች ጻፍ” አለው።'),
  ('75f032f6-099d-5287-ab05-a59cbdf5621d', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', '98a9c825-a197-54c1-a582-d8ce38adbedb', 19, 28, 'በዚያም አርባ ቀንና አርባ ሌሊት በእግዚአብሔር ፊት ነበረ፤ እንጀራም አልበላም፤ ውኃም አልጠጣም። በጽላቱም ዐሥሩን የቃል ኪዳን ቃሎች ጻፈ።'),
  ('a95ed0a0-7052-56cb-a098-ebe0657ffc9c', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', 'e208bdfe-ff87-5b2c-ada2-156b5d8dfb68', 1, 29, 'እንዲህም ሆነ፤ ሙሴ ከሲና ተራራ በወረደ ጊዜ ሁለቱ ጽላት በሙሴ እጅ ነበሩ፤ ሙሴም ከተራራው በወረደ ጊዜ ከእግዚአብሔር ጋር ሲነጋገር ፊቱ እንዳንጸባረቀ አላወቀም ነበር።'),
  ('691166a6-798f-5c06-ad67-c159b9598125', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', 'e208bdfe-ff87-5b2c-ada2-156b5d8dfb68', 2, 30, 'አሮንና የእስራኤልም ልጆች ሁሉ እነሆ፥ ፊቱ እንዳንጸባረቀ ሙሴን በአዩ ጊዜ፥ ወደ እርሱ ለመቅረብ ፈሩ።'),
  ('38cb6fe6-8841-5c38-a5b1-52816a746213', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', 'e208bdfe-ff87-5b2c-ada2-156b5d8dfb68', 3, 31, 'ሙሴም ጠራቸው፤ አሮንም የማኅበሩም አለቆች ሁሉ ወደ እርሱ ተመለሱ፤ ሙሴም ተናገራቸው።'),
  ('0d9799c9-784a-52a1-a197-fc161b313e9f', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', 'e208bdfe-ff87-5b2c-ada2-156b5d8dfb68', 4, 32, 'ከዚያም በኋላ የእስራኤል ልጆች ሁሉ ወደ እርሱ ቀረቡ፤ እግዚአብሔርም በሲና ተራራ የተናገረውን ነገር ሁሉ አዘዛቸው።'),
  ('c5bd5fee-3884-52f5-aa54-6ef6c456f097', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', 'e208bdfe-ff87-5b2c-ada2-156b5d8dfb68', 5, 33, 'ሙሴም ለእነርሱ ተናግሮ ከጨረሰ በኋላ በፊቱ መሸፈኛ አደረገ።'),
  ('dcac3e7f-c637-58b8-a0df-2fd720c7ee58', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', 'e208bdfe-ff87-5b2c-ada2-156b5d8dfb68', 6, 34, 'ሙሴም ከእርሱ ጋር ይነጋገር ዘንድ ወደ እግዚአብሔር በገባ ጊዜ እስኪወጣ ድረስ መሸፈኛውን ከፊቱ ያነሣ ነበር፤ በወጣም ጊዜ ለእስራኤል ልጆች የታዘዘውን ነገር ይነግራቸው ነበር።'),
  ('cd06ad99-43cf-5878-ae31-b6a063477979', 'd777a4bb-7fc7-5b5a-affd-84c741b8298e', 'e208bdfe-ff87-5b2c-ada2-156b5d8dfb68', 7, 35, 'የእስራኤልም ልጆች የሙሴን ፊት እንዳንጸባረቀ ያዩ ነበር፤ እርሱም ከእርሱ ጋር ሊነጋገር እስኪገባ ድረስ እንደ ገና በፊቱ መሸፈኛ ያደርግ ነበር።'),
  ('587ae4b1-ab3d-553a-a605-3b2555aee9e0', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', '4707d5c6-820c-590b-a0a0-9c9749e7133d', 1, 1, 'ሙሴም የእስራኤልን ልጆች ማኅበር ሁሉ ሰብስቦ እንዲህ አላቸው፥ “ታደርጉ ዘንድ እግዚአብሔር ያለው ነገር ይህ ነው፤'),
  ('313a7bd2-a0f1-55ac-a879-65475eddd2f8', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', '4707d5c6-820c-590b-a0a0-9c9749e7133d', 2, 2, 'ስድስት ቀን ሥራህን ትሠራለህ፤ በሰባተኛው ቀን ታርፋለህ፤ ለእግዚአብሔር የተቀደሰ የዕረፍት ሰንበት ነው፤ የሚሠራበትም ሁሉ ይሙት።'),
  ('5e38d2c8-923f-5aa4-a393-51afbc990579', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', '4707d5c6-820c-590b-a0a0-9c9749e7133d', 3, 3, 'በማደሪያዎቻችሁ ውስጥ በሰንበት ቀን እሳትን አታንድዱ፤ እኔ እግዚአብሔር ነኝ።”'),
  ('08ece3eb-5b84-5740-ab30-92566a002e7d', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c4c4e077-bbaf-5819-a6aa-57de023f2332', 1, 4, 'ሙሴም ለእስራኤል ልጆች ማኅበር ሁሉ አላቸው፥ “እግዚአብሔር እንዲህ ብሎ ያዘዘው ነገር ይህ ነው፤'),
  ('ec38f396-8891-59ef-ae38-33ad9de30a79', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c4c4e077-bbaf-5819-a6aa-57de023f2332', 2, 5, 'ከእናንተ ዘንድ ለእግዚአብሔር ቍርባንን አቅርቡ፤ የልብ ፈቃድ ያለው ከገንዘቡ የመጀመሪያውን ለእግዚአብሔር ያምጣ፤ ወርቅና ብር፥ ናስም፤'),
  ('10b788bc-842a-5c3b-a474-fcb622ec32e1', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c4c4e077-bbaf-5819-a6aa-57de023f2332', 3, 6, 'ሰማያዊም፥ ሐምራዊም፥ ድርብ ቀይ ግምጃም፥ የተፈተለ በፍታም፥ የፍየል ጠጕርም፤'),
  ('0cafaa96-82a0-54e8-a1e7-0fa14fe5adae', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c4c4e077-bbaf-5819-a6aa-57de023f2332', 4, 7, 'ቀይ ቀለምም የገባበት የአውራ በግ ቍርበት፥ የአቆስጣም ቍርበት፥ የማይነቅዝም ዕንጨት፤'),
  ('16635a47-7d9f-5d95-aacb-e57f179ee5d1', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c4c4e077-bbaf-5819-a6aa-57de023f2332', 5, 8, 'ለመብራትም ዘይት፥ ለቅብዐት ሽቱን፥ ለማዕጠንት ዕጣንን፤'),
  ('be15ee5a-7941-573d-a82d-d636336ef000', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c4c4e077-bbaf-5819-a6aa-57de023f2332', 6, 9, 'የመረግድ ድንጋይና የተቀረጸ ድንጋይ፥ ለልብሰ መትከፍና ለልብሰ እንግድዓ የሚደረግ ፈርጥ ያምጣ።'),
  ('22eab949-1cac-5b04-a736-c208e058c9e0', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 1, 10, '“በእናንተ ዘንድ ያለ፥ በልቡ ጥበበኛ የሆነ ሁሉ መጥቶ እግዚአብሔር ያዘዘውን ሁሉ ያድርግ።'),
  ('aaf5d080-4dfa-5d2f-a1b8-c7c8afaced45', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 2, 11, 'ድንኳኑንም፥ አደባባዩንም፥ መደረቢያውንም፥ መያዣዎቹንም፥ ሳንቆቹንም፥ መወርወሪያዎቹንም፥ ምሰሶዎችንና እግሮቻቸውን፤'),
  ('94d7e8a6-a66d-5e50-a816-2bc955070808', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 3, 12, 'የቃል ኪዳኑን ታቦትም፥ መሎጊያዎቹንም፥ የስርየት መክደኛውንም፥ መጋረጃውንም፤'),
  ('4174f592-6439-539d-af2f-48ef0bd4c77a', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 4, 13, 'ገበታውንና መሎጊያዎቹንም፥ ዕቃውንም ሁሉ፥ ኅብስተ ገጹንም፤'),
  ('ae90d077-ca5d-5fc2-aba1-58b823382c06', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 5, 14, 'መብራት የሚያበሩበትን መቅረዙን፥ ዕቃውንም ሁሉ፥ ቀንዲሉንም፥ የመብራቱንም ዘይት፤'),
  ('a25fde5c-2235-5626-a853-afe02f075998', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 6, 15, 'የዕጣኑንም መሠዊያ፥ መሎጊያዎቹንም፥ የቅብዐቱንም ዘይት፥ ጣፋጩንም ዕጣን፥ ለማደሪያውም ደጃፍ የሚሆን የደጃፉን መጋረጃ፤'),
  ('ce0b1247-2cae-54c5-a9b3-236e6fea08ee', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 7, 16, 'ለሚቃጠል መሥዋዕት የሚሆነውን መሠዊያውን፥ የናሱንም መከታ፥ መሎጊያዎቹንም፥ ዕቃውንም ሁሉ፥ የመታጠቢያውን ሰንም፥ መቀመጫውንም፤'),
  ('5d2f0c75-8d0c-5e86-adea-f4b0cf8b2fd5', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 8, 17, 'የአደባባዩን መጋረጆች፥ ምሰሶዎችንም፥ እግሮቻቸውንም፥ የአደባባዩንም ደጃፍ መጋረጃ፤'),
  ('39d59f71-8bc5-5d74-ac65-a169e5958001', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 9, 18, 'የማደሪያውን ካስማዎች፥ የአደባባዩንም ካስማዎች፥ አውታሮቻቸውንም፤'),
  ('7a25b2ea-38a1-5269-a9cf-ee5697d89b73', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 10, 19, 'በመቅደስ ውስጥ ለማገልገል በብልሃት የተሠሩትን ልብሶች፥ በክህነት ያገለግሉበት ዘንድ የተቀደሱትን የካህኑን የአሮንን ልብሶች፥ የልጆቹንም ልብሶች።”'),
  ('15a8780a-77c6-59e1-a805-588f0cb870f0', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 11, 20, 'የእስራኤልም ልጆች ማኅበር ሁሉ ከሙሴ ዘንድ ወጡ።'),
  ('a39a1c1e-256d-5bfb-a892-e056780d56c7', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 12, 21, 'ከእነርሱም ሰው ሁሉ እያንዳንዱ ልቡ እንዳነሣሣው፥ መንፈሱም እሺ እንዳሰኘው ለምስክሩ ድንኳን ሥራ ለማገልገያውም ሁሉ ለመቅደስ ልብስ ለእግዚአብሔር ስጦታ አመጡ።'),
  ('027cdb41-3690-5b97-abb3-ac4411451319', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 13, 22, 'ወንዶችና ሴቶችም ልባቸው እንደ ፈቀደ ማርዳዎችን፥ ሎቲዎችንም፥ ቀለበቶችንም፥ ድሪዎችንም፥ የወርቅ ጌጦችንም ሁሉ አመጡ፤ ሰዎችም ሁሉ የወርቅ ስጦታ ለእግዚአብሔር አቀረቡ።'),
  ('10feb743-582b-5f09-a2aa-a6de0fb36483', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 14, 23, 'ሰማያዊም፥ ሐምራዊም፥ ቀይ ግምጃም፥ የተፈተለ በፍታም፥ የፍየል ጠጕርም፥ ቀይ የአውራ በግ ቍርበትም፥ የአቆስጣ ቍርበትም ያላቸው ሰዎች ሁሉ አመጡ።'),
  ('dd9c9f46-1bfc-5fbd-a936-af600e95e091', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 15, 24, 'ስዕለት የተሳለ ሁሉ፥ የብርንም፥ የናስንም ስጦታ ለእግዚአብሔር ቍርባን አቀረበ፤ የማይነቅዝ ዕንጨት ያለው ሁሉ ለድንኳኑ ማገልገያ ለሚያስፈልገው ሥራ አመጣ።'),
  ('dc9afb8b-6165-5d4e-a24d-5248575402df', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 16, 25, 'በልባቸው ጥበበኞች የሆኑ ሴቶችም በእጃቸው ፈተሉ፤ የፈተሉትንም ሰማያዊውን፥ ሐምራዊውንም፥ ቀዩንም ግምጃ፥ ጥሩውንም በፍታ አመጡ።'),
  ('2c8e4c18-4fe0-5b33-a634-437357516476', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 17, 26, 'ልባቸውም በጥበብ ያስነሣቸው ሴቶች ሁሉ የፍየልን ጠጕር ፈተሉ።'),
  ('806c774f-d74e-5f1a-a235-91c4cd8aba56', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 18, 27, 'አለቆችም የመረግድ ድንጋይና የተቀረጸ ድንጋይን ለልብሰ መትከፍና ለልብሰ እንግድዓ የሚገቡትንም ፈርጦችን፥'),
  ('5ac92245-a099-506d-affa-a2a0043fb2e1', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 19, 28, 'ለመብራትም፥ ለቅብዐት ዘይትም፥ ለጣፋጭ ዕጣንም ሽቱንና ዘይትን አመጡ።'),
  ('89858f38-4172-55fe-a498-792c6057d4b2', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', 'c0394812-46b8-5834-a1dd-3dfd8bd5b39d', 20, 29, 'ከእስራኤል ልጆችም ያመጡ ዘንድ ልባቸው ያስነሣቸው ወንዶችና ሴቶች ሁሉ ሙሴ ይሠራ ዘንድ እግዚአብሔር ላዘዘው ሥራ ሁሉ ለእግዚአብሔር ስጦታ በፈቃዳቸው አመጡ።'),
  ('4235abce-82dc-50fa-aa5a-97d61e9371eb', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', '8cd04758-de43-541c-ad0b-1d2565d96e89', 1, 30, 'ሙሴም የእስራኤልን ልጆች አላቸው፥ “እዩ፥ እግዚአብሔር ከይሁዳ ነገድ የሆነውን የሆር የልጅ ልጅ፥ የኡሪ ልጅ ባስልኤልን በስሙ ጠራው።'),
  ('cf15b10b-680b-50ad-abd0-232a0ed0630d', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', '8cd04758-de43-541c-ad0b-1d2565d96e89', 2, 31, 'በሥራ ሁሉ ብልሃት፥ በጥበብም፥ በማስተዋልም፥ በዕውቀትም የእግዚአብሔርን መንፈስ ሞላበት፤'),
  ('6bd8d522-4ddf-509f-a47b-d2b81b4f6a46', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', '8cd04758-de43-541c-ad0b-1d2565d96e89', 3, 32, 'በአናጺዎች ላይ አለቃ ይሆን ዘንድ፥ የጥበብንም ሥራ ያስተውል ዘንድ፥ በወርቅና በብር፥ በናስም ይሠራ ዘንድ፥'),
  ('fb7619d1-856c-566c-a665-b7ff702ab5ab', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', '8cd04758-de43-541c-ad0b-1d2565d96e89', 4, 33, 'በፈርጥ የሚሆነውን የዕንቍ ድንጋይ ይቀርጽ ዘንድ፥ ዕንጨቱንም ይጠርብ ዘንድ፥ የብልሃት ሥራውንም ሁሉ ይሠራ ዘንድ።'),
  ('ee1c568a-1663-57ad-a3c1-813ed3976b28', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', '8cd04758-de43-541c-ad0b-1d2565d96e89', 5, 34, 'እርሱና የዳን ነገድ የሆነው የአሒሳሚክ ልጅ ኤልያብ ያስተምሩ ዘንድ በልባቸው አሳደረባቸው።'),
  ('67d96318-6488-56bf-aa81-2b10e2843fcd', 'a3e6f70b-88b9-50ee-a672-53ad92e266c5', '8cd04758-de43-541c-ad0b-1d2565d96e89', 6, 35, 'በአንጥረኛ፥ በብልህ ሠራተኛም፥ በሰማያዊና በሐምራዊ፥ በቀይም ግምጃ፥ በጥሩ በፍታም በሚሠራ ጠላፊ፥ በሸማኔም ሥራ የሚሠራውን፥ ማናቸውንም ሥራና በብልሃት የሚሠራውን ሁሉ ያደርጉ ዘንድ በእነርሱ ልብ ጥበብን ሞላ።'),
  ('310e2787-1817-5d80-a762-8b6dc4120235', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', '995bf92c-e739-5e22-a065-871735d7635f', 1, 1, '“ባስልኤልና ኤልያብ፥ ለመቅደስም ማገልገያ ሥራ ሁሉ ያደርጉ ዘንድ እንዲያውቁ እግዚአብሔር ጥበብንና ማስተዋልን የሰጣቸው በልባቸውም ጥበበኞች የሆኑ ሁሉ እግዚአብሔር ያዘዘውን ነገር ሁሉ አደረጉ።”'),
  ('a64892bf-0633-5163-a99b-4a2dab8521b9', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', '5ea626d7-7e3b-5052-a7bd-1d2b209217d8', 1, 2, 'ሙሴም ባስልኤልንና ኤልያብን፥ እግዚአብሔርም ዕውቀትንና ጥበብን በልቡናቸው ያሳደረባቸውንና ጥበብ ያላቸውን፥ ሥራውንም ለመሥራት ይቀርብ ዘንድ ልቡ ያስነሣውን ሁሉ ሥራውን ሠርተው ይፈጽሙ ዘንድ ጠራቸው።'),
  ('4b817730-dbe9-53b3-a1c5-fc6820b8a4cc', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', '5ea626d7-7e3b-5052-a7bd-1d2b209217d8', 2, 3, 'እነርሱም የእስራኤል ልጆች ለመቅደስ ማገልገያ ሥራ ያመጡትን ስጦታ ሁሉ ይሠሩ ዘንድ ከሙሴ ተቀበሉ። እነዚያም እንደ ፈቃዳቸው ማለዳ ማለዳ ስጦታውን ገና ወደ እርሱ ያመጡ ነበር።'),
  ('dbb2675a-c3a9-5ce3-ab2f-09593ec06a3b', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', '5ea626d7-7e3b-5052-a7bd-1d2b209217d8', 3, 4, 'እያንዳንዳቸው በሚሠሩት የመቅደሱን ሥራ የሚሠሩ ጠቢባን ሁሉ መጡ፤'),
  ('6e1fd702-4e8a-5c87-a9bb-0a3ba324365a', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', '5ea626d7-7e3b-5052-a7bd-1d2b209217d8', 4, 5, 'እነርሱም ለሙሴ፥ “እግዚአብሔር ይደረግ ዘንድ ላዘዘው ሥራ ከሚበቃ በላይ እጅግ የሚበልጥ ሕዝቡ አመጡ” ብለው ነገሩት።'),
  ('d58cb7b6-6105-559a-a080-0a5cd4f58345', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', '5ea626d7-7e3b-5052-a7bd-1d2b209217d8', 5, 6, 'ሙሴም አዘዘና፥ “ወንድ ወይም ሴት ለመቅደስ ስጦታ ከዚህ የበለጠ የሚያመጣ አይኑር” ብሎ በሰፈሩ ውስጥ አወጀ። ሕዝቡም እንዳያመጡ ተከለከሉ።'),
  ('c662f4dd-37a2-5a90-ae33-0bacad7a0575', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', '5ea626d7-7e3b-5052-a7bd-1d2b209217d8', 6, 7, 'ያመጡትም ነገር ሥራን ሁሉ ለመፈጸም በቅቶ ገና ይተርፍ ነበረና።'),
  ('725fce7b-bb43-56db-a3f9-2b0b2396fb3c', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 1, 8, 'በእነርሱም ዘንድ ያሉት፥ ሥራ ሲሠሩ የነበሩት በልባቸው ጥበበኞች ሁሉ ድንኳኑን ከዐሥር መጋረጃዎች ሠሩ፤ እነርሱንም ከተፈተለ ከጥሩ በፍታ፥ ከሰማያዊም፥ ከሐምራዊም፥ ከቀይም ግምጃ ሠሩ፤ በእነርሱም ላይ በጥልፍ ሥራ ኪሩቤልን አደረጉባቸው።'),
  ('88736d51-61fe-510a-a777-df4e2bce2aa9', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 2, 9, 'የእያንዳንዱ መጋረጃ ርዝመት ሃያ ስምንት ክንድ፥ ወርዱም አራት ክንድ ነበረ፤ የመጋረጃዎቹ ሁሉ ልክ ትክክል ነበረ።'),
  ('2d269c47-b111-5971-a1e3-9c9a3fff4ec3', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 3, 10, 'አምስቱንም መጋረጃዎች እርስ በርሳቸው አንዱን ከሌላው ጋር አጋጠሙ፤ አምስቱንም መጋረጃዎች እርስ በርሳቸው እንዲሁ አጋጠሙ።'),
  ('7fccdc27-104e-5187-af48-4e784a77495f', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 4, 11, 'ከሚጋጠሙትም መጋረጃዎች በአንደኛው መጋረጃ ዘርፍ ላይ የሰማያዊውን ግምጃ ቀለበቶች አደረጉ፤ ደግሞ ከተጋጠሙት ከሌሎቹ በአንደኛው መጋረጃ ዘርፍ ላይ እንዲሁ አደረጉ።'),
  ('1fef706b-8a93-52e4-a1ca-3413ae704e92', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 5, 12, 'አምሳ ቀለበቶችን በአንድ መጋረጃ አደረጉ፤ አምሳውንም ቀለበቶች በሁለተኛው መጋረጃ ዘርፍ አደረጉ፤ ቀለበቶቹ እርስ በርሳቸው ፊት ለፊት የሚተያዩ ነበሩ።'),
  ('3cb66187-c5d7-5a4e-aaab-d47a9b76566d', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 6, 13, 'አምሳም የወርቅ መያዣዎችን ሠሩ፤ መጋረጃዎችንም አንዱን ከሌላው በመያዣዎች አጋጠሙአቸው፤ አንድ ድንኳንም ሆነ።'),
  ('924a650a-e8d1-55b9-a5d1-155b15526a3f', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 7, 14, 'ከድንኳኑም በላይ የሚሆኑ መጋረጃዎችን ከፍየል ጠጕር አደረጉ፤ ዐሥራ አንድ መጋረጃዎችንም አደረጉ።'),
  ('20feb1c0-5926-5d7c-ad9e-3146ca8ad827', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 8, 15, 'እያንዳንዱም መጋረጃ ርዝመቱ ሠላሳ ክንድ፥ እያንዳንዱም መጋረጃ ወርዱ አራት ክንድ ነበረ፤ የእያንዳንዱም መጋረጃ መጠኑ ትክክል ነበረ።'),
  ('bd8f3ee5-948d-5fc2-ab9a-372ca55e5979', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 9, 16, 'አምስቱንም መጋረጃዎች እርስ በርሳቸው አንድ አደረጉ፤ ስድስቱንም መጋረጃዎች አንድ አድርገው አጋጠሙአቸው።'),
  ('4f6903c4-f6a9-55c7-ad9e-2a0ceee75830', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 10, 17, 'ከተጋጠሙትም መጋረጃዎች በአንደኛው መጋረጃ ጠርዝ ላይ አምሳ ቀለበቶችን አደረጉ፤ እንዲሁም በሁለተኛው መጋረጃ ጠርዝ በሚጋጠሙበት በኩል አምሳ ቀለበቶችን አደረጉ።'),
  ('5321b33b-65d0-5dbf-a2a2-f7f7fa064e02', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 11, 18, 'ድንኳኑም አንድ እንዲሆን ያጋጥሙት ዘንድ አምሳ የናስ መያዣዎችን ሠሩ።'),
  ('d7d9275f-377b-5729-a206-bdef18f2ea8c', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 12, 19, 'ለድንኳኑም መደረቢያ ከቀይ አውራ በግ የተለፋ ቍርበት፥ ከዚያም በላይ ሌላ መደረቢያ ከአቆስጣ ቍርበት አደረጉ።'),
  ('ced17c0d-9f9c-5586-a8b3-09ddc2ed3898', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 13, 20, 'ለድንኳኑም ከማይነቅዝ ዕንጨት የሚቆሙትን ሳንቆች አደረጉ።'),
  ('ed301d67-4ac6-5e3a-ab61-6eb8d7ae5b5d', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 14, 21, 'የሳንቃው ሁሉ ርዝመቱ ዐሥር ክንድ፥ ወርዱም አንድ ክንድ ተኩል ነበረ።'),
  ('393adfe7-baea-5973-a75c-9d8f616bff1c', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 15, 22, 'ለእያንዳንዱም ሳንቃ አንዱን በአንዱ ላይ የሚያያይዙ ሁለት ማጋጠሚያዎች ነበሩ፤ ለድንኳኑም ሳንቆች ሁሉ እንዲሁ አደረጉ።'),
  ('4e1fcb8f-b2e8-53f6-a52e-edd4d795791a', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 16, 23, 'ለድንኳኑም በደቡብ ወገን ሃያ ሳንቆችን አደረጉ፤'),
  ('8433efce-3203-5873-a80e-2e3bcb6d3c4d', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 17, 24, 'ከሃያውም ሳንቆች በታች አርባ የብር እግሮች አደረጉ፤ ከእያንዳንዱም ሳንቃ በታች ለሁለቱ ማጋጠሚያዎች ሁለት እግሮች ነበሩ።'),
  ('3295ef58-2887-560a-a41e-1a63d6896db7', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 18, 25, 'ለድንኳኑም ለሁለተኛው ወገን በሰሜን በኩል ሃያ ሳንቆች አደረጉ፤'),
  ('c25dfd00-9dc7-51fd-ac14-caf9f5d4f866', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 19, 26, 'ለእነርሱም አርባ የብር እግሮች፥ ከእያንዳንዱም ሳንቃ በታች ሁለት እግሮች አደረጉ።'),
  ('b10b50ef-1ae9-5660-aa82-7f0ac7b6d98f', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 20, 27, 'ለድንኳኑም በምዕራቡ ወገን በስተኋላ ስድስት ሳንቆች አደረጉ።'),
  ('2de38ffe-e30b-5b39-a6fd-8d13cf0a4f66', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 21, 28, 'ለድንኳኑም ለሁለቱ ማዕዘን በስተኋላ ሁለት ሳንቆች አደረጉ።'),
  ('e03df852-f460-57e0-a8aa-bd41cf7fcd00', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 22, 29, 'ከታችም እስከ ላይ እስከ አንደኛው ቀለበት ድረስ አንድ ሳንቃ ድርብ ነበረ፤ ለሁለቱም ማዕዘን እንዲሁ ሁለት ነበሩ።'),
  ('93eccc0e-128c-5d68-a751-e2e95689e8a3', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 23, 30, 'ስምንት ሳንቆችና ዐሥራ ስድስቱ የብር እግሮቻቸው፥ ከእያንዳንዱም ሳንቃ በታች ሁለት ሁለት እግሮች ነበሩ።'),
  ('df272942-8d81-5a04-af51-c6940ef6a5aa', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 24, 31, 'ከማይነቅዝ ዕንጨት በድንኳኑ በአንደኛው ወገን ላሉት ሳንቆች አምስት መወርወሪያዎችን፥'),
  ('057fd1a3-13ef-5efe-a8d9-1a8f25e2ef8f', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 25, 32, 'በድንኳኑም በሁለተኛው ወገን ላሉት ሳንቆች አምስት መወርወሪያዎችን፥ ከድንኳኑም በስተኋላ በምዕራቡ ወገን ላሉት ሳንቆች አምስት መወርወሪያዎችን አደረጉ።'),
  ('6618eea0-48fc-5a8c-a6e6-6e4b9c31e5a0', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 26, 33, 'መካከለኛውንም መወርወሪያ በሳንቆቹ መካከል ከዳር እስከ ዳር እንዲያልፍ አደረጉ።'),
  ('73c27d7e-caab-56ea-a6bc-a5125878e63a', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 27, 34, 'ሳንቆቹንም በወርቅ ለበጡአቸው፤ ቀለበቶቻቸውንም የመወርወሪያ ቤት እንዲሆኑላቸው ከወርቅ አደረጉ፤ መወርወሪያዎቹንም በወርቅ ለበጡአቸው።'),
  ('4cfd6bcf-b096-5e4b-aa3e-27a5806312f7', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 28, 35, 'መጋረጃውንም ከሰማያዊና ከሐምራዊ፥ ከቀይም ግምጃ፥ ከተፈተለም ከጥሩ በፍታ አደረጉ፤ ኪሩቤልንም በጥልፍ ሥራ በእርሱ ላይ አደረጉ።'),
  ('6301ce0e-c7cd-52c7-ae96-3c5c92748930', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 29, 36, 'ከማይነቅዝም ዕንጨት አራት ምሰሶዎች አደረጉለት፤በወርቅም ለበጡአቸው፤ ኵላቦቻቸውም የወርቅ ነበሩ፤ ለእነርሱም አራት የብር እግሮች አደረጉ።'),
  ('facd6968-b3c1-5f2d-ac23-86c5fcf20584', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 30, 37, 'ለድንኳኑም ደጃፍ ከሰማያዊና ከሐምራዊ፥ ከቀይም ግምጃ፥ ከተፈተለም ከጥሩ በፍታ በጥልፍ አሠራር የተሠራ መጋረጃ አደረጉ፤'),
  ('57e0241f-cc99-5c21-af1d-8883677b5a0d', 'f0b7f598-6bd5-5c6f-a4fd-e0569e9cf23c', 'b3c0093e-5f85-56f4-a86a-9b45cfb64bfd', 31, 38, 'አምስቱንም ምሰሶዎች፥ ኵላቦቻቸውንም አደረጉ፤ ጉልላቶቻቸውንና ዘንጎቻቸውንም በወርቅ ለበጡአቸው፤ አምስቱም እግሮቻቸው የናስ ነበሩ።'),
  ('996d60ba-f042-5e08-a4b8-6e2898e31d56', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '141536c3-a073-569f-abd4-5e07b57e93bd', 1, 1, 'ባስልኤልም ከማይነቅዝ ዕንጨት ታቦትን ሠራ፤ ርዝመቷ ሁለት ክንድ ተኩል፥ ወርድዋ አንድ ክንድ ተኩል፥ ቁመቷም አንድ ክንድ ተኩል ነበረ።'),
  ('7de5333d-9f09-5948-adc6-00cf092c7407', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '141536c3-a073-569f-abd4-5e07b57e93bd', 2, 2, 'በውስጥዋም፥ በውጭዋም በጥሩ ወርቅ ለበጣት፤ በዙሪያዋም የወርቅ አክሊል አደረገላት።'),
  ('12b38883-2820-5fb4-a5e7-ff7400cac28f', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '141536c3-a073-569f-abd4-5e07b57e93bd', 3, 3, 'አራት የወርቅ ቀለበቶችም አደረገላት፤ እነርሱንም በአራቱ እግሮችዋ ላይ አኖረ። በአንድ ወገን ሁለት ቀለበቶች፥ በሌላውም ወገን ሁለት ቀለበቶች ሆኑ።'),
  ('39ff3b6b-0483-5503-a0cb-b66cc88eaf2a', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '141536c3-a073-569f-abd4-5e07b57e93bd', 4, 4, 'መሎጊያዎችዋንም ከማይነቅዝ ዕንጨት ሠራ፤ በወርቅም ለበጣቸው።'),
  ('437c81f7-3af9-5d74-a098-923dd040a020', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '141536c3-a073-569f-abd4-5e07b57e93bd', 5, 5, 'ታቦቷንም ለመሸከም በታቦቷ አጠገብ ባሉት አራት ቀለበቶች መሎጊያዎችዋን አገባ።'),
  ('c1fe9f94-50bc-51ed-a063-424c8818ba64', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '141536c3-a073-569f-abd4-5e07b57e93bd', 6, 6, 'ከጥሩ ወርቅም ርዝመቱ ሁለት ክንድ ተኩል፥ ወርዱም አንድ ክንድ ተኩል የሆነ የስርየት መክደኛ ሠራላት።'),
  ('d834f4d1-4d86-5040-a358-3a0bc18bde8a', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '141536c3-a073-569f-abd4-5e07b57e93bd', 7, 7, 'ሁለት ኪሩቤልንም ከተቀጠቀጠ ወርቅ ሠራ፤ በስርየት መክደኛውም ላይ በሁለት ወገን አደረጋቸው።'),
  ('6a361c3b-6df2-5ec7-a410-2a0f8eacc8d1', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '141536c3-a073-569f-abd4-5e07b57e93bd', 8, 8, 'ከስርየት መክደኛውም ጋር አንዱን ኪሩብ በአንድ ወገን፥ ሁለተኛውንም ኪሩብ በሌላ ወገን በዚህና በዚያ ሁለቱን ኪሩቤል ከስርየት መክደኛው በላይ ሠራ፤'),
  ('f1c079b1-dce1-5620-aa54-c60c0e231c4a', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '141536c3-a073-569f-abd4-5e07b57e93bd', 9, 9, 'ኪሩቤልም ክንፎቻቸውን ወደ ላይ የዘረጉ ሆኑ፥ የስርየት መክደኛውንም በክንፎቻቸው ሸፈኑ፤ እርስ በርሳቸውም ተያዩ፤ የኪሩቤልም ፊቶቻቸው ወደ መክደኛው ተመለከቱ።'),
  ('e6588fbd-0789-5fcc-accb-c2df4bc2a500', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '03ebd318-7fe1-5453-ae12-5f942cd4a855', 1, 10, 'ርዝመቱ ሁለት ክንድ፥ ወርዱም አንድ ክንድ፥ ቁመቱም አንድ ክንድ ተኩል የሆነውን ገበታ ከማይነቅዝ ዕንጨት ሠራ።'),
  ('8ae4df1a-1474-5857-af0a-0e32b2edfceb', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '03ebd318-7fe1-5453-ae12-5f942cd4a855', 2, 11, 'በጥሩም ወርቅ ለበጠው፤ በዙሪያውም የወርቅ አክሊል አደረገለት።'),
  ('3191ad25-c4c2-5b2f-af7f-b95722e3b9ec', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '03ebd318-7fe1-5453-ae12-5f942cd4a855', 3, 12, 'በዙሪያውም አንድ ጋት የሚያህል ክፈፍ አደረገለት፤ የወርቅም አክሊል በክፈፉ ዙሪያ አደረገለት።'),
  ('5d10b13a-9ab0-5222-a7bc-75ebcd2f8984', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '03ebd318-7fe1-5453-ae12-5f942cd4a855', 4, 13, 'አራትም የወርቅ ቀለበቶች አደረገለት፤ ቀለበቶቹንም አራቱ እግሮቹ ባሉበት በአራቱ ማዕዘኖች አደረገ።'),
  ('9e5009fa-d9bd-52eb-a37a-174c4c7c04d0', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '03ebd318-7fe1-5453-ae12-5f942cd4a855', 5, 14, 'ገበታውንም ለመሸከም መሎጊያዎቹ እንዲሰኩባቸው ቀለበቶች በክፈፉ አቅራቢያ ነበሩ።'),
  ('1da78ccc-d20a-571a-ad94-eff0c06b2491', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '03ebd318-7fe1-5453-ae12-5f942cd4a855', 6, 15, 'ገበታውንም ይሸከሙባቸው ዘንድ መሎጊያዎቹን ከማይነቅዝ ዕንጨት ሠርቶ በወርቅ ለበጣቸው።'),
  ('884f54d7-7b8a-5209-a8fd-df96cfe3b678', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '03ebd318-7fe1-5453-ae12-5f942cd4a855', 7, 16, 'ለማፍሰሻም ይሆኑ ዘንድ በገበታው ላይ የሚኖሩትን ዕቃዎች፥ ወጭቶቹንና ጭልፋዎቹን፥ ጽዋዎቹንም፥ መቅጃዎቹንም ከጥሩ ወርቅ አደረጋቸው።'),
  ('0facf8a9-5da4-5c76-a685-fad0061b0739', '7923eaf7-262c-56f0-a2e0-d93d154d3958', 'b201ed0a-bdef-592b-ab90-a0ab54aec03f', 1, 17, 'መቅረዝዋንም ከጥሩ ወርቅ አደረገ፤ መቅረዝዋንም ከእግርዋና ከአገዳዋ ጋር በተቀረጸ ሥራ አደረገ፤ ጽዋዎችዋን፥ ጕብጕቦችዋን፥ አበቦችዋን ከዚያው በአንድነት አደረገ።'),
  ('37230eaa-77ab-5219-a6c9-05b25bfdeee0', '7923eaf7-262c-56f0-a2e0-d93d154d3958', 'b201ed0a-bdef-592b-ab90-a0ab54aec03f', 2, 18, 'በስተጎንዋ ስድስት ቅርንጫፎች ወጡላት፤ ሦስቱ የመቅረዝዋ ቅርንጫፎች በአንድ ወገን፥ ሦስቱም የመቅረዝዋ ቅርንጫፎች በሁለተኛው ወገን ወጡ።'),
  ('e7d24617-8792-5ce9-a8b3-dbd6b5851f31', '7923eaf7-262c-56f0-a2e0-d93d154d3958', 'b201ed0a-bdef-592b-ab90-a0ab54aec03f', 3, 19, 'በአንደኛው ቅርንጫፍ ጕብጕቡንና አበባውን፥ ሦስትም የለውዝ አበባ የሚመስሉትን ጽዋዎች፥ በሁለተኛውም ቅርንጫፍ ጕብጕቡንና አበባውን፥ ሦስትም የለውዝ አበባ የሚመስሉትን ጽዋዎች፥ እንዲሁም ከመቅረዝዋ ለወጡ ለስድስቱ ቅርንጫፎች አደረገ።'),
  ('1cf2bbfe-d7b6-5e59-a883-96c0fb7e05e6', '7923eaf7-262c-56f0-a2e0-d93d154d3958', 'b201ed0a-bdef-592b-ab90-a0ab54aec03f', 4, 20, 'በመቅረዝዋም ጕብጕቦችዋንና አበቦችዋን፥ አራትም የለውዝ አበባ የሚመስሉትን ጽዋዎች አደረገ።'),
  ('3db88800-263c-59e2-a4ac-34a7998d3e07', '7923eaf7-262c-56f0-a2e0-d93d154d3958', 'b201ed0a-bdef-592b-ab90-a0ab54aec03f', 5, 21, 'ከመቅረዝዋ ለወጡ ለስድስት ቅርንጫፎች ከሁለት ቅርንጫፎች በታች አንድ ሆኖ የተሠራ አንድ ጕብጕብ፥ ከሁለትም ቅርንጫፎች በታች አንድ ሆኖ የተሠራ አንድ ጕብጕብ፥ ደግሞ ከሁለት ቅርንጫፎች በታች አንድ ሆኖ የተሠራ አንድ ጕብጕብ ነበረ።'),
  ('05ec1e60-2fc4-5d35-a73d-a8889cd8a282', '7923eaf7-262c-56f0-a2e0-d93d154d3958', 'b201ed0a-bdef-592b-ab90-a0ab54aec03f', 6, 22, 'ጕብጕቦችዋና ቅርንጫፎችዋ ከእርሱ ጋር አንድ ነበሩ፤ ሁሉም አንድ ሆኖ ከተቀረጸ ከጥሩ ወርቅ ተሠርቶ ነበር።'),
  ('d2c85769-2f84-5708-a55d-817758d4f17a', '7923eaf7-262c-56f0-a2e0-d93d154d3958', 'b201ed0a-bdef-592b-ab90-a0ab54aec03f', 7, 23, 'ሰባቱንም መብራቶችዋን መኰስተሪያዎችዋንም፥ የኵስታሪ ማድረጊያዎችዋንም ከጥሩ ወርቅ ሠራ።'),
  ('301850d9-61ef-57b2-aa35-b0d4be313f03', '7923eaf7-262c-56f0-a2e0-d93d154d3958', 'b201ed0a-bdef-592b-ab90-a0ab54aec03f', 8, 24, 'መቅረዙንም፥ ዕቃውንም ሁሉ ከአንድ መክሊት ጥሩ ወርቅ አደረገ።'),
  ('d4a4ec8d-914d-50ea-a84b-d1e54b5a37c3', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '515cf785-ced6-5dcd-aa15-353b8477b586', 1, 25, 'የዕጣን መሠዊያንም ከማይነቅዝ ዕንጨት ሠራ፤ ርዝመቱ አንድ ክንድ፥ ስፋቱ አንድ ክንድ፤ አራት ማዕዘን ነበር፤ ከፍታውም ሁለት ክንድ ነበር፤ ቀንዶቹም ከእርሱ ጋር በአንድነት የተሠሩ ነበሩ።'),
  ('2b73823c-0b61-5b89-a20a-d5c8369f70f1', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '515cf785-ced6-5dcd-aa15-353b8477b586', 2, 26, 'ላይኛውንና የግድግዳውንም ዙሪያ፥ ቀንዶቹንም በጥሩ ወርቅ ለበጠው፤ በዙሪያውም የወርቅ ክፈፍ አደረገበት።'),
  ('f1a9b5df-93d9-5665-aae7-1093a7277346', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '515cf785-ced6-5dcd-aa15-353b8477b586', 3, 27, 'ከክፈፉም በታች ሁለት የወርቅ ቀለበቶች አደረገበት፤ በዚህና በዚያ በሁለቱም ጎን አደረጋቸው፤ ለመሸከምም የመሎጊያዎች መግቢያ ነበሩ።'),
  ('07d75e38-10a1-515e-a074-4b3deedd4c6b', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '515cf785-ced6-5dcd-aa15-353b8477b586', 4, 28, 'መሎጊያዎቹንም ከማይነቅዝ ዕንጨት አደረገ፤ በወርቅም ለበጣቸው።'),
  ('e618353c-2ddc-592e-a610-6af7003882e8', '7923eaf7-262c-56f0-a2e0-d93d154d3958', '515cf785-ced6-5dcd-aa15-353b8477b586', 5, 29, 'የተቀደሰውንም የቅብዐቱን ዘይት፥ ጥሩውንም የጣፋጭ ሽቱ ዕጣን በቀማሚ ብልሃት እንደ ተሠራ አደረገ።'),
  ('69c99fe4-d09e-57ab-a3e8-9930f246b50e', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '59ab98a3-2977-5a4c-a32c-61ee21c52570', 1, 1, 'ርዝመቱ አምስት ክንድ፥ ወርዱም አምስት ክንድ ለሚቃጠል መሥዋዕት የሚሆን መሠዊያን ከማይነቅዝ ዕንጨት አደረገ፤ አራት ማዕዘንም ነበረ፤ ከፍታውም ሦስት ክንድ ነበረ።'),
  ('bdcaf238-7251-5a80-a72f-d6b0d4b66dab', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '59ab98a3-2977-5a4c-a32c-61ee21c52570', 2, 2, 'ቀንዶቹንም በአራቱ ማዕዘን አደረገበት፤ ቀንዶቹም ከእርሱ ጋር ሥረ-ወጥ ነበሩ፤ በናስም ለበጠው።'),
  ('88cee653-52ef-5f17-a0b2-750fd21b7939', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '59ab98a3-2977-5a4c-a32c-61ee21c52570', 3, 3, 'የመሠዊያውንም ዕቃ ሁሉ፥ ምንቸቶቹንም፥ መጫሪያዎቹንም፥ ድስቶቹንም፥ ሜንጦዎቹንም፥ የእሳት ማንደጃዎቹንም አደረገ፤ ዕቃውንም ሁሉ ከናስ አደረገ።'),
  ('f14fc1cf-4f60-59a1-aadb-4b530eec6e42', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '59ab98a3-2977-5a4c-a32c-61ee21c52570', 4, 4, 'እንደ መረብ ሆኖም የተሠራ የናስ መከታ ለመሠዊያው አደረገ፤ መከታውም እስከ መሠዊያው እኩሌታ ይደርስ ዘንድ በመሠዊያው በሚዞረው በደረጃው ታች አደረገው።'),
  ('1ab53fa6-e49d-5507-aac7-b338bb82c149', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '59ab98a3-2977-5a4c-a32c-61ee21c52570', 5, 5, 'ለናሱም መከታ ለአራቱ ማዕዘን የመሎጊያዎች ስፍራ ይሆኑ ዘንድ አራት ቀለበቶች አደረገ።'),
  ('66c494fa-e08d-5451-adb6-f7b34f9f93be', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '59ab98a3-2977-5a4c-a32c-61ee21c52570', 6, 6, 'መሎጊያዎቹንም ከማይነቅዝ ዕንጨት ሠራ፤ በናስም ለበጣቸው።'),
  ('a3542920-6a55-5c99-a9d4-58acfcb5dffd', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '59ab98a3-2977-5a4c-a32c-61ee21c52570', 7, 7, 'ይሸከሙባቸውም ዘንድ በመሠዊያው ጎን ባሉት ቀለበቶች ውስጥ መሎጊያዎቹን አገባ፤ ከሳንቃዎቹም ሠርቶ ክፍት አደረገው።'),
  ('09bfc6a1-9d03-5622-a1c6-40aa5a022c02', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '7b6151f4-5fd3-5a24-a10e-445fb48c933f', 1, 8, 'የመታጠቢያውን ሰንና መቀመጫውንም በምስክሩ ድንኳን ደጃፍ ከሚያገለግሉ ከሴቶች መስተዋት ከናስ አደረገ።'),
  ('e00f8e16-f0fd-5e84-a91f-69cf700b1dcd', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 1, 9, 'ለድንኳኑም በደቡብ በኩል በስተቀኝ አደባባይ አደረገ፤ የአደባባዩ መጋረጃም ከተፈተለ ጥሩ በፍታ የተሠራ ርዝመቱ መቶ ክንድ ነበረ።'),
  ('29d5a7d8-b0a7-5282-aad7-35eadff0a860', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 2, 10, 'ሃያውንም ምሰሶዎቻቸውንና ሃያውን እግሮቻቸውን ከናስ አደረገ፤ የምሰሶዎቹንም ኵላቦችና ዘንጎች ከብር አደረገ።'),
  ('de5cdc32-82fe-56ac-ae84-7d05cd7c7db3', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 3, 11, 'በሰሜኑም ወገን መቶ ክንድ ርዝመት ያላቸውን መጋረጃዎች፥ ከናስም የተሠሩ ሃያ ምሰሶዎችንና ሃያ እግሮችን፥ ለምሰሶዎችም የብር ኵላቦችንና ዘንጎችን አደረገ።'),
  ('9826f3e9-2fa7-5191-a8ff-ab479ee53ddb', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 4, 12, 'በምዕራብም ወገን አምሳ ክንድ ርዝመት ያላቸውን መጋረጃዎች፥ ዐሥሩንም ምሰሶዎች፥ ዐሥሩንም የናስ እግሮች፥ ለምሰሶዎቹም የብር ኵላቦችንና ዘንጎችን አደረገ።'),
  ('8c71cb89-85a5-576d-a10f-a5511566149c', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 5, 13, 'በምሥራቅም ወገን አምሳ ክንድ ርዝመት ያላቸውን መጋረጃዎችን አደረገ።'),
  ('f183aa44-2831-5468-a77a-c390fecc753a', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 6, 14, 'በአዜብ በኩል የመጋረጃዎች ርዝመት ዐሥራ አምስት ክንድ፥ ምሰሶዎቹም ሦስት፥ እግሮቹም ሦስት ነበሩ።'),
  ('de7a7f31-9a1d-5d25-aaa3-18c15ebcd4ab', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 7, 15, 'እንዲሁም በሁለተኛው ወገን በአደባባዩ ደጅ በዚህና በዚያ ዐሥራ አምስት ክንድ ርዝመት ያላቸው መጋረጃዎች፥ ሦስትም ምሰሶዎች፥ ሦስትም እግሮች ነበሩ።'),
  ('a705c939-141e-53e1-ad8c-990009656dc8', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 8, 16, 'በአደባባዩ ዙሪያ ያሉ መጋረጃዎች ሁሉ ከተፈተለ ከጥሩ በፍታ ተሠርተው ነበር።'),
  ('9fb3ec3b-b5e0-52e1-a9c7-482d47769347', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 9, 17, 'የምሰሶዎቹም እግሮች የናስ፥ የምሰሶዎቹም ኵላቦችና ዘንጎች የብር ነበሩ፤ የምሰሶዎቹም ጕልላቶች በብር ተለብጠው ነበር፤ በአደባባዩ ላሉ ምሰሶዎች ሁሉ የብር ዘንጎች ነበሩአቸው።'),
  ('e5351912-3ffa-5de5-ad32-237ac147951b', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 10, 18, 'የአደባባዩም ደጅ መጋረጃ ከሰማያዊ፥ ከሐምራዊም፥ ከቀይም ግምጃ ፥ ከጥሩም በፍታ በጥልፍ አሠራር የተሠራ ነበረ፤ ርዝመቱ ሃያ ክንድ ነበረ፤ ቁመቱም እንደ አደባባዩ መጋረጃዎች አምስት ክንድ ነበረ፤'),
  ('1359b202-7549-5f83-a1a9-14d2dc3e79c4', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 11, 19, 'ከናስ የተሠሩ ምሰሶዎቹም አራት፥ እግሮቹም አራት ነበሩ፤ ኵላቦቹም የብር ነበሩ፤ ጕልላቶቹና ዘንጎቹም በብር ተለብጠው ነበር።'),
  ('d3715522-9c04-55a9-a219-01980080721f', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', 'a4ee0a76-43cf-5502-a383-674eb6f1a4a3', 12, 20, 'የድንኳኑም ካስማዎች፥ በዙሪያውም ያሉ የአደባባዩ ካስማዎች የናስ ነበሩ።'),
  ('614e9a01-357a-55a5-a51d-f945277a5e52', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '4aa81f7d-e037-53c6-aa07-d98329f0da29', 1, 21, 'በካህኑ በአሮን ልጅ በይታምር እጅ የሌዋውያን ተልእኮ ይሆን ዘንድ ሙሴ ከእግዚአብሔር እንደታዘዘ የምስክሩ ድንኳን ሥርዐት ይህ ነው።'),
  ('d9867421-e1dd-56f7-a0e3-4fbc626fd7c5', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '4aa81f7d-e037-53c6-aa07-d98329f0da29', 2, 22, 'ከይሁዳ ነገድም የሆነ የሆር የልጅ ልጅ፥ የኡሪ ልጅ ባስልኤል እግዚአብሔር ለሙሴ እንዳዘዘው ሁሉ አደረገ።'),
  ('3dcf715a-aa81-507a-a491-865d1524bb54', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '4aa81f7d-e037-53c6-aa07-d98329f0da29', 3, 23, 'ከእርሱም ጋር ከዳን ነገድ የሆነ የአሒሳሚክ ልጅ ኤልያብ ነበረ፤ እርሱም በሰማያዊ፥ በሐምራዊ፥ በቀይም ግምጃ፥ በጥሩ በፍታ የሽመና ሥራ ይሠራ ዘንድ የቅርጽ፥ የሽመናና የጥልፍ ሥራ አለቃ ነበረ።'),
  ('6b53ee29-fa77-5ce5-ab76-78d4689a2204', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '4aa81f7d-e037-53c6-aa07-d98329f0da29', 4, 24, 'የተሰጠው ወርቅ ሁሉ፥ ለድንኳኑ ሥራ ሁሉ የተደረገው ወርቅ፥ እንደ መቅደሱ ሰቅል ሚዛን ሃያ ዘጠኝ መክሊት ሰባት መቶ ሠሳሳ ሰቅል ነበረ።'),
  ('1bf92a6c-a8cc-5ddb-a8dc-d44c7ce5a19f', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '4aa81f7d-e037-53c6-aa07-d98329f0da29', 5, 25, 'በማኅበሩም ከሚቈጠሩት የተገኘ ብር፥ እንደ መቅደሱ ሰቅል ሚዛን፥ መቶ መክሊትና አንድ ሺህ ሰባት መቶ ከሰባ አምስት ሰቅል ነበረ።'),
  ('4297a51f-b9b7-5ab3-a310-7639689946a3', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '4aa81f7d-e037-53c6-aa07-d98329f0da29', 6, 26, 'እያንዳንዱም ሰው አንድ አንድ ዲድርክም አዋጣ፤ አንድ ዲድርክም እንደ መቅደሱ ሰቅል ሚዛን የሰቅል ግማሽ ነው፤ ይህም የተዋጣው ከሃያ ዓመት ጀምሮ ከዚያም በላይ ከተቈጠሩ ሁሉ ስድስት መቶ ሦስት ሺህ አምስት መቶ አምሳ ሰዎች ነበረ።'),
  ('6d8dd49e-07e2-52db-a4f9-b32e23495704', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '4aa81f7d-e037-53c6-aa07-d98329f0da29', 7, 27, 'መቶውም የብር መክሊት ለድንኳኑ ምሰሶዎች እግሮችና ለመጋረጃው ምሰሶዎች እግሮች ተደረገ፤ መቶውም መክሊት ለመቶ እግሮች፤ ለአንድ እግርም አንድ መክሊት ሆነ።'),
  ('8f33e632-65e2-5aa6-a1ef-59bbe619cbfe', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '4aa81f7d-e037-53c6-aa07-d98329f0da29', 8, 28, 'ከሺህ ሰባት መቶ ሰባ አምስት ሰቅል የምሰሶዎቹን ኵላቦችና ዘንጎች አደረገ፤ የምሰሶዎቹንም ጕልላቶች ለበጠ።'),
  ('01a46ccb-5d22-5332-acf2-1c48821489bd', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '4aa81f7d-e037-53c6-aa07-d98329f0da29', 9, 29, 'የተሰጠውም ናስ አራት መቶ ሰባ መክሊትና ሁለት ሺህ አራት መቶ ሰቅል ነበረ።'),
  ('d9895edf-87dd-57f9-afe3-b5b1d8d9980f', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '4aa81f7d-e037-53c6-aa07-d98329f0da29', 10, 30, 'ከእርሱም የምስክሩን ድንኳን ደጃፍ እግሮች፥ የናሱንም መሠዊያ፥ ለእርሱም የሆነውን የናሱን መከታ፥ የመሠዊያውንም ዕቃ ሁሉ፥'),
  ('72eef9d8-2c32-5275-a7c2-702d5e18fc81', 'c15d9826-1acd-5fd0-adf5-e707c7d61cb1', '4aa81f7d-e037-53c6-aa07-d98329f0da29', 11, 31, 'በአደባባዩ ዙሪያ ያሉትን እግሮች፥ የአደባባዩንም ደጃፍ እግሮች፥ የድንኳኑንም ካስማዎች ሁሉ፥ በአደባባዩ ዙሪያም ያሉትን ካስማዎች ሁሉ አደረገ።'),
  ('1b24f3c0-477e-5dd7-aea0-c1a4795abc94', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '7a947ecf-538f-5d58-a810-88cdb1d91bed', 1, 1, 'የቀረውም የመባ ወርቅ በእግዚአብሔር ፊት ይሠሩበት ዘንድ ንዋየ ቅድሳት ሆኖ ተሠራ። ከሰማያዊ፥ ከሐምራዊም ከቀይ ግምጃም ለመቅደሱ አገልግሎት ልብሶችን ሠሩ፤ እንዲሁም እግዚአብሔር ሙሴን እንዳዘዘው ለአሮን የተቀደሰውን ልብስ ሠሩ።'),
  ('c7b6c582-188b-5057-a66e-3ea4c5955872', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '7a947ecf-538f-5d58-a810-88cdb1d91bed', 2, 2, 'ልብሰ እንግድዓውንም ከወርቅ፥ ከሰማያዊ፥ ከሐምራዊም፥ ከቀይ ግምጃም፥ ከተፈተለ ከጥሩ በፍታም ሠሩ።'),
  ('dcbd1b84-0475-5203-a0f2-0451746622b7', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '7a947ecf-538f-5d58-a810-88cdb1d91bed', 3, 3, 'ወርቁንም ቀጥቅጠው እንደ ቅጠል ስስ አደረጉት፤ እንደ ፈትልም ቈረጡት። ብልህ ሠራተኛም እንደሚሠራ ሰማያዊ፥ ሐምራዊም፥ ቀይ ግምጃም፥ የተፈተለም ጥሩ በፍታ፥ ከእርሱ ጠለፉ።'),
  ('d182a4d7-7394-5d6b-a270-c9239a3a9490', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '7a947ecf-538f-5d58-a810-88cdb1d91bed', 4, 4, 'ሁለቱ ወገን እንዲጋጠሙ፥ በሁለት ጫንቃዎች ላይ የሚጋጠም ልብሰ መትከፍ ሠሩ።'),
  ('3bfcfd61-6544-5c11-ad3d-3433593cec58', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '7a947ecf-538f-5d58-a810-88cdb1d91bed', 5, 5, 'እግዚአብሔር ሙሴን እንዳዘዘው እርስዋን ከወርቅ፥ ከሰማያዊና ከሐምራዊ፥ ከቀይ ግምጃም፥ ከተፈተለ ከጥሩ በፍታም እንደ ሠሩ የልብሰ መትከፉን ቋድ ሠሩ።'),
  ('fc722dda-a5cd-5e0a-aacf-f22afe71635d', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '7a947ecf-538f-5d58-a810-88cdb1d91bed', 6, 6, 'በወርቅ ፈርጥ የተያዙ የመረግድ ድንጋዮች ሠርተው እንደ ማኅተም ቅርጽ የእስራኤልን ልጆች ስም ቀረጹባቸው።'),
  ('54995a19-567f-5d72-a89a-1c9e7c975963', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '7a947ecf-538f-5d58-a810-88cdb1d91bed', 7, 7, 'ለእስራኤልም ልጆች የመታሰቢያ ድንጋዮች ይሆኑ ዘንድ እግዚአብሔር ሙሴን እንዳዘዘው፥ በልብሰ መትከፉ ጫንቃዎች ላይ አደረጓቸው።'),
  ('93f01a49-fad3-5ab2-a6a5-7707e3ea1db2', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 1, 8, 'ልብሰ እንግድዓውን ብልህ ሠራተኛ እንደሚሠራ፥ እንደ ልብሰ መትከፉ አሠራር ከወርቅና ከሰማያዊ፥ ከሐምራዊም፥ ከቀይም ግምጃ፥ ከተፈትለም ከጥሩ በፍታ አደረጉ።'),
  ('8986d715-5f02-548d-a7a0-41c7a11c3792', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 2, 9, 'አራት ማዕዘንም ነበረ፤ ልብሰ እንግድዓውም ድርብ ነበር፤ ርዝመቱ ስንዝር፥ ወርዱም ስንዝር፥ ድርብም ነበረ።'),
  ('b0678297-cafb-549f-acf0-2d3919d2b68e', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 3, 10, 'ዕንቍዎቹንም በአራት ተራ አደረጉበት፤ በፊተኛውም ተራ ሰርድዮን፥ ቶጳዝዮን፥ መረግድ፤'),
  ('f9c11885-c81f-5801-a29f-4e0fc6cb43d8', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 4, 11, 'በሁለተኛውም ተራ በሉር፥ ሰንፔር፥ ኢያሰጲድ፤'),
  ('3248445f-ab2b-5bc3-ad8e-63122aa6c2bc', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 5, 12, 'በሦስተኛውም ተራ ለግርዮን፥አካጥስ፥ አሜቴስጢኖስ፤'),
  ('1549e218-9f2c-5c68-a2ac-329414d9f893', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 6, 13, 'በአራተኛውም ተራ ወርቃማ ድንጋይ፥ ቢረሌ፥ ሶም፤ ዙሪያውም በወርቅ ፈርጥ ተደረገ።'),
  ('c6fe508f-0e62-5333-ad7b-ce6b99e4c726', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 7, 14, 'የዕንቍዎችም ድንጋዮች እንደ ዐሥራ ሁለቱ እንደ እስራኤል ልጆች ስሞች ነበሩ፤ በየስማቸውም ማተሚያ እንደሚቀረጽ ተቀረጹ፤ ስለ ዐሥራ ሁለቱም ነገዶች ነበሩ።'),
  ('fc0d4c21-2498-5cf3-ab99-96f257201a49', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 8, 15, 'ለልብሰ እንግድዓውም የተጐነጐኑትን ድሪዎች እንደ ገመድ አድርገው ከጥሩ ወርቅ ሠሩ።'),
  ('043e358f-daa7-5432-ae2c-ec99d6c68e33', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 9, 16, 'ሁለትም የወርቅ ፈርጦች፥ ሁለትም የወርቅ ቀለበቶች ሠሩ፤ ሁለቱንም የወርቅ ቀለበቶች በልብሰ እንግድዓው በሁለቱ ወገን አደረጉ።'),
  ('02803669-bf86-5ae2-a477-f15c1a27d9c9', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 10, 17, 'ሁለቱንም የተጐነጐኑትን የወርቅ ድሪዎች በልብሰ እንግድዓው በሁለቱ ወገኖች ወዳሉት ወደ ሁለቱ ቀለበቶች አገቡ።'),
  ('b4281412-bf91-5ca5-ab3f-0319cdda8c9d', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 11, 18, 'የሁለቱንም ድሪዎች ጫፎች በሁለቱ ፈርጦች ውስጥ አግብተው በልብሰ መትከፉ ጫንቃዎች ላይ ፊት ለፊት አደረጓቸው።'),
  ('aa28370a-729f-50b8-af5c-22073fef25e1', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 12, 19, 'ሁለቱንም የወርቅ ቀለበቶች ሠሩ፤ እነርሱንም ከልብሰ መትከፉ ፊት ለፊት ባለው በልብሰ እንግድዓው በሁለቱ ጫፎች ላይ አደረጓቸው።'),
  ('68232d5b-1cb3-5309-a337-3de632686f97', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 13, 20, 'ደግሞም ሁለት የወርቅ ቀለበቶች ሠሩ፤ በመደረቢያው ፊት፥ ከጫንቃዎች በታች፥ በብልሃት ከተጠለፈ ከመደረቢያው ቋድ በላይ፥ በመያዣው አጠገብ አደረጓቸው።'),
  ('22326a4f-15ca-5d22-a3e6-e8ea3301d966', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '1d5663dd-37ab-5721-aa32-f2423a7f5e9a', 14, 21, 'ልብሰ እንግድዓው በብልሃት ከተጠለፈው ከመደረቢያው ቋድ በላይ እንዲሆን፥ ከመደረቢያው እንዳይለይ ልብሰ እንግድዓውን ከቀለበቶቹ ጋር ወደ መደረቢያው ቀለበቶች በሰማያዊ ፈትል አሰሩት።'),
  ('98f59a89-572a-50c0-a9ea-8b0b0ee4038f', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '0b84c1fe-b220-51b1-a58d-27ca8653f69c', 1, 22, 'እግዚአብሔርም ሙሴን እንዳዘዘው፥ የመደረቢያውን ቀሚስ ሞላውን በሸማኔ ሥራ ሰማያዊ አድርጎ ሠራው።'),
  ('4203a1eb-2aa7-56c4-a3cd-403e7b501ed4', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '0b84c1fe-b220-51b1-a58d-27ca8653f69c', 2, 23, 'በቀሚሱም መካከል አንገትጌ ነበረ፤ እንዳይቀደድም በአንገትጌው ዙሪያ በአንድነት የተያያዘ ጥልፍ ነበረ።'),
  ('d12bd024-bb19-57f5-ac34-af8eec5aed14', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '0b84c1fe-b220-51b1-a58d-27ca8653f69c', 3, 24, 'በቀሚሱም ታችኛ ዘርፍ ከሰማያዊ፥ ከሐምራዊም፥ ከቀይ ግምጃም፥ ከተፈተለ በፍታም የአበቡ ሮማኖችን አደረጉ።'),
  ('154a4ff8-dc18-55a4-ae5d-1906c5673669', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '0b84c1fe-b220-51b1-a58d-27ca8653f69c', 4, 25, 'ከጥሩ ወርቅም ሻኵራዎችን ሠሩ፤ ሻኵራዎቹንም ከሮማኖች መካከል በቀሚሱ ዘርፍ ዙሪያ አደረጉ።'),
  ('52119dea-996d-5f3a-a2a1-b82801580e1f', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '0b84c1fe-b220-51b1-a58d-27ca8653f69c', 5, 26, 'በቀሚሱ ዘርፍ ዙሪያ ሻኵራንና ሮማንን፥ ሻኩራንና ሮማንን እግዚአብሔር ሙሴን እንዳዘዘው ለማገልገል አደረጉ።'),
  ('b2d9cbcb-1ef3-5d99-a815-148e827aabe4', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '0b84c1fe-b220-51b1-a58d-27ca8653f69c', 6, 27, 'እንደ ሸማኔ ሥራ ከጥሩ በፍታ ለአሮንና ለልጆቹ እጀ ጠባቦችን፥ ከጥሩ በፍታም አክሊልን፥'),
  ('6d597a64-6a76-503b-acc7-0459652e7005', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '0b84c1fe-b220-51b1-a58d-27ca8653f69c', 7, 28, 'ከጥሩ በፍታም መልካሞቹን ቆቦች፥ ከተፈተለ ከጥሩ በፍታም የእግር ሱሪዎችን፥'),
  ('c1c59185-8b02-5c3d-abce-ef7ce519bb3c', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '0b84c1fe-b220-51b1-a58d-27ca8653f69c', 8, 29, 'ከተፈተለም ከጥሩ በፍታ፥ ከሰማያዊም፥ ከሐምራዊም፥ ከቀይም ግምጃ በጥልፍ አሠራር የተሠራ መታጠቂያውን እግዚአብሔር ሙሴን እንዳዘዘው አደረጉ።'),
  ('ed650df6-8516-5242-a98d-69877ccd7125', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '0b84c1fe-b220-51b1-a58d-27ca8653f69c', 9, 30, 'ከጥሩ ወርቅ የተለየ የወርቅ ቅጠል ሠሩ፤ በእርሱም እንደ ማኅተም ቅርጽ አድርገው፥ “ቅድስና ለእግዚአብሔር” የሚል ጻፉበት።'),
  ('5d92b128-962b-5a0a-a1a5-c82598ce3da4', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '0b84c1fe-b220-51b1-a58d-27ca8653f69c', 10, 31, 'እግዚአብሔር ሙሴን እንዳዘዘው፥ በአክሊሉ ላይ ያንጠለጥሉት ዘንድ ሰማያዊውን ፈትል አሰሩበት።'),
  ('27037a99-0072-502e-a77d-2c54dce5f0aa', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 1, 32, 'እንዲሁም የምስክሩ ድንኳን ሥራ ሁሉ ተፈጸመ። እግዚአብሔርም ሙሴን እንዳዘዘው ሁሉ የእስራኤል ልጆች አደረጉ፤ እንዲሁ አደረጉ።'),
  ('db1cbdd7-afe9-59c9-aaeb-5972d42376a3', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 2, 33, 'ድንኳኑንም፥ መደረቢያውንም፥ ዕቃውንም ሁሉ ወደ ሙሴ አመጡ፤ መያዣዎቹን፥ ሳንቆቹን፥ መወርወሪያዎቹን፥ ምሰሶዎቹን፥ እግሮቹንም፤'),
  ('f839c87a-7364-5339-a04e-97cc8983b387', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 3, 34, 'ከቀይ አውራ በግ ቍርበትም የተሠራ መደረቢያ፥ ከአቆስጣ ቁርበትም የተሠራ መደረቢያ፥ የሚሸፍነውንም መጋረጃ፥'),
  ('9254939a-e04c-57f4-a92d-a5e4623c493c', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 4, 35, 'የምስክሩንም ታቦት፥ መሎጊያዎቹንም፥ የስርየት መክደኛውንም፤'),
  ('126eaa4c-a928-5b9b-a609-4695e6604086', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 5, 36, 'ገበታውንም፥ ዕቃውንም ሁሉ፥ ኅብስተ ገጹንም፤'),
  ('03855c99-0a26-52d4-aa9f-c69c614b529d', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 6, 37, 'ጥሩውንም መቅረዝ፥ መብራቶቹንም፥ በተራ የሚሆኑትንም ቀንዲሎች፥ ዕቃውንም ሁሉ፥ የመብራቱንም ዘይት፤'),
  ('62f1b01a-3742-5ca1-a1dd-ef2e3f6b1f89', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 7, 38, 'የወርቁንም መሠዊያ፥ የቅብዐቱንም ዘይት፥ ጣፋጩንም ዕጣን፥ የድንኳኑንም ደጃፍ መጋረጃ፤'),
  ('c89796bf-8260-5903-a27f-a5112f43c1a9', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 8, 39, 'የናሱንም መሠዊያ፥ የናሱንም መከታ፥ መሎጊያዎቹንም፥ ዕቃውንም ሁሉ፥ የመታጠቢያውን ሰንም፥ መቀመጫውንም፤'),
  ('bf708455-487e-5481-ab59-bef24fa3bda2', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 9, 40, 'የአደባባዩንም መጋረጆች፥ ምሰሶዎቹንም፥ እግሮቹንም፥ የአደባባዩንም ደጃፍ መጋረጃ፥ አውታሮቹንም፥ ካስማዎቹንም፥ ለምስክሩ ድንኳን ማገልገያ የሚሆኑትን ዕቃዎች ሁሉ፤'),
  ('40708a0d-6a13-501f-a05b-e84422c094e1', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 10, 41, 'በመቅደስ ውስጥ ለማገልገል በብልሃት የተሠሩትን ልብሶች፥ በክህነትም ያገለግሉበት ዘንድ የተቀደሱትን የካህኑን የአሮንን ልብሶች፥ የልጆቹንም ልብሶች አመጡ።'),
  ('6320c24e-180e-5e34-a2a7-ec714a04aeab', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 11, 42, 'እግዚአብሔር ሙሴን እንዳዘዘ ሁሉ እንዲሁ የእስራኤል ልጆች ሥራውን ሁሉ ሠሩ።'),
  ('a9eb6911-86d3-5133-a13e-29043513d248', 'bffe0412-fd81-5096-a631-ae1fb0ef8e61', '6b0d88ee-2b77-5ae9-a226-f5e868e1bf69', 12, 43, 'ሙሴም ሥራውን ሁሉ አየ፤ እነሆም፥ አድርገውት ነበር፤ እግዚአብሔር እንዳዘዘው እንዲሁ አድርገውት ነበር፤ ሙሴም ባረካቸው።'),
  ('28065c01-4b53-54ac-aab8-93d47eddd718', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ሲል ተናገረው፦'),
  ('b6393904-aa90-5db5-ac56-58899b0f8adc', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 2, 2, '“በመጀመሪያው ወር በፊተኛው ቀን የምስክሩን ድንኳን ትተክላለህ።'),
  ('1896883a-cfee-5f90-a0f6-4e7d506d79dc', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 3, 3, 'በእርሱም ውስጥ የምስክሩን ታቦት ታኖራለህ፤ ታቦቱንም በመጋረጃ ትጋርዳለህ።'),
  ('ca5ac4da-8675-59b0-a3f5-e21460e0c4a0', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 4, 4, 'ገበታውንም ታገባለህ፤ በሥርዐቱም ታሰናዳዋለህ፤ መቅረዙንም አግብተህ ቀንዲሎቹን ትለኵሳለህ።'),
  ('4d0efc41-4046-502e-ac9a-3a506d5db8a2', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 5, 5, 'የወርቁንም ማዕጠንት በምስክሩ ታቦት ፊት ታኖራለህ፤ በድንኳኑም ደጃፍ ፊት መጋረጃውን ትጋርዳለህ።'),
  ('32afe5bd-6faa-5f56-ada5-69afbadc407e', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 6, 6, 'ለሚቃጠል መሥዋዕት የሚሆነውንም መሠዊያ በምስክሩ ድንኳን ደጅ ፊት ታኖረዋለህ።'),
  ('ef2823e4-729f-517d-aae6-34772effd817', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 7, 7, 'የመታጠቢያውን ሰንም በምስክሩ ድንኳንና በመሠዊያው መካከል ታኖረዋለህ፤ በውስጡም ውኃ ትጨምርበታለህ።'),
  ('434c4c2c-f51f-5270-a1e6-ce0bf5fd0495', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 8, 8, 'በዙሪያውም አደባባዩን ትሠራለህ፤ የአደባባዩንም ደጃፍ መጋረጃ ትዘረጋለህ።'),
  ('7797f340-d970-5162-a668-926ffe0eca84', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 9, 9, 'የቅብዐቱንም ዘይት ወስደህ ድንኳኑን፥ በውስጥዋም ያለውን ሁሉ ትቀባለህ፤ እርስዋንም ዕቃዋንም ሁሉ ትቀድሳለህ፤ ቅድስትም ትሆናለች።'),
  ('8d774fae-00bc-57d8-a3b6-5dba75f8d975', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 10, 10, 'ለሚቃጠል መሥዋዕትም የሚሆነውን መሠዊያ፥ ዕቃውንም ሁሉ ትቀባዋለህ፤ መሠዊያውንም ትቀድሳለህ፤ መሠዊያውም ቅዱሰ ቅዱሳን ይሆናል።'),
  ('9e449f2c-70b9-514e-ae17-c2e8de6db1b4', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 11, 11, 'የመታጠቢያውን ሰንና መቀመጫውንም ቀብተህ ትቀድሳለህ።'),
  ('d04c567d-5984-5574-a0e0-7a19f9c90564', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 12, 12, 'አሮንንና ልጆቹንም ወደ ምስክሩ ድንኳን ደጃፍ አቅርበህ በውኃ ታጥባቸዋለህ።'),
  ('97eede46-6499-5c9f-a53e-4b5c61118112', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 13, 13, 'ለአሮንም የተቀደሰውን ልብስ ታለብሰዋለህ፤ ትቀባዋለህ፤ ትቀድሰውማለህ፤ ካህንም ይሆነኛል።'),
  ('d41b3207-6ba8-5005-adc3-1ffed7685652', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 14, 14, 'ልጆቹንም ታቀርባቸዋለህ፤ ቀሚሳቸውንም ታለብሳቸዋለህ፤'),
  ('e0ce3e89-fa7b-5f3f-a34e-eb646004ddbc', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 15, 15, 'አባታቸውን እንደ ቀባህ ትቀባቸዋለህ፤ ካህናትም ይሆኑኛል። ይህም ለልጅ ልጃቸው ለዘለዓለም የክህነት ቅብዐት ይሆንላቸዋል።”'),
  ('5c49f824-2adc-5863-aa0e-7d785560850b', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 16, 16, 'ሙሴም እግዚአብሔር ያዘዘውን ሁሉ አደረገ፤ እንዲሁም አደረገ።'),
  ('bff45a34-5554-55f5-afdf-ac500a15bd62', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 17, 17, 'እንዲህም ሆነ፤ ከግብፅ ምድር ከወጡ በኋላ በሁለተኛው ዓመት በፊተኛው ወር በመጀመሪያው ቀን ድንኳንዋ ተተከለች።'),
  ('382d4348-5b60-52e9-a35d-0809c0cfb3f0', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 18, 18, 'ሙሴም ድንኳንዋን ተከለ፤ እግሮችዋንም አኖረ፤ ሳንቆችዋንም አቆመ፤ መወርወሪያዎችዋንም አደረገባቸው፤ ምሰሶዎችዋንም አቆመ።'),
  ('03b079d3-abcf-5d67-aace-6511d4857fb7', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 19, 19, 'እግዚአብሔርም ሙሴን እንዳዘዘው መጋረጃውን በድንኳኑ ላይ ዘረጋው፤ የድንኳኑንም መደረቢያ በላዩ አደረገበት።'),
  ('b759af71-0640-53e8-af07-c179acfd62ff', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 20, 20, 'ሙሴም ጽላቱን ወስዶ በታቦቱ ውስጥ አኖረው፤ መሎጊያዎቹንም በታቦቱ ቀለበቶች ውስጥ አደረገ፤ የስርየት መክደኛውንም በታቦቱ ላይ አኖረው።'),
  ('f83db737-ad68-50eb-a26f-8f6565dac5af', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 21, 21, 'ታቦቷንም ወደ ድንኳኑ አገባ፥ የሚሸፍነውንም መጋረጃ አድርጎ የምስክሩን ታቦት ሸፈነ።'),
  ('8530ab97-b7c4-506b-a5d6-b157c2b48f26', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 22, 22, 'እግዚአብሔርም ሙሴን እንዳዘዘው ገበታውን በምስክሩ ድንኳን ውስጥ፥ ከመጋረጃው ውጭ በድንኳኑ በመስዕ በኩል አኖረው፤'),
  ('2c5a1521-6efd-5b44-af92-de89b4816daa', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 23, 23, 'ኅብስተ ገጹንም በላዩ በእግዚአብሔር ፊት አሰናዳ።'),
  ('ffe34e37-fe85-5566-a839-af8fd22a0729', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 24, 24, 'እግዚአብሔርም ሙሴን እንዳዘዘው መቅረዙን በምስክሩ ድንኳን ውስጥ፥ በገበታውም ፊት ለፊት፥ በድንኳኑ በአዜብ በኩል አኖረ፤'),
  ('535b9c0c-67d3-5f85-a028-2a444ccbd2ea', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 25, 25, 'ቀንዲሎቹንም በእግዚአብሔር ፊት አበራ።'),
  ('b4a0e606-7fa0-5d32-ae14-948244afe6f1', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 26, 26, 'እግዚአብሔርም ሙሴን እንዳዘዘው የወርቁን ማዕጠንት በምስክሩ ድንኳን ውስጥ በመጋረጃው ፊት አኖረ።'),
  ('f864237c-08fe-51a6-a805-82de7674e428', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 27, 27, 'የአዘጋጀውንም ዕጣን ዐጠነበት።'),
  ('96e6e249-09a5-5eff-a3ec-8cc7c4f1a92f', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 28, 28, 'ሙሴም እግዚአብሔር እንደ አዘዘው በድንኳኑ ደጅ ፊት መጋረጃውን ዘረጋ።'),
  ('417407e0-b9fd-5b6d-a778-108773347e47', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 29, 29, 'ለሚቃጠል መሥዋዕት የሚሆነውን መሠዊያም በምስክሩ ድንኳን ደጅ አኖረ፤ እግዚአብሔርም ሙሴን እንዳዘዘው በላዩ መሥዋዕቱንና ቍርባኑን አቀረበ።'),
  ('0725fa44-7b78-540c-ad08-a3dde3dd0d50', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 30, 30, 'የመታጠቢያውንም ሰን በምስክሩ ድንኳንና በመሠዊያው መካከል አኖረ፤ ለመታጠቢያም ውኃን ጨመረበት።'),
  ('9a911ef9-0f91-5073-a272-264e9bc881ba', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 31, 31, 'በእርሱም ሙሴና አሮን፥ ልጆቹም እጆቻቸውንና እግሮቻቸውን ታጠቡ፤'),
  ('704c94c0-c8e7-5e7c-af7d-c59ffe7e84f6', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 32, 32, 'እግዚአብሔርም ሙሴን እንዳዘዘው ወደ ምስክሩ ድንኳን በገቡ ጊዜ፥ ወደ መሠዊያውም በቀረቡ ጊዜ ይታጠቡ ነበር።'),
  ('21098ac3-c5ea-51c1-ab8c-2891e8fb3cde', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', 'f757a620-0ceb-55d9-a15c-a894c4cb5999', 33, 33, 'በድንኳኑና በመሠዊያውም ዙሪያ አደባባዩን ሠራ፤ የአደባባዩንም ደጃፍ መጋረጃ ዘረጋ። እንዲሁም ሙሴ ሥራውን ፈጸመ።'),
  ('8b0f1965-bc8f-5802-a90e-3cf2a88bf54c', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', '0af437a0-b396-5aef-aabc-e1182ae688f9', 1, 34, 'ደመናውም የምስክሩን ድንኳን ከደነ፤ ድንኳንዋም የእግዚአብሔርን ክብር ተሞላች።'),
  ('a033f8af-bfc5-5ae8-a986-06701b18cf1b', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', '0af437a0-b396-5aef-aabc-e1182ae688f9', 2, 35, 'ደመናውም በላዩ ስለነበር ድንኳኑም የእግዚአብሔርን ክብር ስለ ተሞላ ሙሴ ወደ ምስክሩ ድንኳን ይገባ ዘንድ አልቻለም።'),
  ('44d2dbdd-6d0f-5383-a85c-360b8bc9e334', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', '0af437a0-b396-5aef-aabc-e1182ae688f9', 3, 36, 'ደመናውም ከድንኳኑ በተነሣ ጊዜ የእስራኤል ልጆች በየነገዳቸው ይጓዙ ነበር።'),
  ('4cdc18bf-a323-5bb2-acb0-0258500b430c', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', '0af437a0-b396-5aef-aabc-e1182ae688f9', 4, 37, 'ደመናው ካልተነሣ ግን ደመናው እስከሚነሣበት ቀን ድረስ አይጓዙም ነበር።'),
  ('a39902e6-50cf-58b9-ade5-122206ff6aa7', '7266ebed-3e72-5fe1-ab1a-9626eb479fbf', '0af437a0-b396-5aef-aabc-e1182ae688f9', 5, 38, 'ደመና በቀን በድንኳኑ ላይ ነበርና፥ እሳቱም በሚጓዙበት ሁሉ በሌሊት በእስራኤል ሁሉ ፊት በእርስዋ ላይ ነበርና።'),
  ('11328703-fd14-562e-ad99-e8a1c68a6e44', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 1, 1, 'እግዚአብሔርም ከምስክሩ ድንኳን ውስጥ ሙሴን ጠርቶ እንዲህ ሲል ተናገረው፦'),
  ('7981cb4e-01e9-547a-a5de-28e88640ecb7', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ ከእናንተ ለእግዚአብሔር መባ የሚያቀርብ ሰው ቢኖር መባችሁን ከእንስሳ ወገን ከላሞች ወይም ከበጎች ታቀርባላችሁ።'),
  ('efd8c100-093c-51ea-abbf-8c7556bb493e', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 3, 3, '“መባውም የሚቃጠል መሥዋዕት ከላሞች መንጋ ቢሆን፥ ነውር የሌለበትን ተባቱን ያቀርባል፤ በእግዚአብሔር ፊት ተቀባይነት እንዲኖረው በምስክሩ ድንኳን ደጃፍ ፊት ያቀርበዋል።'),
  ('1802ac62-f7b6-566b-a97c-489efc296fed', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 4, 4, 'ተቀባይነት ይኖረው ዘንድ ስለ እርሱም ያስተሰርይለት ዘንድ እጁን በሚቃጠለው መሥዋዕት ራስ ላይ ይጭናል።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('60d9198a-3565-5b6d-a6be-e2e0cbcbde09', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 5, 5, 'በሬውንም በእግዚአብሔር ፊት ያርደዋል፤ የአሮንም ልጆች ካህናቱ ደሙን ያቀርባሉ፤ ደሙንም በምስክሩ ድንኳን ደጃፍ ፊት ባለው በመሠዊያው ላይ በዙሪያው ይረጩታል።'),
  ('48df9dcb-f0e3-524c-a232-de77f3a0d730', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 6, 6, 'የሚቃጠለውንም መሥዋዕት ይገፍፈዋል፤ በየብልቱም ይቈርጠዋል።'),
  ('88f4b631-d749-5d38-a101-95b572ed8f8a', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 7, 7, 'የካህኑም የአሮን ልጆች በመሠዊያው ላይ እሳት ያነድዳሉ፤ በእሳቱም ላይ ዕንጨት ይረበርባሉ፤'),
  ('d1d40c8f-4adc-5cef-aefc-4ff0d734c464', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 8, 8, 'የአሮንም ልጆች ካህናቱ የተቈረጡትን ብልቶች፥ ራሱንም፥ ስቡንም በመሠዊያው ላይ በእሳቱ ላይ ባለው በዕንጨቱ ላይ ይረበርቡታል።'),
  ('9f6246a8-d1cf-5cc0-a871-97feb660af4f', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 9, 9, 'የሆድ ዕቃውንና እግሮቹን ግን በውኃ ያጥባሉ፤ ካህኑም ሁሉን የሚቃጠል መሥዋዕት በእግዚአብሔር ዘንድ በጎ መዓዛ እንዲሆን በመሠዊያው ላይ ያቀርበዋል።'),
  ('bb7af2b7-fbb7-597e-a4bc-d676e2143d43', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 10, 10, '“ነገር ግን ለእግዚአብሔር የሚቀርበው መባ ከበጎች ወይም ከፍየሎች ቢሆን፥ ለሚቃጠል መሥዋዕት ነውር የሌለበትን ተባቱን፥ የፊት እግሮቹንና ራሱን ጨምሮ ያቀርበዋል።'),
  ('f533ee63-23ba-5bd4-aa07-58665cc01431', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 11, 11, 'በመሠዊያውም አጠገብ በመስዕ በኩል በእግዚአብሔር ፊት ያርዱታል፤ የአሮንም ልጆች ካህናቱ ደሙን በመሠዊያው ላይ በዙሪያው ይረጩታል።'),
  ('64e49383-0cd8-5e52-a216-713a6a8bacb2', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 12, 12, 'በየብልቱም ራሱን፥ ስቡንም ይቈርጡታል፤ ካህናቱም በመሠዊያው ላይ በእሳቱ ላይ ባለው በዕንጨቱ ላይ ይረበርቡታል፤'),
  ('f5073075-6afe-5126-a7f8-4f9cd6be788c', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 13, 13, 'የሆድ ዕቃውንና እግሮቹን ግን በውኃ ያጥቡታል። ካህኑም ሁሉን በመሠዊያው ላይ ለቍርባን ያቀርበዋል፤ የሚቃጠል መሥዋዕት በእግዚአብሔር ዘንድ በጎ መዓዛ ያለው ቍርባን ነው።'),
  ('499a22d3-9148-568e-a553-5ecdb854cdb3', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 14, 14, '“ለእግዚአብሔርም የሚያቀርበው ቍርባን የሚቃጠል መሥዋዕት ከዎፎች ቢሆን፥ ቍርባኑን ከዋኖስ ወይም ከርግብ ያቀርባል።'),
  ('9a7b65aa-01c1-5406-ac8f-ee25167eedc4', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 15, 15, 'ካህኑም ወደ መሠዊያው ያቀርበዋል፤ አንገቱንም ይቈርጠዋል፥ በመሠዊያውም ላይ ያኖረዋል። ደሙንም በመሠዊያው አጠገብ ያንጠፈጥፈዋል፤'),
  ('3ef9a2f9-9b9b-5a93-af4b-9bf6a4fda3c4', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 16, 16, 'የሆድ ዕቃውንም ከላባዎች ጋር ለይቶ በመሠዊያው አጠገብ በምሥራቅ በኩል በአመዱ ስፍራ ይጥለዋል፤'),
  ('ccfdd169-4e81-544c-a2f3-4d9e2d0afbc5', '94c7fdf7-9496-53b7-a0fa-247a908abfab', '56978d1a-1f90-5e9c-ac55-44fa73a3e9c4', 17, 17, 'ከክንፎቹም ይሰብረዋል፤ ነገር ግን አይለየውም። ካህኑም በመሠዊያው ላይ በእሳቱ ላይ ባለው በዕንጨቱ ላይ ያኖረዋል፤ መሥዋዕቱ ለእግዚአብሔር በጎ መዓዛ ያለው ቍርባን ነው።'),
  ('ac7c1315-6423-52b5-a414-a169b60389d7', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 1, 1, '“ማናቸውም ሰው ቍርባን ለእግዚአብሔር መሥዋዕት እንዲሆን ቢያቀርብ፥ ቍርባኑ ከመልካም ስንዴ ዱቄት ይሁን፤ ዘይትም ያፈስስበታል፤ ነጭ ዕጣንም ይጨምርበታል፤ ይህም መሥዋዕት ነው።'),
  ('2bfcb7ba-c893-5837-ab4c-b159178afc6b', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 2, 2, 'ወደ ካህኑ ወደ አሮን ልጆች ያመጣዋል፤ ከመልካም ስንዴ ዱቄቱና ከዘይቱም አንድ እፍኝ ሙሉና ነጩንም ዕጣን ሁሉ ወስዶ ካህኑ የእሳት ቍርባን ለእግዚአብሔር በጎ መዓዛ እንዲሆን ለመታሰቢያ በመሠዊያው ላይ ያቃጥለዋል።'),
  ('6f6b5e4f-aad7-5c22-ab38-3b207e53f819', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 3, 3, 'ከመሥዋዕቱም የተረፈው ለአሮንና ለልጆቹ ይሆናል፤ ይህም ከእግዚአብሔር መሥዋዕት የተረፈ ቅዱሰ ቅዱሳን ነው።'),
  ('5b9722dd-24dd-5804-a824-0b3f65af18aa', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 4, 4, '“በእቶን የተጋገረውን ቍርባን ስታቀርብ፥ በዘይት የተለወሰ የመልካም ስንዴ ዱቄት፥ የቂጣ እንጎቻ ወይም በዘይት የተቀባ ስስ ቂጣ ይሁን።'),
  ('834d4896-f1f4-54ad-a72c-243da306aa76', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 5, 5, 'ቍርባንህም በምጣድ የተጋገረ ቍርባን ቢሆን፥ በዘይት የተለወሰ የመልካም ስንዴ ዱቄት ቂጣ ይሁን።'),
  ('078bbd3a-9551-5fb6-acfc-01c8c4a5ba8c', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 6, 6, 'ቈርሰህም ዘይት ታፈስስበታለህ፤ የእግዚአብሔር መሥዋዕት ነው።'),
  ('0e76d3f0-4aeb-5b5f-a798-f284603e7ff3', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 7, 7, 'ቍርባንህም በመቀቀያ የበሰለ ቍርባን ቢሆን፥ ዘይት የገባበት ከመልካም ስንዴ ዱቄት የተደረገ ይሁን።'),
  ('b22c8782-6725-577a-a4d2-a853263183f1', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 8, 8, 'ከዚህም ያደረግኸውን መሥዋዕት ወደ እግዚአብሔር ታመጣለህ፤ ወደ ካህኑም ታቀርበዋለህ፤ ካህኑም ወደ መሠዊያው ያቀርበዋል።'),
  ('1ff13510-c082-5e79-a3eb-9a74cc741127', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 9, 9, 'ካህኑም ከቍርባኑ መታሰቢያውን ይወስዳል፤ በመሠዊያውም ላይ ይጨምረዋል። ለእግዚአብሔር በጎ መዓዛ ያለው የሚቃጠል ቍርባን ነው።'),
  ('756f9067-ef53-5696-a58c-2db35beb2388', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 10, 10, 'ከመሥዋዕቱም የተረፈው ለአሮንና ለልጆቹ ይሆናል፤ ይህም ከእግዚአብሔር መሥዋዕት የተረፈ ቅዱሰ ቅዱሳን ነው።'),
  ('9c267675-8fb4-5e65-aafa-0e674864bccc', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 11, 11, '“ለእግዚአብሔር የምታቀርቡት የእህል ቍርባን ሁሉ እርሾ አይሁንበት፤ እርሾ ያለበት ነገር፥ ማርም ለእግዚአብሔር ቍርባን ይሆን ዘንድ አታቀርቡምና።'),
  ('678c1b14-388b-5dd8-a0ad-c8098e683548', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 12, 12, 'እነዚህንም ዐሥራት አድርጋችሁ ለእግዚአብሔር ታቀርባላችሁ፤ ነገር ግን ለእግዚአብሔር ለበጎ መዓዛ በመሠዊያው ላይ አይቀርቡም።'),
  ('12af2455-9ba9-5197-aea5-d753ba075de5', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 13, 13, 'የምታቀርቡት ቍርባን ሁሉ በጨው ይጣፈጣል፤ የአምላክህም ቃል ኪዳን ጨው ከቍርባንህ አይጕደል፤ በቍርባናችሁ ሁሉ ላይ ጨው ትጨምራላችሁ።'),
  ('6c5660d9-d04a-50ff-af8b-a016f3ff29ec', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 14, 14, '“ከመጀመሪያው እህልህ መሥዋዕት ለእግዚአብሔር ብታቀርብ በእሳት የተጠበሰና የተፈተገ የእህል እሸት ታቀርባለህ።'),
  ('8fdd12ce-9339-5f42-a8ee-cfdcf5cc8c4f', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 15, 15, 'ዘይትም ታፈስስበታለህ፤ ዕጣንም ትጨምርበታለህ፤ የእህል ቍርባን ነው።'),
  ('34087e28-c021-55dd-abbc-a78a4421e1b2', '84d92d39-09aa-517f-a89f-df7f85f93cb1', '58cc7225-e997-5a47-a631-6e44e9eb8a4f', 16, 16, 'ካህኑም ከተፈተገው እህል፥ ከዘይቱም ወስዶ ከዕጣኑ ጋር መታሰቢያውን ያቀርባል፤ ይህም ለእግዚአብሔር የሚቃጠል መሥዋዕት ነው።'),
  ('860e01b6-2331-57bf-afdf-fd90c1729964', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 1, 1, '“ለእግዚአብሔር የሚቀርበው ቍርባን የደኅንነት መሥዋዕት ቢሆን፥ ከላሞች መንጋ ተባት ወይም እንስት ቢያቀርብ፥ ነውር የሌለበትን በእግዚአብሔር ፊት ያቅርብ።'),
  ('c0dd868d-d381-5154-a669-cd853132f781', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 2, 2, 'እጁንም ለቍርባን በቀረበው ራስ ላይ ይጭናል፤ በምስክሩ ድንኳን ደጃፍ አጠገብ ያርደዋል፤ የአሮንም ልጆች ካህናቱ ደሙን በሚቃጠለው መሥዋዕት፥ በመሠዊያው ላይ በዙሪያው ይረጩታል።'),
  ('6cd25041-c621-58a0-a8fc-dd89f5c962ab', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 3, 3, 'ከደኅንነቱም መሥዋዕት ለእግዚአብሔር የእሳት ቍርባን አድርገው ያቀርባሉ፤ የሆድ ዕቃውንም የሚሸፍነውን ስብ፥ በሆድ ዕቃውም ላይ ያለውን ስብ ሁሉ፥'),
  ('13540b05-c3b7-52c4-a5d0-b4dac26a0223', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 4, 4, 'ሁለቱንም ኵላሊቶች፥ በእነርሱም ላይና በጎድኑ አጠገብ ያለውን ስብ፥ በጉበቱም ላይ ያለውን መረብ ከኵላሊቶቹ ጋር ያመጣሉ።'),
  ('62280eda-50bb-595b-abe0-f2a610c8fa45', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 5, 5, 'የአሮንም ልጆች ከሚቃጠል መሥዋዕት ጋር በመሠዊያው ላይ በእሳቱ ላይ ባለው በዕንጨቱ ላይ ያቀርቡታል፤ የእሳት ቍርባን ለእግዚአብሔር በጎ መዓዛ ነው።'),
  ('5f7925e8-20dd-543d-a880-0a257713ec73', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 6, 6, '“ለእግዚአብሔርም ለደኅንነት መሥዋዕት የሚያቀርበው ቍርባኑ ከበጎች ተባት ወይም እንስት ቢሆን፥ ነውር የሌለበትን ያቀርባል።'),
  ('b99514f0-717f-592f-a941-82e59733745c', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 7, 7, 'ለቍርባኑ የበግ ጠቦትን ቢያቀርብ በእግዚአብሔር ፊት ያቀርበዋል፤'),
  ('3ec1c4fb-ecb8-5124-ac71-6fdd530e2b57', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 8, 8, 'እጁንም ለቍርባን በቀረበው ራስ ላይ ይጭናል በምስክሩ ድንኳን ደጃፍ ያርደዋል፤ ካህናቱም የአሮን ልጆች ደሙን በመሠዊያው ላይ በዙሪያው ይረጩታል።'),
  ('d816cdbf-93f9-5f53-a5ac-f4df6b5b3742', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 9, 9, 'ከደኅንነቱም መሥዋዕት ለእግዚአብሔር የሚቃጠል መሥዋዕት አድርጎ ያቀርባል፤ ስቡን፥ እስከ ጀርባውም ድረስ የተቈረጠ ሙሉ ላቱን፥ የሆድ ዕቃውንም የሚሸፍነውን ስብ፥ በሆድ ዕቃውም ላይ ያለውን ስብ ሁሉ፥'),
  ('d4df5eec-4aac-544f-a53e-10ced17376e9', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 10, 10, 'ሁለቱንም ኵላሊቶች፥ በእነርሱም ላይና በጎድኑም አጠገብ ያለውን ስብ፥ በጉበቱም ላይ ያለውን መረብ ከኵላሊቶቹ ጋር ይወስዳል።'),
  ('cb0c3a07-e3d5-5f90-a60e-6fb6c6aabc14', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 11, 11, 'ካህኑም በመሠዊያው ላይ ያቀርበዋል፤ በጎ መዓዛ ያለው ለእግዚአብሔር የሚቃጠል መሥዋዕት ነው።'),
  ('e6d695e1-5d93-5236-a3d5-df8f4219d1c1', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 12, 12, '“ቍርባኑም ፍየል ቢሆን በእግዚአብሔር ፊት ያቀርበዋል፤'),
  ('b60464a7-b93e-5ebe-a4f8-e43c51c5ccad', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 13, 13, 'እጁንም በራሱ ላይ ይጭንበታል፤ በምስክሩ ድንኳን ደጃፍም ያርደዋል፤ የአሮንም ልጆች ደሙን በመሠዊያው ላይ በዙሪያው ይረጩታል።'),
  ('166612df-faf3-5b0b-a290-19d69e694a08', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 14, 14, 'ከእርሱም ለእግዚአብሔር የእሳት ቍርባን አድርጎ ያቀርበዋል፤ ሆድ ዕቃውን የሚሸፍነውን ስብ፥ በሆድ ዕቃውም ላይ ያለውን ስብ ሁሉ፥'),
  ('7006f530-d6f0-5fca-ad7c-5160103f30e1', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 15, 15, 'ሁለቱንም ኵላሊቶች፥ በእነርሱም ላይና በጎድኑ አጠገብ ያለውን ስብ፥ በጉበቱም ላይ ያለውን መረብ ከኵላሊቶቹ ጋር ይወስዳል።'),
  ('24abfa78-b811-5433-af43-910e13812113', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 16, 16, 'ካህኑም በመሠዊያው ላይ ያቀርበዋል፤ ለእግዚአብሔር በጎ መዓዛ ያለው የሚቃጠል መሥዋዕት ነው። ስቡ ሁሉ ለእግዚአብሔር ነው።'),
  ('ac714c3c-e962-5d5f-a340-0442cabd4830', '0841cea0-e09f-5c0c-a869-ad8dd894ed6a', '91a9514e-9b66-5292-ab5b-60b8b243d1bf', 17, 17, 'ስብና ደም እንዳትበሉ በምትኖሩበት ሁሉ ለልጅ ልጃችሁ የዘለዓለም ሥርዐት ነው።”'),
  ('f0b5215d-3496-5d55-ac79-c095c55ff824', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ሲል ተናገረው፦'),
  ('5ffe625e-4475-50ab-a6bb-e0e43d530bca', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ ማናቸውም ሰው ሳያውቅ በእግዚአብሔር ፊት ኀጢአት ቢሠራ፥ እግዚአብሔርም፦ አትሥሩ ካላቸው ትእዛዛት አንዲቱን ቢተላለፍ፥'),
  ('a639e7b9-d800-5336-a0aa-ca0ea0b0ebc8', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 3, 3, 'የተቀባውም ሊቀ ካህናት በሕዝቡ ላይ በደል እንዲቈጠርባቸው ኀጢአት ቢሠራ፥ ስለ ሠራው ስለ ኀጢአቱ ከመንጋው ነውር የሌለበትን ወይፈን ለእግዚአብሔር ለኀጢአት መሥዋዕት ያቀርበዋል።'),
  ('48049967-631c-562f-a193-37f67f9484b4', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 4, 4, 'ወይፈኑንም ወደ ምስክሩ ድንኳን ደጃፍ በእግዚአብሔር ፊት ያመጣዋል፤ እጁንም በወይፈኑ ራስ ላይ ይጭነዋል፤ ወይፈኑንም በእግዚአብሔር ፊት ያርደዋል።'),
  ('2a459f43-a728-573e-a0c2-75034bd34c71', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 5, 5, 'ተቀብቶ የተሾመው ካህን ከወይፈኑ ደም በእጁ ወስዶ ወደ ምስክሩ ድንኳን ያመጣዋል፤'),
  ('11ed30a4-b922-5ccf-a2c8-7a3a370c7ef2', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 6, 6, 'ካህኑም ጣቱን በደሙ ውስጥ ነክሮ በእግዚአብሔር ፊት በመቅደሱ መጋረጃ ፊት ደሙን ሰባት ጊዜ ይረጨዋል።'),
  ('ab3c2975-cd7d-50cf-ab1b-cfb35c75057a', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 7, 7, 'ካህኑም በምስክሩ ድንኳን ውስጥ በእግዚአብሔር ፊት ያለው ጣፋጭ ዕጣን በሚታጠንበት መሠዊያ ቀንዶች ላይ ከደሙ ያደርጋል፤ የወይፈኑንም ደም ሁሉ በምስክሩ ድንኳን ደጅ ባለው ለሚቃጠል መሥዋዕት በሚሆነው መሠዊያ በታች ያፈስሰዋል።'),
  ('2f5a6e7f-0017-54be-a89c-5b295e8ec93f', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 8, 8, 'ለኀጢአትም መሥዋዕት ከሚታረደው ወይፈን ስብን ሁሉ ይወስዳል፤ ሆድ ዕቃውንም የሚሸፍነውን ስብ፥ በሆድ ዕቃውም ላይ ያለውን ስብ ሁሉ፥'),
  ('ea6e6366-d72f-5124-a683-80b95b7f4d88', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 9, 9, 'ሁለቱንም ኵላሊቶች፥ በእነርሱም ላይና በጎድኑ አጠገብ ያለውን ስብ፥ በጉበቱም ላይ ያለውን መረብ ከኵላሊቶች ጋር፥'),
  ('56d56f0d-82ed-5ca2-acce-1d3b60809478', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 10, 10, 'ለደኅንነት መሥዋዕት ከታረደው ወይፈን እንደ ተወሰደው ይወስዳል፤ ካህኑም ለሚቃጠል መሥዋዕት በሚሆነው መሠዊያ ላይ ያቀርበዋል።'),
  ('814e4495-b3ab-5304-a250-b86954b381ca', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 11, 11, 'የወይፈኑን ቍርበት፥ ሥጋውንም ሁሉ፥ ራሱንም፥ እግሮቹንም፥ ሆድ ዕቃውንም፥ ፈርሱንም፤'),
  ('af651b5f-fb25-511c-aed3-e68402f585a9', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 12, 12, 'ወይፈኑን ሁሉ ከሰፈሩ ወደ ውጭ አመድ ወደሚፈስስበት ወደ ንጹሕ ስፍራ ይወስዱታል፤ በዕንጨትም ላይ በእሳት ያቃጥሉታል፤ አመድ በሚፈስስበት ስፍራ ይቃጠላል።'),
  ('9c5e95fa-190d-5233-a11b-e618b534510c', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 13, 13, '“የእስራኤል ማኅበር ሁሉ ቢስቱ፥ ነገሩም ከማኅበሩ ዐይን ቢሸሸግ፥ እግዚአብሔርም አትሥሩ ካላቸው ትእዛዛት አንዲቱን ቢተላለፉ፤'),
  ('849de105-b887-56c6-aaa8-91bd4bdaec36', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 14, 14, 'ከዚህም በኋላ፥ የሠሩት ኀጢአት ቢታወቃቸውና ንስሓ ቢገቡ ማኅበሩ ስለ ኀጢአት መሥዋዕት ወይፈንን ያቀርባሉ፤ ወደ ምስክሩም ድንኳን ፊት ያመጡታል።'),
  ('640741d2-6e8d-5728-a784-f534a63e847a', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 15, 15, 'የማኅበሩም ሽማግሌዎች እጆቻቸውን በወይፈኑ ራስ ላይ በእግዚአብሔር ፊት ይጭናሉ፤ ወይፈኑንም በእግዚአብሔር ፊት ያርዱታል።'),
  ('616c46b1-5c2e-586d-a7aa-4d4ca02e4820', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 16, 16, 'የተቀባውም ካህን ከወይፈኑ ደም ወደ ምስክሩ ድንኳን ያመጣል፤'),
  ('b3706633-d588-53d8-a870-0d98d27226be', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 17, 17, 'ካህኑም ጣቱን በደሙ ውስጥ ነክሮ በእግዚአብሔር ፊት በመቅደሱ መጋረጃ ፊት ለፊት ሰባት ጊዜ ይረጨዋል።'),
  ('e4e6db8d-d396-57c2-a143-8b2cc9487d75', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 18, 18, 'በምስክሩ ድንኳን ውስጥ በእግዚአብሔር ፊት ባለው በዕጣን መሠዊያው ቀንዶች ላይ ከደሙ ያደርጋል፤ ደሙንም ሁሉ በምስክሩ ድንኳን ደጅ ባለው ለሚቃጠል መሥዋዕት በሚሆነው መሠዊያ በታች ያፈስሰዋል።'),
  ('ef152937-9ca6-5c62-a6b5-1f30eb3af51d', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 19, 19, 'ስቡንም ሁሉ ከእርሱ ወስዶ በመሠዊያው ላይ ያቀርበዋል።'),
  ('b8aaa91d-bb0f-5dd9-aa59-d957f1e373e7', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 20, 20, 'እንዲህም በወይፈኑ ያደርጋል፤ ስለ ኀጢአት መሥዋዕት በታረደው ወይፈን እንደ አደረገ እንዲሁ በዚህ ያደርጋል፤ ካህኑም ኀጢአታቸውን ያስተሰርያል፤ ኀጢአቸውም ይሰረይላቸዋል።'),
  ('efd03271-d2de-5a6f-adb4-3788285750ed', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 21, 21, 'ወይፈኑንም ሁሉ ከሰፈሩ ወደ ውጭ ይወስዱታል፤ የፊተኛውንም ወይፈን እንዳቃጠሉ ያቃጥሉታል፤ የማኅበሩ የኀጢአት መሥዋዕት ነውና።'),
  ('f8515dd4-77f8-5659-a3de-bbea260c06dc', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 22, 22, '“መኰንንም ኀጢአትን ቢሠራ፥ ሳያውቅም እግዚአብሔር አምላኩ፦ አትሥራ ያለውን ትእዛዝ ቢተላለፍ፥ እንዲህም ቢበድል፥'),
  ('53f21162-f57b-58a8-a36e-576e44911e14', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 23, 23, 'የሠራው ኀጢአት ቢታወቀውና ንስሓ ቢገባ፥ ከፍየሎች ነውር የሌለበትን ተባት ፍየል ለቍርባኑ ያቀርባል፤'),
  ('08b35a88-fa6e-583d-aec5-23e191cbefe6', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 24, 24, 'በፍየሉም ራስ ላይ እጁን ይጭናል፤ የሚቃጠልም መሥዋዕት በሚታረድበት ስፍራ በእግዚአብሔር ፊት ያርደዋል፤ እርሱ የኀጢአት መሥዋዕት ነውና።'),
  ('7df3f5cd-03b1-5ccd-a009-c65e3005f084', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 25, 25, 'ካህኑም ከኀጢአት መሥዋዕት ደም በጣቱ ወስዶ ለሚቃጠል መሥዋዕት በሚሆነው መሠዊያ ቀንዶች ላይ ያደርገዋል፤ ደሙንም ሁሉ ለሚቃጠል መሥዋዕት ከሚሆነው መሠዊያ በታች ያፈስሰዋል።'),
  ('5f1e9016-fe6b-54f4-a27c-283774644472', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 26, 26, 'ስቡንም ሁሉ እንደ ደኅንነት መሥዋዕት ስብ፥ በመሠዊያው ላይ ይጨምረዋል። ካህኑም ኀጢአቱን ያስተሰርይለታል፤ ኀጢአቱም ይቅር ይባልለታል።'),
  ('5506772e-fed2-5bad-a3ef-2eba52fd730c', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 27, 27, '“ከሀገሩም ሕዝብ አንድ ሰው ኀጢአትን ሳያውቅ ቢሠራ፥ እግዚአብሔርም፦ አትሥራ ያለውን ትእዛዝ ቢተላለፍ፥ ቢበድልም፥'),
  ('3b2e46d4-5822-52a4-a697-0a4f72fd472c', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 28, 28, 'ለእርሱም የሠራው ኀጢአት ቢታወቀውና ንስሓ ቢገባ፥ ስለ ሠራው ኀጢአት ነውር የሌለባትን እንስት ፍየል ለቍርባኑ ያመጣል።'),
  ('ceb88a70-8e84-5f45-a329-08758235ee79', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 29, 29, 'እጁንም በኀጢአት መሥዋዕት ራስ ላይ ይጭናል፤ ለሚቃጠልም መሥዋዕት እንስሳትን በሚያርዱበት ስፍራ የኀጢአት መሥዋዕት ፍየልዋን ያርዳታል።'),
  ('c0f6326c-7fb6-5ba0-a779-6726f66fc2f5', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 30, 30, 'ካህኑም ከደምዋ በጣቱ ወስዶ ለሚቃጠል መሥዋዕት በሚሆነው መሠዊያ ቀንዶች ላይ ያደርገዋል፤ ደሙንም ሁሉ ከመሠዊያው በታች ያፈስሰዋል።'),
  ('5043300f-7def-5a66-a398-da14729caa43', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 31, 31, 'ስቡም ሁሉ ከደኅንነት መሥዋዕት ላይ እንደሚወሰድ፥ ስብዋን ሁሉ ይወስዳል፤ ካህኑም ለእግዚአብሔር በጎ መዓዛ እንዲሆን በመሠዊያው ላይ ይጨምረዋል፤ ካህኑም ስለ እርሱ ያስተሰርያል፤ ኀጢአቱም ይሰረይለታል።'),
  ('9f83860b-d896-5763-a521-acf4fffb9b21', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 32, 32, '“ስለ ኀጢአትም መሥዋዕት የበግ ጠቦት ቢያቀርብ፥ ነውር የሌለባትን እንስት ያመጣል።'),
  ('e7c2e30e-70b2-5503-a436-a424cfd32617', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 33, 33, 'እጁንም በኀጢአት መሥዋዕት ራስ ላይ ይጭናል፤ የሚቃጠልም መሥዋዕት በሚታረድበት ስፍራ ለኀጢአት መሥዋዕት ያርዳታል።'),
  ('36c31400-c459-54b5-a051-281041a07d12', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 34, 34, 'ካህኑም ከኀጢአት መሥዋዕት ደም በጣቱ ወስዶ ለሚቃጠል መሥዋዕት በሚሆነው መሠዊያ ቀንዶች ላይ ያደርገዋል፤ ደሙንም ሁሉ ከመሠዊያው በታች ያፈስሰዋል።'),
  ('1d2cde4d-c20b-5781-a2df-9198a943d751', 'fd8f4b9f-cd85-5c79-a946-4007b4487591', '4d4a7080-ed28-5f1c-a9d5-2c4f1c10d120', 35, 35, 'ስቡ ሁሉ ለደኅንነት መሥዋዕት ከታረደው የበግ ጠቦት ላይ እንደሚወሰድ ስብዋን ሁሉ ይወስዳሉ፤ ካህኑም ለእግዚአብሔር በእሳት በተቃጠለው ቍርባን ላይ በመሠዊያው ላይ ይጨምረዋል። ካህኑም ስለ ሠራው ኀጢአት ያስተሰርይለታል፤ ኀጢአቱም ይሰረይለታል።'),
  ('67c72425-723f-549e-a2f0-fe794195a013', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 1, 1, '“አንድ ሰው ቢበድል፥ የሚያምለውንም ቃል ቢሰማ፥ ምስክርም ሆኖ አንድ ነገር አይቶ እንደ ሆነ፥ ወይም ዐውቆ እንደ ሆነ ያነን ባይናገር በደሉን ይሸከማል፤'),
  ('9a8a89d8-f806-56c2-ae9f-1140534ec0d2', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 2, 2, 'ርኩስ ነገርን፥ የሞተውን፥ አውሬ የነከሰውን፥ ወይም የበከተ፥ ወይም የሚንቀሳቀስ የእንስሳን በድን የነካ፥ ከእርሱም ያነሣ ሰው ቢኖር፤'),
  ('fd803cc1-408f-5506-a2fd-30b07e7f76c7', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 3, 3, 'ወይም ርኩስነቱን ሳያውቅ ርኩስን ሰው ቢነካ፥ በማናቸውም ርኵሰት ቢረክስ፥ ነገሩ በታወቀ ጊዜ በደል ይሆንበታል።'),
  ('108e6032-fc44-5b62-a681-39b42308117d', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 4, 4, 'ሰው ሳያስብ ክፉን ወይም መልካምን ያደርግ ዘንድ ሳያስብ በከንፈሩ ተናግሮ ቢምል፥ ሳያስብ የማለውም ከዚህ ባንዱ ነገር ቢሆን፥ በታወቀው ጊዜ ከዚህ ነገር በአንዱ በደለኛ ይሆናል።'),
  ('1284c209-9b6a-5c1a-afa2-41d9add2ece9', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 5, 5, 'ከእነዚህ ነገሮች በአንዲቱ በደለኛ ቢሆን፥ የሠራውን ኀጢአት ይናዘዛል።'),
  ('76005c22-a408-5700-aa10-39291bdb3573', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 6, 6, 'እግዚአብሔርን ስለ መበደሉና ስለ ሠራው ኀጢአት ከበጎቹ ነውር የሌለባትን እንስት በግ ወይም ከፍየሎች እንስት ፍየል ያመጣል፤ ካህኑም ስለ ኀጢአቱ ያስተሰርይለታል፤ ኀጢአቱም ይሰረይለታል።'),
  ('2477a35c-b5ab-5204-a917-ae953c7209bb', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 7, 7, '“ስለ ሠራው ኀጢአት የበግ መግዣ ገንዘብ በእጁ ባይኖረው ግን፥ ሁለት ዋኖሶች ወይም ሁለት የርግብ ግልገሎች፥ አንዱን ለኀጢአት መሥዋዕት ሁለተኛውንም ለሚቃጠል መሥዋዕት፥ ለእግዚአብሔር ያቀርባል። ወደ ካህኑም ያመጣቸዋል፤'),
  ('88d591cc-be6f-5a47-ab63-d50af40b0c6e', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 8, 8, 'ካህኑም አስቀድሞ ለኀጢአት መሥዋዕት የሆነውን ያቀርባል፤ ራሱንም ከአንገቱ ይቆለምመዋል፤ ነገር ግን አይቈርጠውም።'),
  ('273025cc-f8a8-58d4-a7ea-30aba3e7895e', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 9, 9, 'ከኀጢአቱም መሥዋዕት ደም በመሠዊያው ግድግዳ ላይ ይረጨዋል፤ የተረፈውንም ደም ከመሠዊያው በታች ያንጠፈጥፋል፤ እርሱ የኀጢአት መሥዋዕት ነውና።'),
  ('e47bb06a-1532-5607-ad8e-dece22200dc9', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 10, 10, 'እንደ ሥርዐቱም ሁለተኛውን ለሚቃጠል መሥዋዕት ያዘጋጀዋል። ካህኑም ስለ ሠራው ኀጢአት ያስተሰርይለታል፤ ኀጢአቱም ይሰረይለታል።'),
  ('86cacbbb-9352-5725-a7a7-403314bc878a', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 11, 11, '“ሁለት ዋኖሶች ወይም ሁለት የርግብ ግልገሎች ለማምጣት ገንዘብ በእጁ ባይኖረው፥ ስለ ሠራው ኀጢአት የኢፍ መስፈሪያ ዐሥረኛ ክፍል መልካም የስንዴ ዱቄት ለኀጢአት መሥዋዕት ያቀርባል፤ የኀጢአት መሥዋዕት ነውና ዘይት አያፈስስበትም፤ ዕጣንም አይጨምርበትም።'),
  ('bce1ab8c-9263-5ab7-aa6d-5a63346ea7ff', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 12, 12, 'ወደ ካህኑም ያመጣዋል፤ ካህኑም ስለ መታሰቢያው ለእርሱ እፍኝ ሙሉ ይዘግናል፤ ለእግዚአብሔርም በእሳት በተቃጠለው ቍርባን ላይ በመሠዊያው ላይ ይጨምረዋል፤ እርሱም የኀጢአት መሥዋዕት ነው።'),
  ('da785275-e218-573b-ab82-c5c3c4bdcec2', '9468567c-9157-5600-a994-897d42265679', '9d14bfc3-8e55-5c8d-ab04-0046f2f1d898', 13, 13, 'ካህኑም ከእነዚያ በአንዳቸው ስለ ሠራው ኀጢአት ያስተሰርይለታል፤ ኀጢአቱም ይቅር ይባልለታል። የተረፈውም እንደ እህሉ ቍርባን ለካህኑ ይሆናል።”'),
  ('dec8896d-0488-5155-a9ff-ced57e191010', '9468567c-9157-5600-a994-897d42265679', '715b22f0-f32e-5ba9-a177-48f4dc9b87a3', 1, 14, 'እግዚአብሔርም ሙሴን እንዲህ ሲል ተናገረው፦'),
  ('47068d85-dde4-50ff-a964-dc9d0776b4fd', '9468567c-9157-5600-a994-897d42265679', '715b22f0-f32e-5ba9-a177-48f4dc9b87a3', 2, 15, '“ሰው ቢዘነጋ፥ ሳያውቅም ለእግዚአብሔር በተቀደሰው በማናቸውም ነገር ኀጢአትን ቢሠራ፥ ለበደል መሥዋዕት ለእግዚአብሔር ከመንጋዉ ነውር የሌለበትን እንደ መቅደሱ ሰቅል ሚዛን በብር ሰቅል የተገመተውን አውራ በግ ለበደል መሥዋዕት ያቀርባል።'),
  ('31e8e722-431a-548e-a020-ded66a95c0d3', '9468567c-9157-5600-a994-897d42265679', '715b22f0-f32e-5ba9-a177-48f4dc9b87a3', 3, 16, 'በተቀደሰ ነገር ላይ ስለ ሠራው ኀጢአት ዕዳ ይከፍላል፤ አምስተኛውንም እጅ ይጨምርበታል፤ ለካህኑም ይሰጠዋል። ካህኑም በበደል መሥዋዕት አውራ በግ ያስተሰርይለታል፤ ኀጢአቱም ይቅር ይባልለታል።'),
  ('3b8b63fd-f4f0-5fff-a6dd-b83537107038', '9468567c-9157-5600-a994-897d42265679', '715b22f0-f32e-5ba9-a177-48f4dc9b87a3', 4, 17, '“ሰው ባለማወቅ ኀጢአት ቢሠራ፥ እግዚአብሔርም፦ አትሥሩ ካላቸው ትእዛዛት አንዲቱን ቢተላለፍ፥ ቢታወቀው፥ ኀጢአት ስለሆነችበትም ንስሓ ቢገባ፥'),
  ('c83e6976-69b0-5e52-aa1a-cd66779e53b8', '9468567c-9157-5600-a994-897d42265679', '715b22f0-f32e-5ba9-a177-48f4dc9b87a3', 5, 18, 'ነውር የሌለበትን በሰቅል የተገመተውን አውራ በግ ከመንጋው ለበደል መሥዋዕት ወደ ካህኑ ያመጣዋል፤ ካህኑም ሳያውቅ ስለ ሳተው ስሕተት ያስተሰርይለታል፤ ኀጢአቱም ይቅር ይባልለታል።'),
  ('8bb8c113-716d-5ad0-a863-aaf1c4700088', '9468567c-9157-5600-a994-897d42265679', '715b22f0-f32e-5ba9-a177-48f4dc9b87a3', 6, 19, 'እርሱ በእግዚአብሔር ፊት ንስሓ ገብቶአልና።”'),
  ('a3cddefc-1489-58f7-a281-1aa3fe74515f', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'e3de8d2f-e9fb-5eff-ad0b-2260cf22f2f3', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ሲል ተናገረው፦'),
  ('efd79448-e1e2-5d7b-ac10-04497ee797c7', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'e3de8d2f-e9fb-5eff-ad0b-2260cf22f2f3', 2, 2, '“ሰው ኀጢአትን ቢሠራ፥ የእግዚአብሔርንም ትእዛዝ ቸል ቢል፥ ያኖረበትን አደራ ወይም የኅብረትን ገንዘብ ወስዶ ባልንጀራውን ቢክድ፥ ወይም ቢቀማ፥ ወይም በባልንጀራው ላይ ግፍ ቢሠራ፥'),
  ('0c57768e-a02b-5fd1-ac8d-550ec718a141', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'e3de8d2f-e9fb-5eff-ad0b-2260cf22f2f3', 3, 3, 'ወይም የጠፋውን ነገር ቢያገኝ፥ ስለዚህም ቢዋሽ፥ ሰው ኀጢአትን ለመሥራት ከሚያደርጋቸው ከእነዚህ ነገሮች ሁሉ በአንዲቱ በሐሰት ቢምል፥'),
  ('d4663c9b-0997-54cc-ae63-87f5b842fd59', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'e3de8d2f-e9fb-5eff-ad0b-2260cf22f2f3', 4, 4, 'እርሱ ቢበድልና ከዚህ በኋላ ንስሓ ቢገባ፥ በቅድሚያ የወሰደውን፥ ወይም በዐመፅና በግፍ የተቀበለውን፥ ወይም የተሰጠውን አደራ፥ ወይም ጠፍቶ ያገኘውን፥'),
  ('51802c5e-c075-59d8-a162-a5d86fbf24b6', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'e3de8d2f-e9fb-5eff-ad0b-2260cf22f2f3', 5, 5, 'ወይም በሐሰት የማለበትን ነገር ቢመልስ፥ በሙሉ ይመልስ፤ ከዚያም በላይ አምስተኛውን ክፍል ጨምሮ የበደሉን መሥዋዕት በሚያቀርብበት ቀን ለባለ ገንዘቡ ይስጠው።'),
  ('d95f26b8-307a-5c8d-afbd-38e47279fd71', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'e3de8d2f-e9fb-5eff-ad0b-2260cf22f2f3', 6, 6, 'ስለ በደል መሥዋዕትም ከመንጋው ነውር የሌለበትን፥ ዋጋው እንደ በደሉ የተገመተውን አውራ በግ ለእግዚአብሔር ያምጣ።።'),
  ('565ae216-efbf-5dea-a88f-dced31753c07', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'e3de8d2f-e9fb-5eff-ad0b-2260cf22f2f3', 7, 7, 'ካህኑም በእግዚአብሔር ፊት ያስተሰርይለታል፤ ስለዚያም ስለ አደረገው በደል ሁሉ ይቅር ይባልለታል።”'),
  ('e188d542-7140-5763-a3b4-302cfcfcd15f', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'de61d14e-6c83-5e9d-abbc-1b2069adbace', 1, 8, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('03ed978d-c02c-5d37-a8e4-2e3d78789e95', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'de61d14e-6c83-5e9d-abbc-1b2069adbace', 2, 9, '“አሮንንና ልጆቹን እንዲህ ብለህ እዘዛቸው፦ የሚቃጠለው የመሥዋዕቱ ሕግ ይህ ነው፤ የመሠዊያው እሳት በላዩ እየነደደች እስኪነጋ ትተዉታላችሁ።'),
  ('0c4d712c-8321-5ad6-a2f7-8b2182aecc76', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'de61d14e-6c83-5e9d-abbc-1b2069adbace', 3, 10, 'ካህኑም የተልባ እግር ቀሚስና የተልባ እግር ሱሪ በሰውነቱ ላይ ይለብሳል፤ በመሠዊያውም ላይ የሚቃጠለውን መሥዋዕት እሳቱ ከበላው በኋላ አመዱን አንሥቶ በመሠዊያው አጠገብ ያፈስሰዋል።'),
  ('fce94a67-5614-5496-a980-c988a23a2f49', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'de61d14e-6c83-5e9d-abbc-1b2069adbace', 4, 11, 'ልብሱንም ያወልቃል፤ ሌላም ልብስ ይለብሳል፤ አመዱንም ተሸክሞ ከሰፈሩ ንጹሕ ወደ ሆነ ስፍራ ወደ ውጭ ያወጣዋል።'),
  ('40b80299-30b8-5231-a652-77eba9e849b2', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'de61d14e-6c83-5e9d-abbc-1b2069adbace', 5, 12, 'እሳቱም በመሠዊያው ላይ ዘወትር ይነድዳል፤ አይጠፋም፤ ካህኑም ማለዳ ማለዳ ዕንጨት ያቃጥልበታል፤ የሚቃጠለውንም መሥዋዕት በዚያ ላይ ይረበርባል፤ በዚያም የደኅንነትን መሥዋዕት ስብ ያቃጥላል።'),
  ('e5236c0e-5f9e-5f38-a3a8-dfe675760c99', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'de61d14e-6c83-5e9d-abbc-1b2069adbace', 6, 13, 'ዘወትር በመሠዊያው ላይ እሳት ይነድዳል፤ አይጠፋም።'),
  ('f4109ac8-de81-5bf3-ae02-fbce8b2e05db', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'f72554dc-abc3-5ef3-a3a8-b72a42b72097', 1, 14, '“የአሮን ልጆች በእግዚአብሔር ፊት በመሠዊያው ፊት ለፊት የሚያቀርቡት የመሥዋዕት ሥርዐት ይህ ነው።'),
  ('c6654d91-01de-5f1b-ada1-2396808d69e9', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'f72554dc-abc3-5ef3-a3a8-b72a42b72097', 2, 15, 'ካህኑም ከእህሉ ቍርባን መልካሙን የስንዴ ዱቄት ከዘይት ጋር እፍኝ ሙሉ፥ ደግሞም በእህሉ ቍርባን ላይ ያለውን ዕጣን ሁሉ ያነሣል፤ ለእግዚአብሔርም በጎ መዓዛ ያለው የመታሰቢያ ቍርባን እንዲሆን ለመታሰቢያ ነውና በመሠዊያው ላይ ይጨምረዋል።'),
  ('921151a2-3efd-57c1-a2c8-33bcb48288cf', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'f72554dc-abc3-5ef3-a3a8-b72a42b72097', 3, 16, 'ከእርሱም የተረፈውን አሮንና ልጆቹ ይበሉታል፤ ቂጣ ሆኖ በተቀደሰው ስፍራ ይበላል፤ በምስክሩ ድንኳን ዙሪያ ባለው አደባባይ ይበሉታል።'),
  ('390330a0-7984-5ea2-a4d8-6b8704702159', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'f72554dc-abc3-5ef3-a3a8-b72a42b72097', 4, 17, 'በእርሾ ቦክቶ አይጋገርም። ከእግዚአብሔር መሥዋዕት የሰጠኋቸው ዕድል ፈንታ ይህ ነው፤ እርሱም እንደ ኀጢአትና እንደ በደል መሥዋዕት ቅዱሰ ቅዱሳን ነው።'),
  ('12c6620d-0d89-5517-a530-3922020f1437', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'f72554dc-abc3-5ef3-a3a8-b72a42b72097', 5, 18, 'ከካህናት ወገን ወንድ ሁሉ ይበላዋል፤ በዘመናችሁ ለዘለዓለም ሕግ ነው። ከሚቃጠለው የእግዚአብሔር መሥዋዕት የሚነካ ሁሉ ቅዱስ ይሆናል።”'),
  ('e11a9c83-bf60-515f-a537-f0976b5f7238', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'f72554dc-abc3-5ef3-a3a8-b72a42b72097', 6, 19, 'እግዚአብሔርም ሙሴን እንዲህ ሲል ተናገረው፦'),
  ('f0ff9d11-d7a5-597d-a2ae-7c285b3f78db', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'f72554dc-abc3-5ef3-a3a8-b72a42b72097', 7, 20, '“እርሱን በቀባህበት ቀን ለእግዚአብሔር የሚያቀርቡት የአሮንና የልጆቹ መባ ይህ ነው። የኢፍ መስፈርያ ዐሥረኛ ክፍል መልካሙን ዱቄት እኩሌታውን በጥዋት፥ እኩሌታውንም በማታ ለዘወትር መሥዋዕት ያቀርባሉ።'),
  ('797c4c0f-c69f-502a-a9b9-ef491d50ae77', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'f72554dc-abc3-5ef3-a3a8-b72a42b72097', 8, 21, 'ከዘይት ጋር በምጣድ ላይ ያደርጉታል፤ ለውሰውም ያገቡታል፤ ለእግዚአብሔር በጎ መዓዛ እንዲሆን የሚፈተት መሥዋዕት ነው።'),
  ('864d04d0-fb08-5a3b-a69c-cad4ed4e8b4e', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'f72554dc-abc3-5ef3-a3a8-b72a42b72097', 9, 22, 'ከልጆቹም በእርሱ ፋንታ የተቀባው ካህን ያቀርበዋል። ለዘለዓለም ሥርዐት ነው፤ ሁልጊዜም ይደረጋል።'),
  ('5435f2ab-f410-5678-aea9-51a71ed6f72e', 'e44846bd-7a13-5d78-aadd-30838fd88245', 'f72554dc-abc3-5ef3-a3a8-b72a42b72097', 10, 23, 'ካህናትም የሚያቀርቡት የእህል ቍርባን ሁሉ ፈጽሞ ይቃጠላል፤ ከእርሱም አንዳች አይበላም።”'),
  ('18882cb0-fd67-5b1a-a786-a8fb69885b8f', 'e44846bd-7a13-5d78-aadd-30838fd88245', '6c34dfed-1179-59ef-aa8e-e0766174d584', 1, 24, 'እግዚአብሔርም ሙሴን እንዲህ ሲል ተናገረው፦'),
  ('6af16aea-690c-51fe-a3e0-0158cff4631d', 'e44846bd-7a13-5d78-aadd-30838fd88245', '6c34dfed-1179-59ef-aa8e-e0766174d584', 2, 25, '“አሮንንና ልጆቹን እንዲህ ብለህ ንገራቸው፦ የኀጢአት መሥዋዕት ሕግ ይህ ነው፤ የሚቃጠል መሥዋዕት በሚታረድበት ስፍራ የኀጢአቱ መሥዋዕት በእግዚአብሔር ፊት ይታረዳል፤ እርሱም ቅዱሰ ቅዱሳን ነው።'),
  ('cf0acc20-9866-5ada-a362-ee817edb3b56', 'e44846bd-7a13-5d78-aadd-30838fd88245', '6c34dfed-1179-59ef-aa8e-e0766174d584', 3, 26, 'የሚሠዋው ካህን ይበላዋል፤ በምስክሩ ድንኳን ዙሪያ በአለው አደባባይ በተቀደሰ ስፍራ ይበሉታል።'),
  ('7019118b-d845-5b48-a70b-af2622cb16bc', 'e44846bd-7a13-5d78-aadd-30838fd88245', '6c34dfed-1179-59ef-aa8e-e0766174d584', 4, 27, 'ሥጋውን የሚነካ ሁሉ ቅዱስ ይሆናል፤ ማናቸውም ልብስ ደም ቢረጭበት የተረጨበትን በተቀደሰ ስፍራ ያጥቡታል።'),
  ('831b3c0d-b0d2-55c4-a0c9-fea11dbdc071', 'e44846bd-7a13-5d78-aadd-30838fd88245', '6c34dfed-1179-59ef-aa8e-e0766174d584', 5, 28, 'የሚቀቀልበትን ሸክላ ይሰብሩታል፤ በናስም ዕቃ ቢቀቀል ይፈገፍጉታል፤ በውኃም ያጥቡታል።'),
  ('fe99b789-d78f-585a-a3d4-6bf674c6180e', 'e44846bd-7a13-5d78-aadd-30838fd88245', '6c34dfed-1179-59ef-aa8e-e0766174d584', 6, 29, 'ከካህናት ወገን የሆነ ወንድ ሁሉ ከእርሱ ይበላል፤ እርሱም ቅዱሰ ቅዱሳን ነው።'),
  ('6c14b742-5984-5397-a188-6dd8a990e88c', 'e44846bd-7a13-5d78-aadd-30838fd88245', '6c34dfed-1179-59ef-aa8e-e0766174d584', 7, 30, 'ነገር ግን በመቅደሱ ውስጥ ለማስተስረያ ይሆን ዘንድ ከደሙ ወደ ምስክሩ ድንኳን የሚገባው የኀጢአት መሥዋዕት ሁሉ አይበላም፤ በእሳት ይቃጠላል።'),
  ('b50e03fe-df7d-5278-a4c7-2717fedd5eb4', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'a635429f-f37e-5a26-aaa9-39debc53b1ce', 1, 1, '“የበደል መሥዋዕት ሕግ ይህ ነው፤ ቅዱሰ ቅዱሳን ነው።'),
  ('d416d0d0-de06-560b-a67f-87a49164b9c6', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'a635429f-f37e-5a26-aaa9-39debc53b1ce', 2, 2, 'የሚቃጠለውን መሥዋዕት በሚያርዱበት ስፍራ የበደሉን መሥዋዕት በግ በዚያ ያርዱታል፤ ደሙንም በመሠዊያው ላይ በዙሪያው ይረጩታል።'),
  ('40279f8c-4b23-51e0-a2b6-51203ee5fed9', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'a635429f-f37e-5a26-aaa9-39debc53b1ce', 3, 3, 'ስቡንም ሁሉ፥ ላቱንም፥ የሆድ ዕቃውንም የሚሸፍነውን ስብ ሁሉ፥ በአንጀቱም ላይ ያለውን ስብ፤'),
  ('08b66f22-c88f-5bda-a591-a8cee2cda92c', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'a635429f-f37e-5a26-aaa9-39debc53b1ce', 4, 4, 'ሁለቱንም ኵላሊቶች፥ በእነርሱም ላይና በጎድኑ አጠገብ ያለውን ስብ፥ በጉበቱም ላይ ያለውን መረብ ከኵላሊቶቹ ጋር ካህኑ ይለያል።'),
  ('3cfa1758-fb7a-505c-a29a-520d90d9af17', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'a635429f-f37e-5a26-aaa9-39debc53b1ce', 5, 5, 'ካህኑም ለእግዚአብሔር የእሳት ቍርባን እንዲሆን በመሠዊያው ላይ ይጨምረዋል፤ እርሱም የበደል መሥዋዕት ነው።'),
  ('47a6eb6a-3fea-543e-acc8-b558b74c6b9d', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'a635429f-f37e-5a26-aaa9-39debc53b1ce', 6, 6, 'ከካህናት ወገን የሆነ ወንድ ሁሉ ይበላዋል፤ በተቀደሰ ስፍራም ይበሉታል፤ ቅዱሰ ቅዱሳን ነው።'),
  ('ac42569f-4e5c-53c5-a0a6-d876b0c2f846', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'a635429f-f37e-5a26-aaa9-39debc53b1ce', 7, 7, 'የኀጢአት መሥዋዕት እንደ ሆነ እንዲሁ የበደል መሥዋዕት ነው፤ ለሁለቱ አንድ ሕግ ነው፤ በእነርሱ የሚያስተሰርይ ካህን ይወስደዋል።'),
  ('fa646da3-6107-5c11-ae4e-b679023ad8c4', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'a635429f-f37e-5a26-aaa9-39debc53b1ce', 8, 8, 'የሰውን የሚቃጠል መሥዋዕት የሚያቀርብ ካህን ያቀረበው የሚቃጠለው መሥዋዕት ቍርበት ለዚያው ካህን ይሆናል።'),
  ('e11d16ec-65e8-525a-af6a-b48157c67153', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'a635429f-f37e-5a26-aaa9-39debc53b1ce', 9, 9, 'በእቶን የተጋገረው የእህል ቍርባን ሁሉ፥ በመቀቀያም ወይም በምጣድ የበሰለው ሁሉ ለሚያቀርበው ካህን ይሆናል።'),
  ('bb20139c-fb71-5e6d-a0dd-a50521b1ec02', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'a635429f-f37e-5a26-aaa9-39debc53b1ce', 10, 10, 'በዘይትም የተለወሰው ወይም የደረቀው የእህል ቍርባን ሁሉ ለአሮን ልጆች ሁሉ ይሆናል፤ ለእያንዳንዱም እኩል ይሆናል።'),
  ('63b7f931-4ba2-5406-ad73-ed579bbcaa74', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '336dec21-b4da-5c86-a94b-bc17490af926', 1, 11, '“ለእግዚአብሔር የሚያቀርቡት የደኅንነት መሥዋዕት ሕግ ይህ ነው።'),
  ('cd45d53f-e17c-539b-a08f-6d1876f90a6c', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '336dec21-b4da-5c86-a94b-bc17490af926', 2, 12, 'ለምስጋና ቢያቀርበው፥ ከምስጋናው መሥዋዕት ጋር በዘይት የተለወሰ የቂጣ እንጎቻ፥ በዘይትም የተቀባ ስስ ቂጣ፥ በዘይትም የተለወሰ መልካም የስንዴ ዱቄት ያቀርባል።'),
  ('0b564c25-85c0-56ae-a3a2-5873ad18b518', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '336dec21-b4da-5c86-a94b-bc17490af926', 3, 13, 'ለምስጋና የሚሆነውን የደኅንነት መሥዋዕት በአቀረበ ጊዜ እርሾ ያለበትን ኅብስት ያቀርባል።'),
  ('c22c0122-c5a3-5905-a0f6-4fa044eb5eba', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '336dec21-b4da-5c86-a94b-bc17490af926', 4, 14, 'ከቍርባኑም ሁሉ የእግዚአብሔርን ድርሻ ከእነርሱ አንዱን ያነሣል። እርሱም የደኅንነትን መሥዋዕት ደም ለሚረጨው ካህን ይሆናል።'),
  ('81ba8f01-e08f-5408-a0f9-561ff3b5a5ac', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '336dec21-b4da-5c86-a94b-bc17490af926', 5, 15, '“ለምስጋና የሚሆነው የደኅንነት መሥዋዕት ሥጋም ለእርሱ ነው፤ በሚቀርብበትም ቀን ይበሉታል፤ ከእርሱ እስከ ነገ ምንም አያተርፉም።'),
  ('584c333e-5d78-5f7c-a469-b0b9e79b4d13', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '336dec21-b4da-5c86-a94b-bc17490af926', 6, 16, 'የቍርባኑም መሥዋዕት የስእለት ወይም የፈቃድ ቢሆን፥ መሥዋዕቱ በሚቀርብበት ቀን ይብሉት፤ ከእርሱም የቀረውን በነጋው ይብሉት፤'),
  ('0ad8c270-3a33-565f-a798-c1d3c2567eb0', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '336dec21-b4da-5c86-a94b-bc17490af926', 7, 17, 'ከመሥዋዕቱም ሥጋ እስከ ሦስተኛው ቀን የሚቈየውን በእሳት ያቃጥሉታል።'),
  ('20f0e428-e9c1-5301-a57e-cd2856f242af', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '336dec21-b4da-5c86-a94b-bc17490af926', 8, 18, 'በሦስተኛው ቀን ከደኅንነት መሥዋዕት ሥጋ ቢበላ፥ አይሠምርም፤ ላቀረበው ሰው የተጠላ ይሆንበታል እንጂ ቍርባን ሆኖ አይቈጠርለትም፤ ከእርሱም የበላ ሰው ኀጢአቱን ይሸከማል።'),
  ('5fb4c31e-7419-5cff-a531-859ef89a8e24', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '336dec21-b4da-5c86-a94b-bc17490af926', 9, 19, '“ርኩስ ነገር የሚነካውን ሥጋ አይብሉት፤ በእሳት ያቃጥሉት እንጂ። ንጹሕ የሆነ ሰው ሁሉ ግን ከሥጋው ይብላ።'),
  ('6918b6d4-225b-58ba-abd0-59319085de2c', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '336dec21-b4da-5c86-a94b-bc17490af926', 10, 20, 'ኀጢአት ሳለባት፥ ለእግዚአብሔር ከሆነው ከደኅንነት መሥዋዕት ሥጋ የበላች ሰውነት፥ ያች ሰውነት ከሕዝብዋ ተለይታ ትጥፋ።'),
  ('d69b187a-677a-5256-a9ad-5407b4e12325', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '336dec21-b4da-5c86-a94b-bc17490af926', 11, 21, 'ከርኩስ ሁሉ፥ ወይም ከረከሰው ሰው፥ ወይም ንጹሕ ካልሆነው እንስሳ የነካች ሰውነት፥ ለእግዚአብሔር ከሆነው ከደኅንነት መሥዋዕት ሥጋ ብትበላ፥ ያች ሰውነት ከሕዝብዋ ተለይታ ትጥፋ።”'),
  ('45266547-fd0b-5bbf-a766-4dbc9b20d716', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '8a467c8b-75c5-5243-aea6-a61ea4dc2085', 1, 22, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('f726ff07-6a4d-5a54-ab2c-7cd99aac01dc', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '8a467c8b-75c5-5243-aea6-a61ea4dc2085', 2, 23, '“የእስራኤልን ልጆች እንዲህ ብለህ ተናገራቸው፦ የበሬ ወይም የበግ ወይም የፍየል ስብ ከቶ አትብሉ።'),
  ('9a05e6bf-3477-55f7-a5e6-feb07683e8a2', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '8a467c8b-75c5-5243-aea6-a61ea4dc2085', 3, 24, 'የሞተውን ስብ፥ አውሬ የሰበረውንም ስብ ለሌላ ተግባር አድርጉት፤ እናንተ ግን አትብሉት፤'),
  ('4faf6ca2-a722-5122-a64d-fe9a1a7a65ed', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '8a467c8b-75c5-5243-aea6-a61ea4dc2085', 4, 25, 'ለእግዚአብሔር በእሳት ከሚቀርበው ከእንስሳ ስብ የሚበላ ሁሉ ያች የበላች ሰውነት ከሕዝብዋ ተለይታ ትጥፋ።'),
  ('d351f7c1-cf73-5314-a31a-3d78980b6306', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '8a467c8b-75c5-5243-aea6-a61ea4dc2085', 5, 26, 'በመኖሪያዎቻችሁ ሁሉ የወፍ ወይም የእንስሳ ደም ቢሆን አትብሉ።'),
  ('a6fceb02-b0f4-59ff-a7a7-930e48a93f53', '8d10538e-01cf-59d6-abfb-f74c38808ca5', '8a467c8b-75c5-5243-aea6-a61ea4dc2085', 6, 27, 'ደም የምትበላ ሰውነት ሁሉ ያች ሰውነት ከሕዝብዋ ተለይታ ትጥፋ።”'),
  ('5865b9db-570d-5d33-abef-de9bbd88a133', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'eb6224a6-3fb9-5a5e-a143-cdb518c368a4', 1, 28, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('fc7cbaf6-dff8-5459-a67c-e81cc69cf158', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'eb6224a6-3fb9-5a5e-a143-cdb518c368a4', 2, 29, '“የእስራኤልን ልጆች እንዲህ ብለህ ተናገራቸው፦ ለእግዚአብሔር የደኅንነት መሥዋዕት የሚያቀርብ ሰው ቍርባኑን ለእግዚአብሔር ከደኅንነቱ መሥዋዕት ያመጣል።'),
  ('f83e5431-66cc-52e8-a43e-34dca28c8540', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'eb6224a6-3fb9-5a5e-a143-cdb518c368a4', 3, 30, 'የእርሱ እጆች ለእግዚአብሔር የእሳቱን ቍርባን ያመጣሉ፤ ፍርምባውን በእግዚአብሔር ፊት ቍርባን ያቀርብ ዘንድ በጉበቱ ላይ ያለውን መረብና የፍርምባውን ስብ ያመጣል።'),
  ('84622a5d-f6cb-5f76-a6f3-48af9a2b4a5f', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'eb6224a6-3fb9-5a5e-a143-cdb518c368a4', 4, 31, 'ካህኑም ስቡን በመሠዊያው ላይ ይጨምረው፤ ፍርምባውም ለአሮንና ለልጆቹ ይሁን።'),
  ('febc264a-eeff-57e1-ae6c-cbab4dd4f456', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'eb6224a6-3fb9-5a5e-a143-cdb518c368a4', 5, 32, 'ከደኅንነት መሥዋዕታችሁ ቀኝ ወርቹን ለማንሣት ቍርባን እንዲሆን ለካህኑ ትሰጡታላቸሁ።'),
  ('39519449-dadf-5db7-a3a3-2fdf106b5250', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'eb6224a6-3fb9-5a5e-a143-cdb518c368a4', 6, 33, 'ከአሮንም ልጆች የደኅንነትን መሥዋዕት ደሙንና ስቡን ለሚያቀርብ ለእርሱ ቀኝ ወርቹ እድል ፈንታው ይሆናል።'),
  ('cb4830c1-a382-5659-a458-9b44b935fde2', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'eb6224a6-3fb9-5a5e-a143-cdb518c368a4', 7, 34, 'ፍርምባውንና የቀኝ ወርቹን ከእስራኤል ልጆች ከደኅንነት መሥዋዕታቸው ወስጄአለሁ፤ ለካህኑ ለአሮንና ለልጆቹም ለዘለዓለም ሕግ እንዲሆን ከእስራኤል ልጆች ዘንድ ሰጥቼአቸዋለሁ።”'),
  ('861515a4-bf4d-52ca-ab6b-2b4d936f57d8', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'eb6224a6-3fb9-5a5e-a143-cdb518c368a4', 8, 35, 'እግዚአብሔርን በክህነት ያገለግሉት ዘንድ በተቀቡበት ቀን ለእግዚአብሔር ከሆነ ከእሳት ቍርባን የአሮንና የልጆቹ ሕግ ይህ ነው።'),
  ('26078034-57b0-531b-a8da-2e09acfe0356', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'eb6224a6-3fb9-5a5e-a143-cdb518c368a4', 9, 36, 'ለልጅ ልጃቸው ለዘለዓለም ሕግ እንዲሆን በቀባቸው ቀን የእስራኤል ልጆች ይሰጡአቸው ዘንድ እግዚአብሔር ያዘዘው ይህ ነው።'),
  ('e955d1d8-d267-5bd5-abe5-49e5a2ab32c6', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'eb6224a6-3fb9-5a5e-a143-cdb518c368a4', 10, 37, 'የሚቃጠል መሥዋዕትና የእህል ቍርባን፥ የኀጢአትና የበደል መሥዋዕት፥ የቅድስናና የደኅንነት መሥዋዕት ሕግ ይህ ነው።'),
  ('878d0a01-264e-5231-a262-0fa410d14489', '8d10538e-01cf-59d6-abfb-f74c38808ca5', 'eb6224a6-3fb9-5a5e-a143-cdb518c368a4', 11, 38, 'እግዚአብሔር በሲና ምድረ በዳ ቍርባናቸውን በእግዚአብሔር ፊት ያቀርቡ ዘንድ ለእስራኤል ልጆች ባዘዘ ጊዜ በሲና ተራራ ለሙሴ ያዘዘው ይህ ነው።'),
  ('5b090a89-54c3-53ea-af9f-dd1551b3fabc', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('baee45cb-e405-547e-a43c-bcdecd984c66', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 2, 2, '“አሮንን፥ ከእርሱም ጋር ልጆቹን፥ ልብሱንም፥ የቅብዐቱንም ዘይት፥ ለኀጢአት መሥዋዕትም የሆነውን ወይፈን፥ ሁለቱንም አውራ በጎች፥ የቂጣውንም እንጀራ መሶብ ውሰድ፤'),
  ('2c610309-0ea3-501b-a641-5851a6a6c18f', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 3, 3, 'ማኅበሩንም ሁሉ ወደ ምስክሩ ድንኳን ደጃፍ ሰብስባቸው።”'),
  ('701c4e26-b341-50ce-a55b-74924559ab6e', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 4, 4, 'ሙሴም እግዚአብሔር እንዳዘዘው አደረገ፤ ማኅበሩንም ሁሉ ወደ ምስክሩ ድንኳን ደጃፍ ሰበሰበ።'),
  ('4bee045e-9cbd-5b47-a638-44de5f985916', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 5, 5, 'ሙሴም ማኅበሩን፥ “እግዚአብሔር ታደርጉ ዘንድ ያዘዘው ነገር ይህ ነው” አላቸው።'),
  ('530e2b1a-2cb9-56f2-a5d4-084cb1ab4011', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 6, 6, 'ሙሴም አሮንንና ልጆቹን አቀረበ፤ በውኃም አጠባቸው።'),
  ('919f384e-f731-5172-a643-0f631c279dec', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 7, 7, 'እጀ ጠባብም አለበሰው፤ በመታጠቂያም አስታጠቀው፤ የበፍታ ቀሚስም አለበሰው፤ ልብሰ መትከፍም ደረበለት፤ በልብሰ መትከፉም አሠራር ላይ በብልሃት በተጠለፈ ቋድ አስታጠቀውና በእርሱ ላይ አሰረው።'),
  ('988fb61f-5d78-599f-a21c-ab0cb3fce60c', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 8, 8, 'ልብሰ እንግድዓውንም በእርሱ ላይ አደረገ፤ በልብሰ እንግድዓውም ላይ የምልክትና የእውነት መገለጫዎችን አኖረበት።'),
  ('3b636af1-7c7e-5a84-aa5b-5dfa1e1ec540', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 9, 9, 'እግዚአብሔርም ሙሴን እንዳዘዘው በራሱ ላይ አክሊል አደረገለት፤ በአክሊሉም ላይ በፊቱ በኩል የተቀደሰውን የወርቅ መርገፍ አደረገ።'),
  ('1d19207c-b483-55c0-a63a-15694072aef3', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 10, 10, 'ሙሴም የቅብዐቱን ዘይት ወሰደ፤ ከእርሱም በመሠዊያው ላይ ሰባት ጊዜ ረጨ፤'),
  ('31cc0920-2a18-5931-afa9-c17cc363871e', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 11, 11, 'ይቀድሳቸውም ዘንድ መሠዊያውንና ዕቃውን ሁሉ፥ የመታጠቢያውን ሰንና መቀመጫውን ቀባ፤ ድንኳኒቱንና ዕቃዋን ሁሉ ቀብቶ ቀደሳቸው።'),
  ('7c88f960-547a-51c4-a616-90eb2eca0059', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 12, 12, 'ከቅብዐቱም ዘይት በአሮን ራስ ላይ አፈሰሰ፤ ቀባው፤ ቀደሰውም።'),
  ('78148ea1-9402-56e9-a0be-1568c6a05781', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 13, 13, 'እግዚአብሔርም ሙሴን እንዳዘዘው ሙሴ የአሮንን ልጆች አቀረበ፤ የበፍታ ቀሚሶችንም አለበሳቸው፤ በመታጠቂያም አስታጠቃቸው፤ አክሊልም ደፋላቸው።'),
  ('311f8fdf-30d5-5603-af3b-a9afd2d3a49d', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 14, 14, 'የኀጢአትንም መሥዋዕት ወይፈን አቀረበ፤ አሮንና ልጆቹም በኀጢአቱ መሥዋዕት ወይፈን ራስ ላይ እጆቻቸውን ጫኑ።'),
  ('1ef8236c-ccaf-5f0a-a106-30b7601d4b4b', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 15, 15, 'አረዱትም፤ ሙሴም ደሙን ወስዶ በጣቱ የመሠዊያውን ቀንዶች ዙሪያ ቀባ፤ መሠዊያውንም አነጻው፤ ደሙንም ከመሠዊያው በታች አፈሰሰው፤ ያስተሰርይለትም ዘንድ ቀደሰው።'),
  ('dd1b1da4-26f8-5c2a-af23-44d4da5204e7', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 16, 16, 'ሙሴም በሆድ ዕቃው ላይ ያለውን ስብ ሁሉ፥ የጉበቱንም መረብ፥ ሁለቱንም ኵላሊቶች፥ ስባቸውንም ወሰደ፤ በመሠዊያውም ላይ ጨመረው።'),
  ('aaff624c-e921-56fc-a9d5-8cbe3764b1df', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 17, 17, 'እግዚአብሔርም ሙሴን እንዳዘዘው ወይፈኑን፥ ቍርበቱንም፥ ሥጋውንም፥ ፈርሱንም ከሰፈሩ ውጭ በእሳት አቃጠለ።'),
  ('cc64fdc3-0e04-578d-a2bd-d3cbf1a31860', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 18, 18, 'ሙሴም ለሚቃጠል መሥዋዕት የሚሆን አውራ በግ አቀረበ፤ አሮንና ልጆቹም በአውራው በግ ራስ ላይ እጆቻቸውን ጫኑ።'),
  ('df3d398e-9030-5f07-a420-984e315d8809', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 19, 19, 'ሙሴም ያን በግ አረደው፤ ደሙንም በመሠዊያው ዙሪያ ረጨው።'),
  ('49d089a5-5df1-5cff-aa86-762d6208ddef', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 20, 20, 'አውራውንም በግ በየብልቱ ቈረጠ፤ ሙሴም ጭንቅላቱን፥ ብልቶቹንም፥ ስቡንም ጨመረ።'),
  ('84984730-6df9-5086-a416-5fba57a61941', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 21, 21, 'የሆድ ዕቃውንና እግሮቹንም በውኃ አጠበ፤ ሙሴም አውራውን በግ ሁሉ በመሠዊያው ላይ ጨመረ፤ ይህ በጎ መዓዛ እንዲሆን የሚቃጠል መሥዋዕት ነበረ፤ እግዚአብሔር ሙሴን እንዳዘዘው ለእግዚአብሔር የእሳት ቍርባን ነበረ።'),
  ('00b3add4-d68f-5232-a2a0-57b8cf0bd337', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 22, 22, 'ሙሴም ለቅድስና የሚሆነውን ሁለተኛውን አውራ በግ አቀረበ፤ አሮንና ልጆቹም በአውራው በግ ራስ ላይ እጆቻቸውን ጫኑ፤'),
  ('7c97546f-981c-5676-aebf-1d8fd1f9926f', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 23, 23, 'አረዱትም። ሙሴም ከደሙ ወስዶ የአሮንን የቀኝ ጆሮውን ጫፍ፥ የቀኝ እጁንም አውራ ጣት፥ የቀኝ እግሩንም አውራ ጣት ቀባው።'),
  ('17cfc474-49c0-53cd-ac7c-145e22b46c0d', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 24, 24, 'የአሮንንም ልጆች አቀረበ፤ ሙሴም የቀኝ ጆሮአቸውን ጫፍ፥ የቀኝ እጃቸውንም አውራ ጣት፥ የቀኝ እግራቸውንም አውራ ጣት ከደሙ ቀባ፤ ሙሴም ደሙን በመሠዊያው ዙሪያ ረጨ።'),
  ('1f90d579-5119-5ee8-afc0-2bcd2e783715', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 25, 25, 'ስቡንና ላቱን፥ በሆድ ዕቃውም ላይ ያለውን ስብ ሁሉ፥ የጉበቱንም መረብ፥ ሁለቱንም ኵላሊቶች፥ ስባቸውንም፥ ቀኝ ወርቹንም ወሰደ፤'),
  ('6e3e1cce-d1f4-560e-aa8f-b3f5e80e84af', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 26, 26, 'በእግዚአብሔር ፊት ካለው የቅድስና መሶብ አንድ የቂጣ እንጎቻ፥ አንድም የዘይት እንጀራ፥ አንድም ስስ ቂጣ ወስዶ በስቡና በቀኝ ወርቹ ላይ አኖራቸው።'),
  ('cb310140-bcaa-53a5-a9fb-e8f8f73c047b', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 27, 27, 'ሁሉንም በአሮንና በልጆቹ እጆች ላይ አደረገ፤ በእግዚአብሔርም ፊት ቍርባንን አቀረበ፤'),
  ('251f4846-dcf3-5640-a255-dc1fd8db519c', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 28, 28, 'ሙሴም ከእጃቸው ተቀብሎ በመሠዊያው በሚቃጠለው መሥዋዕት ላይ አኖረው። በጎ መዓዛ የቅድስና መሥዋዕት ነበረ። እርሱም ለእግዚአብሔር የእሳት ቍርባን ነበረ።'),
  ('728a0ef4-56a0-5430-abff-6f2f90449af7', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 29, 29, 'ሙሴም ከቅድስናው አውራ በግ ፍርምባውን ወስዶ በእግዚአብሔር ፊት ያቀርበው ዘንድ ቈራረጠ። እግዚአብሔር ሙሴን እንዳዘዘው ይህ ለቅድስና ከታረደው አውራ በግ የሙሴ እድል ፈንታ ሆነ።'),
  ('1d9b83cd-5678-5b05-af24-033e63f9079a', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 30, 30, 'ሙሴም ከቅብዐቱ ዘይትና በመሠዊያው ላይ ከአለው ከደሙ ወስዶ በአሮንና በልብሱ ላይ ፥ በልጆቹና በልጆቹ ልብስ ላይ ረጨው፤ አሮንንና ልብሱንም፥ ልጆቹንም፥ የልጆቹንም ልብስ ቀደሰ።'),
  ('72bab3d9-1ed0-5107-a6ed-6e021ea39dd2', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 31, 31, 'ሙሴም አሮንንና ልጆቹን አላቸው፥ “ሥጋውን በምስክሩ ድንኳን ደጃፍ በተቀደሰው ቦታ ቀቅሉ፤ አሮንና ልጆቹ ይብሉት ብሎ እግዚአብሔር እንዳዘዘኝ በዚያ እርሱንና በቅድስናው መሶብ ያለውን እንጀራ ብሉ።'),
  ('55e566f3-bbdf-55fb-a089-4e7f642ef30d', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 32, 32, 'ከሥጋውና ከእንጀራውም የተረፈውን በእሳት አቃጥሉት።'),
  ('a1345d76-ad01-5e95-a1fd-871e100eb916', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 33, 33, 'ሰባት ቀን ይክናችኋልና የክህነታችሁ ቀን እስኪፈጸም ድረስ ሰባት ቀን ከማኅበሩ ድንኳን ደጃፍ አትውጡ።'),
  ('b58ba511-dc51-59ac-add8-6af8831ad334', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 34, 34, 'በዚህ ቀን እንደ ተደረገ ለእናንተ ለማስተስረያ ይደረግ ዘንድ እንዲሁ እግዚአብሔር አዘዘ።'),
  ('b5a3db6c-eba6-581e-a0ab-81f054fc4388', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 35, 35, 'እግዚአብሔር እንዲሁ አዝዞኛልና እንዳትሞቱ በምስክሩ ድንኳን ደጃፍ ሌሊቱንና ቀኑን ሰባት ቀን ተቀመጡ፤ የእግዚአብሔርንም ሥርዐት ጠብቁ፤”'),
  ('13a4536a-542d-50fd-a77e-1583e1fe8496', 'ff6ef6a8-8ab6-527e-af97-275cef5eb31b', '9b4c2e62-76de-5258-a1ff-627b29ff5286', 36, 36, 'አሮንና ልጆቹም እግዚአብሔር ለሙሴ ያዘዘውን ሁሉ አደረጉ።'),
  ('f30a70f3-c424-52c9-aac5-3f21b9a51dfd', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 1, 1, 'በስምንተኛውም ቀን እንዲህ ሆነ፤ ሙሴ አሮንንና ልጆቹን፥ የእስራኤልንም ሽማግሌዎች ጠራ።'),
  ('a55b6362-6342-51de-abd1-ad88a144abc3', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 2, 2, 'ሙሴም አሮንን አለው፥ “ስለ ኀጢአት መሥዋዕት ከመንጋው እንቦሳውን፥ ስለሚቃጠልም መሥዋዕት አውራውን በግ ወስደህ በእግዚአብሔር ፊት አቅርባቸው።'),
  ('9f9a57e4-b69e-5507-a764-88f430937435', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 3, 3, 'የእስራኤልንም ልጆች፦ ለኀጢአት መሥዋዕት አውራ ፍየልን፥ ለሚቃጠልም መሥዋዕት ነውር የሌለባቸውን አንድ ዓመት የሆናቸውን ጥጃና ጠቦትን፥'),
  ('bb06f3ba-0bf3-5c2d-afb9-f74f2720fd7f', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 4, 4, 'ለደኅንነትም መሥዋዕት በሬንና አውራ በግን፥ በዘይትም የተለወሰ የእህልን ቍርባን በእግዚአብሔር ፊት ይሠዉ ዘንድ ውሰዱ፤ ዛሬ እግዚአብሔር ይገለጥላችኋልና ብለህ ንገራቸው።”'),
  ('694c57c1-d115-5ba7-acdb-fb4ded2131a5', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 5, 5, 'ሙሴም ያዘዛቸውን ወደ ምስክሩ ድንኳን ደጃፍ አመጡ፤ ማኅበሩም ሁሉ ቀርበው በእግዚአብሔር ፊት ቆሙ።'),
  ('b0bcda10-de21-5a33-abef-c1b28345bf81', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 6, 6, 'ሙሴም፥ “ታደርጉት ዘንድ እግዚአብሔር ያዘዛችሁ ቃል ይህ ነው፤ የእግዚአብሔርም ክብር ይገለጥላችኋል” አለ።'),
  ('32a72e1f-69f1-57f0-abe7-54c19ae978c0', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 7, 7, 'ሙሴም አሮንን፥ “ወደ መሠዊያው ቀርበህ የኀጢአትህን መሥዋዕትና የሚቃጠለውን መሥዋዕትህን ሠዋ፤ ለራስህና ለወገንህ አስተስርይ፤ እግዚአብሔርም እንዳዘዘ የሕዝቡን ቍርባን አቅርብ፤ አስተስርይላቸውም” አለው።'),
  ('b791256a-e199-512a-a78e-c8d9eaf40392', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 8, 8, 'አሮንም ወደ መሠዊያው ቀርቦ ስለ ራሱ ኀጢአት መሥዋዕት የሆነውን ጥጃ አረደ።'),
  ('a412a488-cf5c-5966-abb4-33a9df6da9b1', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 9, 9, 'የአሮንም ልጆች ደሙን አቀረቡለት፤ ጣቱንም በደሙ ውስጥ ነክሮ የመሠዊያውን ቀንዶች ቀባ፤ ደሙንም ከመሠዊያው በታች አፈሰሰው።'),
  ('31a20507-4b95-5f04-a4c5-6f3557a3735f', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 10, 10, 'እግዚአብሔርም ሙሴን እንዳዘዘው ከኀጢአቱ መሥዋዕት ስቡንና ኵላሊቶቹን፥ የጉበቱንም መረብ በመሠዊያው ላይ ጨመረ።'),
  ('076f52b7-cadb-5e3e-ada3-a19fff1d71d5', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 11, 11, 'ሥጋውንና ቍርበቱንም ከሰፈሩ ውጭ በእሳት አቃጠሉ።'),
  ('e9db60af-9148-5314-ae55-c51b875a1692', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 12, 12, 'የሚቃጠለውንም መሥዋዕት አረደ፤ የአሮንም ልጆች ደሙን አመጡለት፤ እርሱም በመሠዊያው ላይ በዙሪያው ረጨው።'),
  ('97a62c75-4902-5286-a884-f7962a82a7c1', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 13, 13, 'የሚቃጠለውን መሥዋዕት በየብልቱ፥ ራሱንም አመጡለት፤ እርሱም በመሠዊያው ላይ ጨመረው።'),
  ('d45e0324-8789-5732-ad54-83423aa19dd4', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 14, 14, 'የሆድ ዕቃውንና እግሮቹንም በውኃ አጠበ፤ በመሠዊያውም በሚቃጠለው መሥዋዕት ላይ ጨመረው።'),
  ('a3994137-d069-5ac5-a596-c81dcdcb903e', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 15, 15, 'ከዚህም በኋላ የሕዝቡን ቍርባን አቀረበ፤ ስለ ሕዝቡ ለኀጢአት መሥዋዕት የሆነውን ፍየል ወስዶ አረደው፤ አነጻውም፤ እንደ ፊተኛውም ለየው።'),
  ('4c3d9016-d492-58b6-a86a-325a6a799df6', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 16, 16, 'የሚቃጠለውንም መሥዋዕት አቀረበ፤ እንደ ሥርዐቱም አደረገው።'),
  ('18839b3f-b376-5f91-ab1b-e4d41fc14f00', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 17, 17, 'የስንዴውንም መሥዋዕት አቀረበ፤ ከእርሱም እፍኝ ሙሉ ወስዶ በጥዋት ከሚቃጠለው መሥዋዕት ሌላ በመሠዊያው ላይ ጨመረው።'),
  ('214ee6bd-62fd-554c-abce-c9fd048aa603', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 18, 18, 'ስለ ሕዝቡ የሆነውን የደኅንነት መሥዋዕት፥ በሬውንና አውራውን በግ አረደ፤ የአሮንም ልጆች ደሙን አመጡለት፤ በመሠዊያውም ዙሪያ ረጨው፤'),
  ('7bf5fc88-5f80-59d2-a81d-7587dc2ee962', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 19, 19, 'የበሬውንና የአውራውንም በግ ስብ፥ ላቱንም፥ የሆድ ዕቃውንም የሚሸፍነውን ስብ፥ ሁለቱን ኵላሊቶቹንም፥ በላያቸውም ያለውን ስብ፥ የጉበቱንም መረብ አመጡለት።'),
  ('b7993d4a-beb3-57d9-a1fc-742ce97ec4bf', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 20, 20, 'ስቡንም በፍርምባዎቹ ላይ አኖረ፤ ስቡንም በመሠዊያው ላይ ጨመረ፤'),
  ('00c1b551-4f01-5381-ac71-0824cf8e3772', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 21, 21, 'እግዚአብሔርም ሙሴን እንዳዘዘው አሮን ፍርምባዎቹንና ቀኝ ወርቹን በእግዚአብሔር ፊት ለየ።'),
  ('1b87dc1c-44f2-580d-a868-6c7f7db02c85', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 22, 22, 'አሮንም እጆቹን ወደ ሕዝቡ ዘረጋ፤ ባረካቸውም፤ የኀጢአቱን፥ የሚቃጠለውንም፥ የደኅንነቱንም መሥዋዕት ከሠዋ በኋላ ወረደ።'),
  ('05bf3f5d-9c98-5f36-ae92-5d6bb9334449', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 23, 23, 'ሙሴና አሮንም ወደ ምስክሩ ድንኳን ገቡ፤ ወጡም፤ ሕዝቡንም ባረኩ፤ የእግዚአብሔርም ክብር ለሕዝቡ ሁሉ ተገለጠ።'),
  ('2e727665-c6ee-50b8-ab10-e42e5d03bed6', '17c40c9f-3cda-5971-ad63-d06bafbd7165', '20f03085-4e0f-5c4f-affb-1dab94727191', 24, 24, 'እሳትም ከእግዚአብሔር ዘንድ ወጣ፤ በመሠዊያውም ላይ የሚቃጠለውን መሥዋዕት፥ ስቡንም በላ፤ ሕዝቡም ሁሉ አይተው ተደነቁ፤ በግምባራቸውም ወደቁ።'),
  ('0f3214b8-3768-5a47-acbf-ccfd75223ab9', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'eb32263a-ce43-5095-ae8c-3f4caa0a4e52', 1, 1, 'የአሮንም ልጆች ናዳብና አብዩድ በየራሳቸው ጥናውን ወስደው እሳት አደረጉበት፤ በላዩም ዕጣን ጨመሩበት፤ በእግዚአብሔርም ፊት እግዚአብሔር ያላዘዛቸውን ሌላ እሳት አቀረቡ።'),
  ('55cd715e-4acf-5911-adfe-8fa90a754b7f', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'eb32263a-ce43-5095-ae8c-3f4caa0a4e52', 2, 2, 'እሳትም ከእግዚአብሔር ዘንድ ወጥቶ በላቸው፤ በእግዚአብሔርም ፊት ሞቱ።'),
  ('9bf47124-bdd5-508c-a74b-887cc183842b', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'eb32263a-ce43-5095-ae8c-3f4caa0a4e52', 3, 3, 'ሙሴም አሮንን፥ “እግዚአብሔር፦ ወደ እኔ በሚቀርቡ እመሰገናለሁ፤ በሕዝቡም ሁሉ ፊት እከብራለሁ ብሎ የተናገረው ይህ ነው” አለው፤ አሮንም ደነገጠ።'),
  ('2484275f-3089-5492-a869-df0bf207e13f', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'eb32263a-ce43-5095-ae8c-3f4caa0a4e52', 4, 4, 'ሙሴም የአሮንን አጎት የአዚሔልን ልጆች ሚሳዴንና ኤልሳፍንን ጠርቶ፥ “ሂዱ፤ ወንድሞቻቸሁን ከመቅደሱ ፊት አንሥታችሁ ከሰፈር ወደ ውጭ ውሰዱአቸው” አላቸው።'),
  ('fe2fc8a2-7f09-5e1a-a74c-82b05c25f46d', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'eb32263a-ce43-5095-ae8c-3f4caa0a4e52', 5, 5, 'እነርሱም ገብተው አነሡአቸው፤ ሙሴም እንዳለ በልብሳቸው ከሰፈር ወደ ውጭ ወሰዱአቸው።'),
  ('f71d8973-80d1-5c54-a766-5f00a49bd475', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'eb32263a-ce43-5095-ae8c-3f4caa0a4e52', 6, 6, 'ሙሴም አሮንን፥ ልጆቹንም አልዓዛርንና ኢታምርን፥ “እንዳትሞቱ፥ በማኅበሩም ላይ ሁሉ ቍጣ እንዳይወርድ ራሳችሁን አትንጩ፤ ልብሳችሁንም አትቅደዱ፤ እግዚአብሔር ስላቃጠላቸው ማቃጠል ግን ወንድሞቻችሁ የእስራኤል ቤት ሁሉ ያልቅሱ።'),
  ('9a1650b1-b894-5812-ad7b-f2555823244e', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'eb32263a-ce43-5095-ae8c-3f4caa0a4e52', 7, 7, 'የእግዚአብሔር የቅብዐት ዘይት በላያችሁ ነውና እንዳትሞቱ ከምስክሩ ድንኳን ደጃፍ አትውጡ” አላቸው። ሙሴም እንዳዘዛቸው አደረጉ።'),
  ('9913eb88-6c1d-5fb7-aa10-849d28b93eaf', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 1, 8, 'እግዚአብሔርም አሮንን እንዲህ ብሎ ተናገረው፦'),
  ('0aa8e0c0-84b4-5d74-a99f-bd9a8cb7666e', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 2, 9, '“እንዳትሞቱ ወደ ምስክሩ ድንኳን ስትገቡ ወይም ወደ መሠዊያው ስትቀርቡ አንተና ልጆችህ የወይን ጠጅና የሚያሰክርን ነገር ሁሉ አትጠጡ፤ ይህም ለልጅ ልጃችሁ የዘለዓለም ሥርዐት ይሆናል፤'),
  ('0177959e-7747-5ac5-ad88-2497434bd68a', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 3, 10, 'በተቀደሰውና በአልተቀደሰው፥ በርኩሱና በንጹሑም መካከል ትለያላችሁ፤'),
  ('b36d0f17-cf38-5a31-a40f-1e0d61cdc286', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 4, 11, 'እግዚአብሔርም በሙሴ እጅ የነገራቸውን ሥርዐት ሁሉ ለእስራኤል ልጆች ታስተምራቸዋለህ።”'),
  ('e21f2b33-f632-5ecf-ae72-d57131b97ea2', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 5, 12, 'ሙሴም አሮንን፥ የተረፉለትን ልጆቹን አልዓዛርንና ኢታምርን አላቸው፥ “ቅዱሰ ቅዱሳን ነውና ለእግዚአብሔር ከሆነው ከእሳት ቍርባን የቀረውን የስንዴውን ቍርባን ውሰዱ፤ ቂጣም አድርጋችሁ በመሠዊያው አጠገብ ብሉት፤'),
  ('3641a1cd-fcf0-5692-a267-5af0cc4778be', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 6, 13, 'እግዚአብሔርም እንዲህ አዝዞኛልና፥ ለእግዚአብሔር ከሆነው ከእሳት ቍርባን ለአንተም፥ ለልጆችህም የተሰጠ ሥርዐት ነውና በቅዱስ ስፍራ ትበሉታላችሁ።'),
  ('00885932-7fab-5d65-a9fd-161131fe7ef3', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 7, 14, 'እነዚህም ከእስራኤል ልጆች ከደኅንነት መሥዋዕቶች ለአንተና ለልጆችህ ሥርዐት እንዲሆኑ ስለ ተሰጡ፥ የመሥዋዕቱን ፍርምባና ወርች አንተ፥ ከአንተ ጋርም ልጆችህ፥ ቤተሰብህም ተለይቶ በንጹሕ ስፍራ ትበላላችሁ።'),
  ('ae9a0543-65c5-5323-ac07-a07e482a38fb', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 8, 15, 'የመሥዋዕቱን ወርችና ፍርምባ በእግዚአብሔር ፊት ከሚቀርበው መሥዋዕት የእሳት ቍርባን ከሆነው ስብ ጋር ያመጣሉ፤ እግዚአብሔር እንዳዘዘ ለአንተ፥ ከአንተ ጋርም ለወንዶችና ሴቶች ልጆችህ የዘለዓለም ሥርዐት ይሆናል።”'),
  ('a97a6fb5-2fc2-5850-a655-165fabc0165d', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 9, 16, 'ሙሴም የኀጢአቱን መሥዋዕት ፍየል እጅግ ፈለገው፤ በፈለገውም ጊዜ እነሆ ተቃጥሎ ነበር፤ ሙሴም የቀሩትን የአሮንን ልጆች አልዓዛርንና ኢታምርን ተቈጣቸው፤ እንዲህም አላቸው፦'),
  ('78722def-6338-5319-a7e4-fc0e561b2a55', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 10, 17, '“ቅዱሰ ቅዱሳን ነውና፥ የሕዝቡንም ኀጢአት እንድትሸከሙ፥ በእግዚአብሔርም ፊት እንድታስተሰርዩላቸው ይህን ትበሉ ዘንድ ለእናንተ ሰጥቶታልና ስለ ምን የኀጢአትን መሥዋዕት በቅዱሱ ስፍራ አልበላችሁም?'),
  ('6552bee7-ed4a-550a-a8a0-04117b0c14dd', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 11, 18, 'እነሆ፥ ደሙን ወደ መቅደስ ውስጥ አላገባችሁትም፤ እኔ እንደታዘዝሁ በቅዱስ ስፍራ ውስጥ ትበሉት ዘንድ ይገባችሁ ነበር።”'),
  ('5a520b60-d8fa-562d-a9ea-ee89c617f923', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 12, 19, 'አሮንም ሙሴን ተናገረው እንዲህም አለው፥ “እነሆ፥ ዛሬ የኀጢአታቸውን መሥዋዕት፥ የሚቃጠለውንም መሥዋዕታቸውን በእግዚአብሔር ፊት በለዩ ጊዜ፥ ይህች አገኘችኝ፤ ዛሬም የኀጢአቱን መሥዋዕት እበላ ዘንድ በእግዚአብሔር ፊት መልካም አይደለም።”'),
  ('0d15d3e4-d1d5-51af-a63d-d5be63d8ebd6', '3f43ac8c-c2be-50b3-abca-6908d89546b0', 'b99c2ff3-7c7c-514d-a003-0e45ecde0925', 13, 20, 'ሙሴም ሰማ፤ ደስም አለው።'),
  ('4867ee37-a982-51e1-a25e-dc3b074ce559', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 1, 1, 'እግዚአብሔርም ሙሴንና አሮንን እንዲህ ብሎ ተናገራቸው፦'),
  ('3184eb09-4c9b-528a-a8cb-d4f2088fee51', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብላችሁ ንገሩአቸው፦ በምድር ካሉት እንስሳት ሁሉ የምትበሉአቸው እንስሳት እነዚህ ናቸው።')
